function shortUnit(unit){return {Pacote:'pct',Dúzia:'dz','Meia Dúzia':'½ dz',Caixa:'cx',Unidade:'un',Vidro:'vidro',Pote:'pote',kg:'kg',Litro:'L',Sacola:'sacola'}[unit]||unit.toLowerCase();}
function familyKey(p){return [E.normalize(p.baseName||p.name),p.category,p.type||'',stockGroupOf(p)].join('|');}
function presentations(p){return model.data.products.filter(x=>familyKey(x)===familyKey(p)).sort((a,b)=>(a.weight||0)-(b.weight||0)||a.unit.localeCompare(b.unit));}
function pillLabel(p){if(p.unit==='Pacote'||p.unit==='Pote'||p.unit==='Vidro'){if(p.weight)return p.weight>=1000?E.quantity(p.weight/1000)+' kg':E.quantity(p.weight)+' g';if(p.volume)return E.quantity(p.volume)+' ml';}return p.unit==='Caixa'&&p.contentCount?'Caixa '+E.quantity(p.contentCount):p.unit;}
function productDot(p){const reference=stockRatio(p);if(reference.ratio>=.5)return '';const percent=Math.round(reference.ratio*100),label=p.stock<=0?'Sem estoque':'Estoque abaixo de 50%';return '<span class="stock-low-eye" role="img" aria-label="'+escape(label+' · '+percent+'% restante')+'">'+icon('eye')+'</span>';}

function stockSignal(p){
 if(p.stock<=0)return{className:'neutral',symbol:'dot',label:'Sem estoque'};
 if(p.stock<=p.min)return{className:'low',symbol:'down',label:'Estoque baixo'};
 const latest=model.data.movements.find(m=>m.productId===p.id&&m.kind!=='initial');
 return latest&&latest.after>latest.before?{className:'added',symbol:'up',label:'Entrada registrada'}:{className:'neutral',symbol:'dot',label:'Sem nova entrada'};
}

function productCards(stockMode){
 const products=productList(stockMode);if(!products.length)return '<div class="empty"><strong>Nenhum produto cadastrado</strong><p>Adicione produtos ao estoque geral.</p>'+btn('new-product','Adicionar produto','link')+'</div>';
 if(stockMode)return '<div class="product-grid stock-grid">'+products.map(p=>{const signal=stockSignal(p);return btn('stock-product','<span class="card-heading"><span class="name">'+escape(titleName(p.name))+'</span>'+productDot(p)+'</span><span class="description">'+escape(stockCardDescription(p))+'</span><span class="stock-balance"><span class="stock-number tabular">'+E.quantity(p.stock)+'</span>'+(signal.symbol==='up'?'<span class="stock-signal added" role="img" aria-label="Entrada registrada">↑</span>':'')+'</span>','product-card stock-card'+(p.stock<=0?' is-empty':''),{id:p.id});}).join('')+'</div>';
 const groups=new Map();products.forEach(p=>{const key=familyKey(p);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);});const available=[...groups.values()].filter(variants=>variants.some(v=>v.stock>0));if(!available.length)return '<div class="empty"><strong>Nenhum produto disponível</strong><p>Reponha o estoque para voltar a vender.</p>'+btn('nav','Ver Estoque','link',{page:'Estoque'})+'</div>';return '<div class="product-grid selling-grid">'+available.map(variants=>{const offered=variants.some(v=>v.stock>0)?variants.filter(v=>v.stock>0):variants,p=offered.slice().sort((a,b)=>a.price-b.price)[0],worst=variants.reduce((a,b)=>stockRatio(a).ratio<=stockRatio(b).ratio?a:b);return '<article class="product-card selling-card'+(variants.every(v=>v.stock<=0)?' is-empty':'')+'">'+btn('sell-product','<span class="card-heading"><span class="name">'+escape(titleName(p.name))+'</span>'+productDot(worst)+'</span><span class="price tabular"><small class="price-meta">'+escape(sellingCardDescription(p))+'</small>'+E.money(p.price)+'</span>','card-body',{id:p.id},variants.every(v=>v.stock<=0))+'</article>';}).join('')+'</div>';
}
