 return products.length?products.map(p=>btn('pick-catalog-product','<span><strong class="search-product-name">'+escape(titleName(p.name))+productDot(p)+'</strong><small>'+escape(E.description(p))+'</small></span><span class="tabular">'+(searchMode==='stock'?E.quantity(p.stock)+' '+shortUnit(p.unit):E.money(p.price))+'</span>','list-row',{id:p.id})).join(''):'<p class="muted">Nenhum produto encontrado.</p>';
