function startProduct(id){if(!id&&!stockCreationTarget)return stockPicker('product');formError='';numericTouched.clear();productNamePrefix='';closeNumberPad();const p=id&&model.product(id);productForm=p?{name:p.baseName||p.name,category:p.category,editId:id,more:false,variants:[{...p,priceInput:cashInput(p.price),costInput:cashInput(p.cost),stockInput:String(p.stock),minInput:String(p.min)}]}:{name:'',category:'Outros',editId:null,more:false,variants:[newVariant(E.classify(''))]};productForm.stockGroup=p?stockGroupOf(p):stockCreationTarget;productForm.stockGroupChosen=!!p||stockTargetExists(stockCreationTarget);page='Produto';render();window.scrollTo(0,0);}
