 return'<div class="subview">'+header(f.editId?'Editar produto':'Novo produto','cancel-product')+identification+'<div id="product-presentations">'+productPresentationPanels()+'</div>'+(f.editId?'':btn('add-variant',icon('plus')+'<span>Outra opção de venda</span>','link-row add-sale-option'))+'<div id="form-error" class="'+(formError?'error':'')+'" role="alert">'+escape(formError)+'</div><div class="product-form-actions">'+btn('cancel-product','Cancelar','choice product-cancel')+btn('save-product','Salvar produto','success')+'</div></div>';
