 return'<div class="weight-options" role="group" aria-label="Pesos, formatos e valores de '+escape(saleDisplayName(p))+'">'+options.map(v=>{
  const index=draft.items.findIndex(i=>i.productId===v.id),line=index>=0?draft.items[index]:null,chosen=index===draft.active,qty=line?E.number(line.rawQty):0;
  const label=weightLabel(v);
  return '<div class="weight-option-line">'+btn('select-sale-weight','<span class="weight-left"><strong>'+escape(label)+'</strong>'+(qty>0?'<small>'+E.quantity(qty)+' '+E.unitLabel(v.unit,qty)+' na venda</small>':'')+'</span><span class="weight-right"><strong>'+E.money(v.price)+'</strong>'+((chosen||qty>0)?icon(chosen?'check':'down'):'')+'</span>','weight-pill'+(chosen?' selected':'')+(qty>0?' included':'')+(v.stock<=0?' unavailable':''),{id:v.id},v.stock<=0)+(line&&(qty>0||chosen)?btn('remove-item',icon('trash'),'red weight-remove',{index}):showRemove?'<span class="weight-remove-spacer" aria-hidden="true"></span>':'')+'</div>';
 }).join('')+'</div>';
