function openModal(title,body,kind,data,footer){
 modal={kind,data};dialog.setAttribute('data-kind',kind||'');
 const bottomBack=['weather','scope','event-detail','mg-detail','consumption','consumption-detail','client','client-detail','appearance','brain','day-summary','fair-finish','fair-activity','event-load','voice','credit-other','credit-terms','receivables','receivable-receipt'].includes(kind)||/^(advisor|agent-|workflow|store)/.test(String(kind||'')),registered=kind==='story'&&data&&data.pending===false;
 if(bottomBack){body=body.replace(/<button\b[^>]*data-action="close-modal"[^>]*>[\s\S]*?<\/button>/g,'');if(!footer)footer=btn('close-modal',icon('back')+'<span>Voltar</span>','sheet-back');}
 dialog.toggleAttribute('data-bottom-back',bottomBack);dialog.toggleAttribute('data-no-close',bottomBack||registered);
 const reviewSheet=kind==='cart'||kind==='checkout',heading=(bottomBack||registered||reviewSheet?'':btn('close-modal',icon('close'),'dialog-close'))+'<h2 id="dialog-title"'+(kind==='event'?' tabindex="-1" autofocus':'')+'>'+(kind==='event-detail'?'<span class="event-store-icon" aria-hidden="true">'+icon('store')+'</span><span>'+escape(title)+'</span>':escape(title))+'</h2>',footerLabel=kind==='movement'?'Ações do estoque':kind==='restock'?'Reposição do estoque':kind==='calculator'?'Ações da calculadora':bottomBack?'Ações da janela':'Finalização da venda';
 dialog.innerHTML='<div class="checkout-header">'+heading+'</div><div class="dialog-content" id="checkout-scroll">'+body+'</div>'+(footer?'<div class="checkout-footer" role="region" aria-label="'+footerLabel+'">'+footer+'</div>':'')+'<aside id="dialog-number-pad" class="modal-number-pad" hidden aria-label="Teclado numérico"></aside>';
 if(!dialog.open)dialog.showModal();dialog.dispatchEvent(new CustomEvent('territorio:sheet',{bubbles:true,detail:{kind:kind||'',title:String(title||''),data:data||null}}));
}

function closeModal(skipSaleCapture){if(['credit-other','credit-terms'].includes(modal?.kind)&&pendingCheckout){window.TerritorioReceivables.back();return;}const isOption=modal&&saleOptionKinds.has(modal.kind);if(isOption&&!skipSaleCapture)captureSaleOptionInputs();if(modal&&['cart','checkout'].includes(modal.kind))pendingCheckout=null;if(modal?.kind==='stock-peek')stockUnderlayExiting=true;dialog.close();closeNumberPad();modal=null;movement=null;if(isOption){/* Keep the closed visual intact until the native exit settles; the next open replaces it. */clearSaleOptionFlags();if(page==='Venda')render();}}
