function scopedData(){const sales=model.data.sales.filter(s=>matchesSource(s,dataScope)),ids=new Set(sales.flatMap(s=>s.items.map(i=>model.product(i.productId)?.id||i.productId))),customers=new Set(sales.map(s=>s.customerId));return {sales,products:model.data.products.filter(p=>dataScope==='all'||ids.has(p.id)),clients:model.data.clients.filter(c=>dataScope==='all'||customers.has(c.id)),events:model.data.events.filter(e=>['all','events'].includes(dataScope)||e.id===dataScope),expenses:model.data.expenses.filter(e=>matchesSource(e,dataScope)),movements:model.data.movements.filter(m=>dataScope==='all'||sales.some(s=>s.id===m.saleId)||m.eventId===dataScope)};}
function saleCSVRows(sales){return[['Venda','Data','Local','Status','Cliente','Município','Bairro','UF','Subtotal','Desconto','Valor da venda','Receita líquida','Custo dos produtos','Resultado bruto','Destino do QR','QR lido em'],...sales.map(s=>[s.id,s.date,saleSourceName(s),s.status==='returned'?'Devolvida':'Concluída',s.customerName||(model.data.clients.find(c=>c.id===s.customerId)||{}).name||'',s.customerCity,s.customerNeighborhood,s.customerUF,(s.subtotal/100).toFixed(2),(s.discount/100).toFixed(2),(s.total/100).toFixed(2),((s.status==='completed'?s.total:0)/100).toFixed(2),((s.status==='completed'?s.cost:0)/100).toFixed(2),((s.status==='completed'?s.total-s.cost:0)/100).toFixed(2),s.qrTitle||'',s.qrReadAt||''])];}
function rawCSVRows(kind){const d=scopedData(),cash=x=>((x||0)/100).toFixed(2);switch(kind){
 case'sales':return saleCSVRows(d.sales);
 case'items':return[['Venda','Data','Local','Status','Produto','Apresentação','Unidade','Quantidade','Preço unitário','Custo unitário','Valor dos itens','Custo dos itens','Município','Bairro','UF'],...d.sales.flatMap(s=>s.items.map(i=>[s.id,s.date,saleSourceName(s),s.status,titleName(i.name),i.description,i.unit,i.qty,cash(i.price),cash(i.cost),cash(i.total),cash(i.costTotal),s.customerCity,s.customerNeighborhood,s.customerUF]))];
 case'payments':return[['Venda','Data','Local','Status','Método','Valor'],...d.sales.flatMap(s=>s.payments.map(p=>[s.id,s.date,saleSourceName(s),s.status,p.method,cash(p.amount)]))];
 case'returns':return[['Venda','Data da venda','Data da devolução','Local','Valor devolvido','Produtos'],...d.sales.filter(s=>s.status==='returned').map(s=>[s.id,s.date,s.returnedAt||'',saleSourceName(s),cash(s.total),s.items.map(i=>titleName(i.name)+' · '+i.description+' · '+E.quantity(i.qty)).join(' | ')])];
 case'products':return[['Produto','Categoria','Nome-base','Tipo','Formato','Estoque de cadastro'],...[...new Map(d.products.map(p=>[familyKey(p),p])).values()].map(p=>[titleName(p.name),p.category,titleName(p.baseName||p.name),p.type,p.format,stockGroupName(stockGroupOf(p))])];
 case'presentations':return[['ID','Produto','Categoria','Tipo','Formato','Apresentação','Unidade','Peso (g)','Volume (ml)','Conteúdo da caixa','Estoque','Mínimo','Preço','Custo','Estoque de cadastro'],...d.products.map(p=>[p.id,titleName(p.name),p.category,p.type,p.format,E.description(p),p.unit,p.weight||'',p.volume||'',p.contentCount||'',p.stock,p.min,cash(p.price),cash(p.cost),stockGroupName(stockGroupOf(p))])];
 case'movements':return[['Movimento','Data','Produto','Apresentação','Tipo','Unidade','Quantidade','Saldo anterior','Novo saldo','Venda','Motivo'],...d.movements.map(m=>[m.id,m.date,titleName(m.name),model.product(m.productId)?E.description(model.product(m.productId)):'',m.kind,m.unit,m.qty,m.before,m.after,m.saleId,m.note])];
 case'clients':return[['ID','Nome','Município','Bairro','UF','Compras','Total em compras'],...d.clients.map(c=>{const sales=d.sales.filter(s=>s.status==='completed'&&s.customerId===c.id);return[c.id,c.name,c.city,c.neighborhood,c.uf,sales.length,cash(sales.reduce((n,s)=>n+s.total,0))];})];
 case'events':return[['ID','Evento','Local','Início','Fim','Horário inicial','Horário final','Status','Vendas','Receita','Custo','Despesas','Resultado'],...d.events.map(e=>{const sales=d.sales.filter(s=>s.status==='completed'&&s.scope===e.id),revenue=sales.reduce((n,s)=>n+s.total,0),cost=sales.reduce((n,s)=>n+s.cost,0),expense=d.expenses.filter(x=>x.scope===e.id).reduce((n,x)=>n+x.amount,0);return[e.id,e.name,e.place,e.start,e.end,e.from,e.until,e.status,sales.length,cash(revenue),cash(cost),cash(expense),cash(revenue-cost-expense)];})];
 case'expenses':return[['ID','Data','Local','Descrição','Valor'],...d.expenses.map(x=>[x.id,x.date,scopeName(x.scope),x.title,cash(x.amount)])];
 default:throw Error('Planilha não encontrada.');
}}
function csvRows(kind){return rawCSVRows(kind).map(row=>row.map(value=>typeof value==='string'?E.displayUnits(value):value));}
function generalRows(){return rawGeneralRows().map(row=>row.map(value=>typeof value==='string'?E.displayUnits(value):value));}
function rawGeneralRows(){const d=scopedData(),records=[],cash=x=>((x||0)/100).toFixed(2),headers=['Registro','ID','Data','Local','Status','Cliente','Município','Bairro','UF','Produto','Apresentação','Unidade','Quantidade','Preço unitário','Custo unitário','Subtotal','Desconto','Receita líquida','Custo total','Pagamento','Valor pago','Saldo anterior','Novo saldo','Descrição','Início','Fim','Despesa','Resultado bruto','Destino do QR','QR lido em','Tipo de cliente','Documento','Avisos autorizados','Autorização registrada em','Finalidade da despesa'];
 const add=o=>records.push(headers.map(k=>o[k]??''));
 d.sales.forEach(s=>{const common={'Data':s.date,'Local':saleSourceName(s),'Status':s.status,'Cliente':s.customerName||(model.data.clients.find(c=>c.id===s.customerId)||{}).name||'','Município':s.customerCity||'','Bairro':s.customerNeighborhood||'','UF':s.customerUF||'','Tipo de cliente':s.customerType||(model.data.clients.find(c=>c.id===s.customerId)||{}).personType||'','Documento':s.customerDocument||''};add({...common,Registro:'Venda',ID:s.id,Subtotal:cash(s.subtotal),Desconto:cash(s.discount),'Receita líquida':s.status==='completed'?cash(s.total):'0.00','Custo total':s.status==='completed'?cash(s.cost):'0.00','Resultado bruto':s.status==='completed'?cash(s.total-s.cost):'0.00','Destino do QR':s.qrTitle||'','QR lido em':s.qrReadAt||''});s.items.forEach(i=>add({...common,Registro:'Item vendido',ID:s.id,Produto:titleName(i.name),'Apresentação':i.description,Unidade:i.unit,Quantidade:i.qty,'Preço unitário':cash(i.price),'Custo unitário':cash(i.cost)}));s.payments.forEach(p=>add({...common,Registro:'Pagamento',ID:s.id,Pagamento:p.method,'Valor pago':cash(p.amount)}));});
 d.products.forEach(p=>add({Registro:'Apresentação',ID:p.id,Produto:titleName(p.name),'Apresentação':E.description(p),Unidade:p.unit,'Preço unitário':cash(p.price),'Custo unitário':cash(p.cost),'Novo saldo':p.stock,Local:stockGroupName(stockGroupOf(p)),Descrição:p.category}));
 d.movements.forEach(m=>add({Registro:'Movimento',ID:m.id,Data:m.date,Local:m.eventId?scopeName(m.eventId):m.saleId?scopeName((d.sales.find(s=>s.id===m.saleId)||{}).scope):stockGroupName(stockGroupOf(model.product(m.productId))),Produto:titleName(m.name),Unidade:m.unit,Quantidade:m.qty,'Saldo anterior':m.before,'Novo saldo':m.after,Descrição:m.kind+' · '+m.note}));
 d.clients.forEach(c=>add({Registro:'Cliente',ID:c.id,Cliente:c.name,'Município':c.city,Bairro:c.neighborhood,UF:c.uf,'Tipo de cliente':c.personType,Documento:c.document||'','Avisos autorizados':c.noticeConsent?'Sim':'Não','Autorização registrada em':c.noticeConsentAt||''}));d.events.forEach(e=>add({Registro:'Evento',ID:e.id,Local:e.name,Status:e.status,Descrição:e.place,Início:e.start,Fim:e.end}));d.expenses.forEach(x=>add({Registro:'Despesa',ID:x.id,Data:x.date,Local:scopeName(x.scope),Descrição:x.title,Despesa:cash(x.amount),'Finalidade da despesa':x.category||'Não classificada'}));model.data.contacts.filter(x=>matchesSource(x,dataScope)).forEach(x=>add({Registro:'Abordagens',ID:x.id,Data:x.date,Local:scopeName(x.scope),Quantidade:x.count}));return[headers,...records];
}
function saveCatalog(file){if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Escolha uma foto PNG, JPEG ou WebP.');if(file.size>3*1024*1024)return toast('Escolha uma foto de até 3 MB para salvar neste navegador.');const title=document.getElementById('catalog-title').value.trim()||model.data.settings.businessName,reader=new FileReader();reader.onerror=()=>toast('Não foi possível abrir a foto.');reader.onload=()=>{const previous=model.data.catalog;model.data.catalog={...previous,title,image:String(reader.result),fileName:file.name,mime:file.type,updatedAt:new Date().toISOString()};if(!persist()){model.data.catalog=previous;return toast('Não foi possível salvar a foto. Escolha um arquivo menor.');}render();toast('Catálogo salvo.');};reader.readAsDataURL(file);}
async function shareCatalogImage(channel){const c=model.data.catalog;if(!c)return;const bytes=Uint8Array.from(atob(c.image.split(',')[1]),x=>x.charCodeAt(0)),blob=new Blob([bytes],{type:c.mime}),file=typeof File!=='undefined'?new File([blob],c.fileName,{type:c.mime}):null,text=(c.title||model.data.settings.businessName)+' · '+model.data.settings.producerName;if(file&&navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({title:c.title,text,files:[file]});}catch(e){if(e.name!=='AbortError')toast('Não foi possível compartilhar. Use Baixar catálogo.');}return;}downloadCatalog();const url=channel==='whatsapp'?'https://wa.me/?text='+encodeURIComponent(text):'mailto:?subject='+encodeURIComponent(c.title)+'&body='+encodeURIComponent(text+'\nSegue meu catálogo de produtos.');const a=document.createElement('a');a.href=url;if(channel==='whatsapp'){a.target='_blank';a.rel='noopener noreferrer';}document.body.appendChild(a);a.click();a.remove();toast('Catálogo baixado. Anexe a foto à sua mensagem.');}
function downloadCatalog(){const c=model.data.catalog;if(!c)return;const a=document.createElement('a');a.href=c.image;a.download=c.fileName;document.body.appendChild(a);a.click();a.remove();}
const INVENTORY_SITE='https://www.visitecarangolamg.com.br';
const CATALOG_PHOTOS=window.TERRITORIO_ASSETS.catalogPhotos;
let studio={mode:'single',photos:[],story:'',prompt:'Organize um catálogo com nomes, apresentações e preços. Não invente dados que não estejam nas fotos ou no texto.',drafts:[],busy:false,source:'',title:''};
function safePublicURL(value){try{const u=new URL(String(value||'').trim());return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch(e){return '';}}
function isInventoryEvent(event){return !!event&&(event.qrKind==='site'||E.normalize(event.name).includes('inventario'));}
function catalogGroups(){const groups=new Map();model.data.products.forEach(p=>{const key=familyKey(p);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p);});return [...groups.values()].map(group=>group.sort((a,b)=>(a.weight||0)-(b.weight||0)||a.price-b.price));}
function catalogText(){const c=model.data.catalog;return[c.title,c.story,...catalogGroups().map(group=>titleName(group[0].name)+'\n'+group.map(p=>weightLabel(p)+': '+E.money(p.price)+(p.stock<=0?' · indisponível':'')).join(' | '))].join('\n\n');}
function catalogQRText(){const c=model.data.catalog,lines=[c.title],groups=catalogGroups();for(const group of groups){const line=titleName(group[0].name)+': '+group.map(p=>weightLabel(p)+' '+E.money(p.price)).join(' / ');if(unescape(encodeURIComponent(lines.concat(line).join('\n'))).length>650){lines.push('Catálogo completo com fotos: peça o PDF ao produtor.');break;}lines.push(line);}return lines.join('\n');}
function storyDestination(scopeId){const e=model.data.events.find(e=>e.id===scopeId),c=model.data.catalog;if(isInventoryEvent(e))return{kind:'site',payload:safePublicURL(e.website)||INVENTORY_SITE,title:'Visite Carangola',url:safePublicURL(e.website)||INVENTORY_SITE};const url=safePublicURL(c.publicUrl);return{kind:'catalog',payload:url||catalogQRText(),title:c.title,url};}
function brandMark(){const name=model.data.catalog.title||model.data.settings.businessName||'Seu negócio';return '<span class="martins-logo" aria-label="'+escape(name)+'"><b>'+escape(initials(name))+'</b><small>'+escape(name)+'</small></span>';}
function photoIndex(p){const n=E.normalize(p.name);if(p.category==='Cafés')return{Especial:0,Gourmet:1,Tradicional:2}[p.type]??0;if(/banana/.test(n))return /maca/.test(n)?7:p.unit==='Caixa'?8:3;if(/tilapia/.test(n))return 4;if(/queijo/.test(n))return 5;if(/salame/.test(n))return 6;return null;}
function photoTile(p){const photos=model.data.catalog.photos,own=photos[p.id]||p.photo,other=own||presentations(p).map(v=>photos[v.id]||v.photo).find(Boolean);if(other)return '<div class="catalog-photo"><img src="'+escape(other)+'" alt="Foto de '+escape(titleName(p.name))+'" loading="lazy"></div>';const index=model.data.dataContext?.type==='demo'||model.data.settings.onboarding==='demo'?photoIndex(p):null;if(index===null)return '<div class="catalog-photo" style="display:flex;align-items:center;justify-content:center;background:var(--field);color:var(--muted)">'+icon('box')+'<span class="small">Foto não cadastrada</span></div>';return '<div class="catalog-photo atlas"><img src="'+CATALOG_PHOTOS+'" alt="Embalagem ilustrativa Produtos Martins · '+escape(titleName(p.name))+'" loading="lazy" style="left:-'+index%3*100+'%;top:-'+Math.floor(index/3)*100+'%"></div>';}
function catalogContents(){const c=model.data.catalog;return '<section class="catalog-hero"><div class="story-brand">'+brandMark()+'<div><h3>'+escape(c.title)+'</h3><span class="small">Sabores do campo, perto de você</span></div></div><p class="story-copy">'+escape(c.story)+'</p></section><div class="catalog-product-grid">'+catalogGroups().map(group=>{const p=group[0];return '<article class="catalog-product">'+photoTile(p)+'<div class="catalog-product-body"><h3>'+escape(titleName(p.name))+'</h3><div class="catalog-options">'+group.map(v=>'<div>'+escape([v.format,weightLabel(v)].filter(Boolean).join(' · '))+' <strong>'+E.money(v.price)+'</strong></div>').join('')+'</div>'+(group.every(v=>v.stock<=0)?'<p class="catalog-unavailable">Indisponível no momento</p>':'')+'</div></article>';}).join('')+'</div>';}
const renderedQRCodes=new Map();
function cachedQRCode(payload){const key=String(payload||'');if(renderedQRCodes.has(key)){const value=renderedQRCodes.get(key);renderedQRCodes.delete(key);renderedQRCodes.set(key,value);return value;}const svg=E.qrSVG(payload);renderedQRCodes.set(key,svg);if(renderedQRCodes.size>8)renderedQRCodes.delete(renderedQRCodes.keys().next().value);return svg;}
function storyModal(id){
 const sale=id&&model.data.sales.find(s=>s.id===id),pending=!sale&&recipientPending;if(!sale&&!pending)return;
 const record=sale||pending.summary,destination=storyDestination(sale?sale.scope:scope),payload=sale?.qrPayload||storyPayload(destination,pending),title=sale?.qrTitle||destination.title;
 const body='<div class="story-modal"><div class="qr-section"><button type="button" data-action="qr-zoom" data-id="'+escape(sale?.id||'pending')+'" class="story-qr-button" aria-label="Ampliar QR code">'+cachedQRCode(payload)+'</button><strong class="story-qr-caption">'+escape(title)+'</strong>'+(destination.kind==='catalog'&&!safePublicURL(model.data.catalog.publicUrl)?'<p class="story-qr-hint">Publique seu portfólio online em Catálogo para que este QR abra sua página no celular do cliente.</p>':'')+btn('qr-read',record.qrReadAt||pending?.qrReadAt?'QR code lido ✓':'QR code lido','success qr-read',{id:sale?.id||'pending'})+'<div class="pdf-actions">'+btn('catalog-pdf-options',icon('arrow')+' Enviar PDF','',{sale:sale?.id||''})+btn('catalog-pdf-download',icon('download')+' Baixar PDF')+'</div></div></div>';
 openModal('Conheça Nossa História',body,'story',{id:sale?.id||'',pending:!sale},'<div class="story-footer">'+recipientControls(sale)+'</div>');
}
function catalogPage(){const c=model.data.catalog;return '<div class="subview">'+header('Catálogo','catalog-back')+portfolioPanel()+catalogContents()+'<div class="catalog-tools">'+btn('catalog-whatsapp','Compartilhar no WhatsApp')+btn('catalog-email','Compartilhar por e-mail')+btn('catalog-pdf-options','Enviar catálogo em PDF')+btn('catalog-pdf-download','Baixar PDF')+btn('catalog-complete-download','Baixar catálogo (página)')+btn('studio-open',icon('spark')+' Preparar com fotos')+'</div><details class="panel catalog-settings"><summary>História, links e fotos '+icon('down')+'</summary>'+field('catalog-title','Nome do catálogo',c.title,'placeholder="Nome do seu negócio"')+'<label for="catalog-story">Sua história (3 linhas)</label><textarea id="catalog-story" maxlength="2000">'+escape(c.story)+'</textarea>'+field('catalog-public-url','Link público do catálogo',c.publicUrl||'','type="url" placeholder="https://seusite.com/catalogo"')+field('catalog-website','Site do produtor',model.data.settings.website||'','type="url" placeholder="https://seusite.com"')+field('catalog-instagram','Perfil do Instagram',model.data.settings.instagram||'','type="url" placeholder="https://www.instagram.com/seuperfil/"')+btn('catalog-save-links','Salvar história e links','success modal-action')+'<label class="catalog-upload">'+icon('upload')+' Adicionar uma imagem do catálogo<input id="catalog-upload" type="file" accept="image/png,image/jpeg,image/webp"></label>'+(c.image?'<img class="catalog-image" src="'+escape(c.image)+'" alt="'+escape(c.title)+'"><div class="share-grid">'+btn('catalog-download','Baixar imagem enviada')+btn('catalog-remove','Remover imagem','red')+'</div>':'')+'</details><p class="catalog-illustration-note">Produtos Martins é um exemplo de catálogo. As embalagens ilustrativas foram criadas por IA. Troque pelas fotos e pela história do seu negócio.</p></div>';}
function catalogDocument(){const style=document.querySelector?document.getElementById('legacy-css'):null;const css=style&&style.textContent||'';return '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(model.data.catalog.title)+'</title><style>'+css+'\n:root{--panel:#1c1c1e;--field:#29292b;--text:#fff;--muted:#a5a5ac;--blue:#bfd3e3}body{background:#000;color:var(--text);font-family:system-ui,sans-serif;margin:0}main{max-width:720px;padding:24px;margin:auto}.catalog-photo.atlas img{position:absolute;width:300%;height:300%;max-width:none}.catalog-photo{position:relative;aspect-ratio:1;overflow:hidden}.catalog-product-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.catalog-product{background:#1c1c1e;border-radius:18px;overflow:hidden}.catalog-product-body{padding:14px}.catalog-hero{padding:22px;background:#15372a;border-radius:22px;margin-bottom:16px}.story-copy{white-space:pre-line;line-height:1.6}.story-brand{display:flex;gap:14px;align-items:center}.martins-logo{background:#18483b;color:#f3e6bf;border-radius:14px;padding:10px;display:inline-flex;flex-direction:column;align-items:center}.martins-logo b{font:32px Georgia,serif}.martins-logo small{font-size:8px}img{width:100%;height:100%;object-fit:cover}h3{margin:0 0 8px;font-size:18px}.catalog-options{font-size:13px;line-height:1.8}.catalog-illustration-note{font-size:11px;color:#aaa}@media(min-width:700px){.catalog-product-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}</style><main>'+catalogContents()+'<p class="catalog-illustration-note">Catálogo de exemplo · Fotografias ilustrativas de embalagens criadas por IA.</p></main></html>';}
function completeCatalogDownload(){download('catalogo-produtos-martins.html',catalogDocument(),'text/html;charset=utf-8');toast('Catálogo completo baixado.');}
function saveCatalogDetails(){const c=model.data.catalog,publicUrl=document.getElementById('catalog-public-url').value.trim(),website=document.getElementById('catalog-website').value.trim(),instagram=document.getElementById('catalog-instagram').value.trim();if([publicUrl,website,instagram].some(v=>v&&!safePublicURL(v)))return toast('Use links HTTPS válidos.');Object.assign(c,{title:document.getElementById('catalog-title').value.trim()||model.data.settings.businessName||'Meu catálogo',story:document.getElementById('catalog-story').value.trim(),publicUrl});Object.assign(model.data.settings,{website,instagram});if(!persist())return toast('Não foi possível salvar. Exporte um backup.');render();toast('Catálogo atualizado.');}
async function shareFullCatalog(channel){const c=model.data.catalog;if(c.image)return shareCatalogImage(channel);const url=safePublicURL(c.publicUrl),text=c.title+'\n'+(url||catalogText()),file=typeof File!=='undefined'?new File([catalogDocument()],'catalogo-produtos-martins.html',{type:'text/html'}):null;if(file&&navigator.share&&navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({title:c.title,text:c.title,files:[file]});}catch(e){if(e.name!=='AbortError')toast('Use Baixar catálogo completo para anexar o arquivo.');}return;}if(!url)completeCatalogDownload();const a=document.createElement('a');a.href=channel==='whatsapp'?'https://wa.me/?text='+encodeURIComponent(text):'mailto:?subject='+encodeURIComponent(c.title)+'&body='+encodeURIComponent(text);if(channel==='whatsapp'){a.target='_blank';a.rel='noopener noreferrer';}document.body.appendChild(a);a.click();a.remove();if(!url)toast('Catálogo baixado. Anexe o arquivo à mensagem.');}
function studioPage(){const ready=studio.drafts.length,active=aiProvider(),config=active&&model.data.ai.providers[active.id];return '<div class="subview studio-page">'+header('Produtos por fotografia','studio-back')+'<section class="panel"><div class="choices">'+[['single','Um produto'],['batch','Várias fotos']].map(([mode,label])=>btn('studio-mode',label,'choice'+(mode===studio.mode?' selected':''),{mode})).join('')+'</div><label class="photo-upload">'+icon('upload')+' '+(studio.mode==='single'?'Enviar foto do produto':'Enviar fotos de uma vez')+'<input id="studio-upload" type="file" accept="image/png,image/jpeg,image/webp"'+(studio.mode==='batch'?' multiple':'')+'></label><div class="studio-upload-list">'+studio.photos.map(photo=>'<div><img src="'+escape(photo.image)+'" alt="'+escape(photo.name)+'"><small>'+escape(photo.name)+'</small></div>').join('')+'</div><label for="studio-story">História do produtor</label><textarea id="studio-story" maxlength="2000">'+escape(studio.story)+'</textarea><label for="studio-prompt">Seu pedido</label><textarea id="studio-prompt" maxlength="4000" placeholder="Ex.: Identifique os cafés e monte meu catálogo.">'+escape(studio.prompt)+'</textarea>'+btn('studio-prepare',studio.busy?'Preparando…':config?'Preparar com '+escape(active.name):'Preparar prévia local','success modal-action',null,!studio.photos.length||studio.busy)+'<p class="settings-note">'+(config?'As fotos e o texto serão enviados ao serviço configurado. Revise os dados antes de criar os produtos.':'Sem um serviço de IA conectado, a prévia usa o nome do arquivo e dados já cadastrados. As imagens não são interpretadas automaticamente.')+'</p></section>'+(ready?'<h2 class="section-title">Revisar '+ready+' '+(ready===1?'produto':'produtos')+'</h2><p class="studio-source">'+escape(studio.source)+'</p>'+studio.drafts.map((d,index)=>'<section class="studio-review"><div class="studio-review-heading"><img src="'+escape(studio.photos[d.photoIndex].image)+'" alt="Foto selecionada"><span>'+escape(d.existingId?'Produto já cadastrado · atualizar fotografia':'Novo produto · confira os dados')+'</span></div>'+studioField(index,'name','Nome do produto',d.name,d.existingId?'readonly':'')+(d.existingId?'<p class="settings-note">A fotografia será vinculada ao produto. Valores e estoque serão mantidos.</p>':'<div class="two">'+studioField(index,'priceInput','Preço (R$)',d.priceInput,'inputmode="decimal"')+studioField(index,'stockInput','Quantidade em estoque',d.stockInput,'inputmode="decimal"')+'</div><details><summary>Apresentação e custo '+icon('down')+'</summary><label>Categoria</label><select id="studio-'+index+'-category" data-studio="'+index+'" data-field="category">'+E.CATEGORIES.map(c=>'<option'+(c===d.category?' selected':'')+'>'+escape(c)+'</option>').join('')+'</select><label>Unidade</label><select id="studio-'+index+'-unit" data-studio="'+index+'" data-field="unit">'+['Unidade','Sacola','Pacote','Dúzia','Caixa','kg','Pote','Vidro','Litro'].map(u=>'<option'+(u===d.unit?' selected':'')+'>'+u+'</option>').join('')+'</select><div class="two">'+studioField(index,'weight','Peso em gramas',d.weight||'','inputmode="numeric"')+studioField(index,'format','Formato / preparo',d.format||'')+'</div><div class="two">'+studioField(index,'type','Tipo (se for café)',d.type||'')+studioField(index,'costInput','Custo (R$)',d.costInput,'inputmode="decimal"')+'</div><div class="two">'+studioField(index,'contentCount','Itens por caixa',d.contentCount||'','inputmode="numeric"')+studioField(index,'contentUnit','Unidade do conteúdo',d.contentUnit||'unidades')+'</div>'+studioField(index,'volume','Volume em ml',d.volume||'','inputmode="numeric"')+'</details>')+'</section>').join('')+'<div class="error" id="studio-error" role="status"></div>'+btn('studio-apply',studio.mode==='single'?'Criar produto / salvar fotografia':'Salvar produtos e catálogo','success modal-action'):'')+'</div>';}
function studioField(index,key,label,value,extra){return field('studio-'+index+'-'+key,label,value,'data-studio="'+index+'" data-field="'+key+'" '+(extra||''));}
function readStudioFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Não foi possível abrir '+file.name+'.'));reader.onload=()=>resolve({name:file.name,image:String(reader.result),mime:file.type});reader.readAsDataURL(file);});}
async function uploadStudio(files){studioStockTarget='general';const list=Array.from(files||[]).slice(0,studio.mode==='single'?1:8);if(!list.length)return;if(Array.from(files||[]).length>8)return toast('Envie até 8 fotos por vez.');if(list.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)))return toast('Use fotos PNG, JPEG ou WebP.');if(list.reduce((n,f)=>n+f.size,0)>2*1024*1024)return toast('Use até 2 MB no total para este catálogo.');studio.busy=true;render();try{studio.photos=await Promise.all(list.map(readStudioFile));studio.drafts=[];studio.source='';}catch(e){toast(e.message);}finally{studio.busy=false;render();}}
function photoDraft(info,index){const file=studio.photos[index],name=String(info.name||file.name.replace(/\.[^.]+$/,'').replace(/[_-]/g,' ')).trim().slice(0,120),known=model.data.products.find(p=>E.normalize(p.name)===E.normalize(name)&&(!info.weight||p.weight===+info.weight)&&(!info.unit||p.unit===info.unit)),suggestion=E.classify(name);return{photoIndex:index,existingId:known&&known.id||null,name:known?titleName(known.name):name,category:known?known.category:E.CATEGORIES.includes(info.category)?info.category:suggestion.category,unit:known?known.unit:info.unit||suggestion.unit,type:known?known.type||'':info.type||suggestion.type||'',format:known?known.format||'':info.format||'',weight:known?known.weight||0:+info.weight||0,volume:known?known.volume||0:+info.volume||0,contentCount:known?known.contentCount||0:+info.contentCount||0,contentUnit:known?known.contentUnit||'unidades':info.contentUnit||'unidades',priceInput:known?cashInput(known.price):info.price==null?'':String(info.price),costInput:known?cashInput(known.cost):info.cost==null?'':String(info.cost),stockInput:known?String(known.stock):info.stock==null?'':String(info.stock),minInput:'3'};}
async function prepareStudio(){studioStockTarget='general';if(studio.busy||!studio.photos.length)return;const p=aiProvider(),config=p&&model.data.ai.providers[p.id];studio.busy=true;studio.drafts=[];render();if(!config){studio.drafts=studio.photos.map((photo,index)=>photoDraft({},index));studio.title=model.data.catalog.title;studio.source='Prévia local: nomes dos arquivos e cadastro existente. Complete preço, apresentação e estoque dos produtos novos.';studio.busy=false;render();return;}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const response=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',signal:controller.signal,body:JSON.stringify({task:'catalog-products',provider:p.id,model:config.model,mode:studio.mode,story:studio.story,prompt:studio.prompt,photos:studio.photos.map(photo=>({name:photo.name,image:photo.image})),responseContract:{catalog:{title:'texto',story:'texto'},products:[{photoIndex:0,name:'texto',category:'texto',unit:'Pacote',weight:250,format:'Moído',type:'Especial',price:25,cost:15,stock:0}]}})});if(!response.ok)throw Error('O serviço respondeu com erro '+response.status+'.');const result=await response.json();if(!Array.isArray(result.products)||!result.products.length||result.products.length>8)throw Error('O serviço deve retornar products com até 8 produtos.');if(result.products.some(d=>!d||typeof d.name!=='string'||!d.name.trim()||!Number.isInteger(d.photoIndex)||d.photoIndex<0||d.photoIndex>=studio.photos.length))throw Error('A resposta deve informar um nome e um photoIndex válido para cada produto.');studio.drafts=result.products.map(d=>photoDraft(d,d.photoIndex));studio.title=String(result.catalog&&result.catalog.title||model.data.catalog.title).slice(0,120);if(result.catalog&&typeof result.catalog.story==='string')studio.story=result.catalog.story.slice(0,2000);studio.source='Prévia preparada por '+p.name+'. Preços em reais; quantidades e apresentações precisam da sua revisão.';}catch(e){studio.source=e.name==='AbortError'?'O serviço demorou para responder. Tente novamente.':e.message;toast(studio.source);}finally{clearTimeout(timer);studio.busy=false;render();}}
function applyStudio(){if(!stockTargetExists(studioStockTarget))return stockPicker('studio');if(!studio.drafts.length)return;const original=model,next=new E.ERPModel(JSON.parse(JSON.stringify(model.data)));try{studio.drafts.forEach(d=>{if(d.existingId){const p=next.product(d.existingId);if(!p)throw Error('O produto cadastrado não foi encontrado.');const siblings=next.data.products.filter(x=>familyKey(x)===familyKey(p));siblings.forEach(p=>next.data.catalog.photos[p.id]=studio.photos[d.photoIndex].image);return;}if(!['Unidade','Sacola','Pacote','Dúzia','Caixa','kg','Pote','Vidro','Litro'].includes(d.unit))throw Error('Revise a unidade de '+d.name+'.');if(!d.priceInput||E.cents(d.priceInput)<=0||d.stockInput==='')throw Error('Preencha preço e quantidade de '+d.name+'.');if(d.category==='Cafés'&&!E.COFFEE_TYPES.includes(d.type))throw Error('Revise o tipo de café de '+d.name+'.');const added=next.saveProducts({name:d.name,category:d.category,stockGroup:studioStockTarget},[{...d,weight:E.number(d.weight),volume:E.number(d.volume),contentCount:E.number(d.contentCount),costInput:d.costInput||'0'}]);next.data.catalog.photos[added[0].id]=studio.photos[d.photoIndex].image;});if(studio.mode==='batch'){next.data.catalog.story=studio.story;next.data.catalog.title=studio.title||next.data.catalog.title;}next.data.catalog.updatedAt=new Date().toISOString();model=next;if(!persist()){model=original;throw Error('Não foi possível salvar as fotos. Use arquivos menores ou exporte seus dados.');}studio.drafts=[];studio.photos=[];page='Catálogo';render();toast('Produtos e fotografias salvos no catálogo.');}catch(e){model=original;const error=document.getElementById('studio-error');if(error)error.textContent=e.message;toast(e.message);}}

function starIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.5 2.9 5.9 6.5.9-4.7 4.6 1.1 6.5-5.8-3.1-5.8 3.1 1.1-6.5L2.6 9.3l6.5-.9Z"/></svg>';}
function clientRanking(){
 const totals=new Map();model.data.sales.filter(s=>s.status==='completed'&&s.customerId).forEach(s=>{const c=model.data.clients.find(c=>c.id===s.customerId);if(!c)return;const t=totals.get(c.id)||{id:c.id,name:c.name,total:0,count:0};t.total+=s.total;t.count++;totals.set(c.id,t);});
 return [...totals.values()].filter(c=>c.total>0).sort((a,b)=>b.total-a.total||b.count-a.count||a.name.localeCompare(b.name,'pt-BR')||a.id.localeCompare(b.id));
}
function whatsappNumber(value){const raw=String(value||'').trim(),n=raw.replace(/\D/g,'');if(!n)return '';if(n.length===10||n.length===11)return '55'+n;if(n.length===12||n.length===13){if(n.startsWith('55'))return n;}return raw.startsWith('+')&&n.length>=8&&n.length<=15?n:'';}
function eventDateLabel(e){const date=new Date(e.start+'T12:00:00-03:00');return date.toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',timeZone:'America/Sao_Paulo'})+(e.end!==e.start?' a '+new Date(e.end+'T12:00:00-03:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long',timeZone:'America/Sao_Paulo'}):'')+' · '+e.from+' às '+e.until;}
function chooseNoticeEvent(id){noticeClientId=id||noticeClientId;const events=model.data.events.filter(e=>e.status==='active');openModal('Qual feira você quer avisar?',events.length?events.map(e=>btn('notice-select-event','<span><strong>'+escape(e.name)+'</strong><small>'+escape(eventDateLabel(e))+'</small></span>'+icon('chevron'),'list-row',{id:e.id})).join(''):'<p class="dialog-text">Cadastre uma feira na seção Eventos para preparar o convite.</p>'+btn('notice-new-event','Criar evento','success'),'notice-events');}
function openClientNotice(id,eventId){const c=model.data.clients.find(c=>c.id===id),e=model.data.events.find(e=>e.id===eventId&&e.status==='active');if(!c)return;if(!e)return chooseNoticeEvent(id);noticeClientId=id;notifyEventId=e.id;const text=clientInvitation(c,e),phone=whatsappNumber(c.phone);openModal('Avisar '+c.name,'<p class="dialog-text">'+escape(e.name)+'</p><label for="client-invitation">Mensagem para o cliente</label><textarea id="client-invitation" class="notice-copy-text">'+escape(text)+'</textarea><div class="notice-actions">'+btn('notice-copy','Copiar aviso','success')+(phone?btn('notice-whatsapp','Abrir WhatsApp','success',{id:c.id}):btn('edit-client','Adicionar WhatsApp','primary',{id:c.id}))+'</div><p class="pdf-share-note">'+(phone?'O WhatsApp abre com a mensagem pronta. Confira o contato e toque em enviar.':'Copie o aviso e cole na conversa do cliente, ou adicione o telefone com DDD ao cadastro.')+'</p>','client-notice',{client:id,event:e.id});}
async function copyClientNotice(){const el=document.getElementById('client-invitation');if(!el)return;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(el.value);return toast('Aviso copiado. Cole no WhatsApp do cliente.');}}catch(e){}el.focus();el.select();if(document.execCommand&&document.execCommand('copy'))toast('Aviso copiado. Cole no WhatsApp do cliente.');else toast('Mensagem selecionada. Toque em Copiar e cole no WhatsApp.');}
function openNoticeWhatsApp(id){const c=model.data.clients.find(c=>c.id===id),n=c&&whatsappNumber(c.phone),el=document.getElementById('client-invitation');if(!n||!el)return toast('Adicione um telefone com DDD ao cliente.');const a=document.createElement('a');a.href='https://wa.me/'+n+'?text='+encodeURIComponent(el.value);a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove();}
function reminderText(e,days){return days===1?'Amanhã é seu dia de feira. Tá esquecendo algo?':days===3?'Faltam 3 dias para a feira. Separe os produtos e avise os clientes.':'Faltam 5 dias para a feira. Confira estoque, catálogo e transporte.';}
