function reminderBanner(){const notices=eventReminders();if(!notices.length)return '';const r=notices[0];return '<section class="fair-reminder" role="status">'+btn('open-reminders','<strong>⚠️ '+escape(r.text)+'</strong><small>'+escape(r.event.name)+(notices.length>1?' · '+notices.length+' avisos':'')+'</small>')+btn('reminder-dismiss',icon('close'),'reminder-dismiss',{key:r.key})+'</section>';}
function openReminders(){const list=eventReminders();openModal('Seus lembretes de feira',list.map(r=>'<section class="panel"><h3>⚠️ '+escape(r.event.name)+'</h3><p class="dialog-text">'+escape(r.text)+'</p><p class="small muted">'+escape(eventDateLabel(r.event))+' · '+escape(r.event.place)+'</p><div class="reminder-checklist">'+['Produtos e estoque','Troco e meios de pagamento','Catálogo e QR code','Transporte e montagem'].map(t=>'<label><input type="checkbox">'+t+'</label>').join('')+'</div>'+btn('event-notify','Avise os clientes','event-notify',{id:r.event.id})+btn('reminder-dismiss','Marcar como visto','link-row',{key:r.key})+'</section>').join('')+'<p class="pdf-share-note">Os avisos aparecem ao abrir o app nos 5, 3 e 1 dias anteriores. Salve os lembretes na agenda para receber alertas com o app fechado.</p>'+btn('close-modal','Entendi','success modal-action'),'reminders');}
function calendarEscape(value){return String(value||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function foldCalendarLine(line){let result='',length=0;for(const char of line){const bytes=unescape(encodeURIComponent(char)).length;if(length+bytes>75){result+='\r\n ';length=1;}result+=char;length+=bytes;}return result;}
