function brainReport(sel,now){now=now||Date.now();const m=sel.eventId?aggregateSales(model.data.sales.filter(s=>s.status==='completed'&&s.scope===sel.eventId&&Date.parse(s.date)<=now),model.data.expenses.filter(x=>x.scope===sel.eventId)):filteredMetrics(sel),facts=[],add=(level,title,text,order)=>facts.push({level,title,text,order:order||0}),out=scopeStockProducts(sel.scope).filter(p=>p.stock<=0),low=scopeStockProducts(sel.scope).filter(p=>p.stock>0&&p.stock<=p.min),e=model.data.events.find(e=>e.id===sel.scope);if(m.result<0)add('red','Resultado exige atenção','O período tem receita de '+E.money(m.revenue)+' e resultado de '+E.money(m.result)+'. Revise preços, custos e despesas antes de ampliar descontos.',100);if(out.length)add('red','Produtos sem estoque',out.map(p=>titleName(p.name)+' · '+E.description(p)).join('; ')+'. Suspenda a oferta dessas apresentações ou confirme reposição.',95);if(low.length)add('orange','Reposição antes da próxima venda',low.map(p=>titleName(p.name)+' · '+E.quantity(p.stock)+' '+E.unitLabel(p.unit,p.stock)).join('; ')+'. Confira estoque e prazo de reposição.',90);const marketing=kpiData(sel),conversion=marketing.find(k=>k.key==='conversion');if(conversion.value==='—')add('orange','Quantos compraram dos que pararam','Para saber quantas pessoas que pararam na banca compraram, registre os atendimentos em "Registrar abordagens".',30);else add('green','Conversão registrada',conversion.value+' no período. Compare faixas de horário antes de mudar a oferta.',50);if(m.sales.length)add(m.gross<0?'red':'green','Margem das vendas',grammarCount(m.sales.length,'venda','vendas')+' · lucro bruto '+E.money(m.gross)+' · margem '+(m.margin==null?'sem base':m.margin.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%')+'. Despesas registradas: '+E.money(m.expense)+'.',60);else add('orange','Sem vendas concluídas neste período','Amplie o período ou aguarde novas vendas. Não há base para afirmar queda de demanda.',15);if(m.rank[0])add('green','Produto com mais receita',titleName(m.rank[0].name)+' · '+m.rank[0].description+' gerou '+E.money(m.rank[0].amount)+'. Confira sua margem e mantenha essa apresentação visível na banca.',65);const sold=new Set(m.rank.map(r=>r.id)),slow=scopeStockProducts(sel.scope).filter(p=>{if(p.stock<=0||sold.has(p.id))return false;const moves=model.data.movements.filter(x=>x.productId===p.id),first=moves.reduce((a,x)=>Math.min(a,Date.parse(x.date)),Infinity),lastSale=model.data.sales.filter(s=>s.status==='completed'&&s.items.some(i=>i.productId===p.id)).reduce((a,s)=>Math.max(a,Date.parse(s.date)),0);return now-Math.max(first,lastSale)>=30*86400000;});if(slow.length)add('orange','Estoque com 30 dias sem saída',slow.slice(0,3).map(p=>titleName(p.name)+' · '+E.description(p)).join('; ')+'. Teste exposição, demonstração ou um kit com margem calculada; confira validade quando aplicável.',70);const older=e&&model.data.events.filter(x=>x.id!==e.id&&x.start<e.start).sort((a,b)=>b.start.localeCompare(a.start))[0],prior=older?aggregateSales(eventSalesInWindow(older,e,sel,now),[]):filteredMetrics(previousSelection(sel)),buyers=new Set(m.sales.map(s=>s.customerId).filter(Boolean)),missing=[...new Set(prior.sales.map(s=>s.customerId).filter(Boolean))].filter(id=>!buyers.has(id)).map(id=>model.data.clients.find(c=>c.id===id)).filter(Boolean);if(missing.length)add('orange','Clientes que ainda não voltaram',missing.slice(0,3).map(c=>c.name).join(', ')+(missing.length>3?' e mais '+(missing.length-3):'')+' compraram no período anterior e ainda não neste. Convide apenas quem autorizou os avisos.',40);if(e){const stage=now<eventStartTime(e)?'Antes da feira':now<eventEndTime(e)&&e.status==='active'?'Durante a feira':'Depois da feira';add('green',stage,e.name+' · '+e.from+'–'+e.until+'. '+(stage==='Durante a feira'?'Os comparativos usam a janela atual até este minuto, sem comparar uma hora parcial com uma hora inteira.':stage==='Antes da feira'?'Confira reposição, etiquetas e aviso aos clientes.':'Revise saída por apresentação, resultado e retorno dos clientes para a próxima edição.'),55);}const hourly=Math.floor(now/3600000)%3,advice=[['Branding · origem visível','Conte em uma frase a origem do produto e mantenha nome e logo iguais na banca, na embalagem e no catálogo.'],['Banca · escolha e pagamento claros','Mostre preço e apresentação juntos. Separe o espaço de escolher do espaço de pagar e deixe o catálogo acessível.'],['Combinação com outro produtor','Ideia para testar: café com queijo ou banana. Antes da parceria, combine preço, responsabilidade, estoque e margem; não há parceria cadastrada automaticamente.']][hourly];add('green',advice[0],advice[1],10);return {metrics:m,facts:facts.sort((a,b)=>({red:3,orange:2,green:1}[b.level]-{red:3,orange:2,green:1}[a.level])||b.order-a.order)};}
