async function weatherJSON(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error('Previsão indisponível.');return await response.json();}finally{clearTimeout(timer);}}
async function forecastForEvent(e,now){if(eventEndTime(e)<=(now||Date.now()))return {status:'unavailable',text:'A feira já encerrou. Previsão não é histórico observado de chuva.'};return window.TerritorioWeather.eventWeather(e,now);}

async function loadBrainWeather(force){const e=brainWeatherEvent();if(!e||!brainContext)return;const key=weatherKey(e),cache=weatherCache.get(key);if(!force&&cache&&Date.now()-cache.at<3600000)return;weatherCache.set(key,{at:Date.now(),status:'loading',text:'Consultando o tempo para '+(e.city||model.data.settings.city)+'…'});if(modal&&modal.kind==='brain')paintBrain(true);try{const result=await forecastForEvent(e);weatherCache.set(key,{...result,at:Date.now()});}catch(error){weatherCache.set(key,{at:Date.now(),status:'unavailable',text:'Previsão indisponível agora. Conecte à internet e tente atualizar; não há confirmação de chuva.'});}if(modal&&modal.kind==='brain')paintBrain(true);}
function weatherFact(){const e=brainWeatherEvent();if(!e)return {level:'orange',title:'Tempo na próxima feira',text:'Cadastre evento com município e UF.'};const w=weatherCache.get(weatherKey(e));if(!w||w.status!=='ready')return {level:'orange',title:'Tempo · '+e.name,text:w?.text||'Consultando previsão.'};return {level:w.rain>0?'orange':'green',title:'Tempo · '+e.name,text:'Chuva prevista: '+w.rain.toLocaleString('pt-BR',{maximumFractionDigits:1})+' mm.'+(w.prob!==null?' Maior chance entre períodos informados: '+w.prob+'%.':' Sem probabilidade percentual informada.')+(w.partial?' Intervalos parciais estimados proporcionalmente.':'')+' Previsão, não certeza nem observação histórica. '+w.city+' · MET Norway · '+new Date(w.updatedAt).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})+(w.stale?' · última previsão salva.':'.')};}
