 'all-months':()=>{allMonthsOpen=!allMonthsOpen;render();},
 'month-input-apply':()=>{const el=document.getElementById('all-month-input');if(el&&/^\d{4}-\d{2}$/.test(el.value)){month=el.value;managementDays.clear();render();}},
 'month-shift':d=>{month=shiftMonth(month,Number(d.delta));managementDays.clear();render();},
 'choose-month':()=>{calendarOpen=true;render();},
 'calendar-toggle':()=>{calendarOpen=!calendarOpen;render();},
 'calendar-day':d=>{if(d.day.slice(0,7)!==month)return;managementDays.has(d.day)?managementDays.delete(d.day):managementDays.add(d.day);render();},
 'calendar-clear':()=>{managementDays.clear();managementHours={from:'',until:''};render();},
 'calendar-apply':()=>{const from=document.getElementById('period-from').value,until=document.getElementById('period-until').value;if(from&&until&&from>=until)return toast('O fim precisa ser depois do início.');managementHours={from,until};calendarOpen=false;render();},
 'period-sales':()=>salesHistory(filteredMetrics().sales,'Vendas do período'),
 'management-scope':d=>{managementScope=d.scope;render();},
 'local-insights':()=>brainOpen('management'),
 'management-data':()=>{dataReturn='Gestão';dataScope=managementScope;page='Dados';render();window.scrollTo(0,0);},
 'log-approaches':()=>approachesModal(),
 'save-approaches':()=>{const count=Number(document.getElementById('approach-count').value),date=document.getElementById('approach-date').value,time=document.getElementById('approach-time').value,local=document.getElementById('approach-scope').value;if(!Number.isInteger(count)||count<1||!date||!time)return toast('Informe quantidade inteira positiva, dia e horário.');model.data.contacts.push({id:E.uid(),scope:local,date:date+'T'+time+':00-03:00',count});persist();closeModal();render();toast('Abordagens registradas.');},
 'broadcast':()=>broadcastModal(),
 'broadcast-copy':()=>copyBroadcast(),
 'broadcast-link-save':()=>{const el=document.getElementById('events-public-link'),value=el.value.trim();if(value&&!safePublicURL(value))return toast('Informe um link HTTPS válido.');model.data.settings.eventsURL=value;persist();broadcastModal(document.getElementById('broadcast-event').value);},
 'broadcast-events':()=>{closeModal();page='Eventos';render();window.scrollTo(0,0);},
 'consumption':d=>{consumptionQuery='';consumptionModal(d.type);},
 'consumption-detail':d=>consumptionDetail(d.id),
 'customer-records':d=>salesHistory(filteredMetrics({...selection(),customerId:d.id}).sales,'Vendas do cliente no período'),
 'client-detail':d=>consumptionDetail(d.id),
 'save-client':()=>{captureClient();const name=clientEditor.name.trim();if(!name)return toast('Informe o nome do cliente.');if(clientEditor.phone&&!whatsappNumber(clientEditor.phone))return toast('Informe um telefone com DDD válido.');const previous=model.data.clients.find(c=>c.id===clientEditor.id),c={...previous,id:clientEditor.id||E.uid(),name,phone:clientEditor.phone||'',city:clientEditor.city.trim(),neighborhood:clientEditor.neighborhood.trim(),uf:clientEditor.uf,aiConsent:clientEditor.aiConsent,personType:clientEditor.personType==='PJ'?'PJ':'PF',document:clientEditor.document.trim(),noticeConsent:!!clientEditor.noticeConsent};if(c.noticeConsent&&!previous?.noticeConsent)c.noticeConsentAt=new Date().toISOString();if(!c.noticeConsent)c.noticeConsentAt='';if(isCarangola(c))c.uf='MG';const i=model.data.clients.findIndex(x=>x.id===c.id);if(i>=0)model.data.clients[i]=c;else model.data.clients.push(c);persist();closeModal();render();toast('Cliente salvo.');},
 'save-event':()=>{const value=id=>document.getElementById(id).value.trim(),name=value('event-name'),place=value('event-place'),start=value('event-start'),end=value('event-end'),from=value('event-from'),until=value('event-until'),city=value('event-city'),uf=value('event-uf').toUpperCase(),days=(Date.parse(end)-Date.parse(start))/86400000+1;if(!name||!place||!start||!end||days<1||days>9||!from||!until||from>=until||!city||!E.STATES.some(s=>s[0]===uf))return toast('Informe nome, local, município, UF e datas de 1 a 9 dias. O horário final deve ser após o início.');const e={id:E.uid(),name,place,start,end,from,until,city,uf,status:'active',qrKind:E.normalize(name).includes('inventario')?'site':'catalog',website:E.normalize(name).includes('inventario')?'https://www.visitecarangolamg.com.br':''};model.data.events.push(e);syncEvents();persist();closeModal();render();toast(e.status==='finished'?'Evento passado salvo como encerrado.':'Evento criado.');},
 'event-detail':d=>{syncEvents();eventDetail(d.id);},
 'event-use':d=>{syncEvents();const e=model.data.events.find(e=>e.id===d.id);if(!e)return;if(e.status==='active'){scope=e.id;page='Vender';}else{page='Gestão';managementScope=e.id;month=e.start.slice(0,7);managementDays.clear();managementHours={from:'',until:''};}closeModal();render();},
 'finish-event':d=>{const e=model.data.events.find(e=>e.id===d.id);if(!e)return;e.status='finished';e.finishedAt=new Date().toISOString();e.closedAutomatically=false;if(scope===d.id)scope='loja';persist();closeModal();render();toast('Evento finalizado. As vendas continuam na Gestão.');},
 'export-fair':d=>exportCSV('feira-geral-'+d.id+'.csv',fairGeneralRows(d.id)),
 'export-monthly':()=>exportCSV('vendas-fora-eventos-'+month+'.csv',saleCSVRows(model.data.sales.filter(s=>s.scope==='loja'&&E.monthKey(s.date)===month))),
 'export-consumption':d=>exportCSV('consumo-'+(d.type==='PJ'?'cnpj':'pessoa-fisica')+'-'+month+'.csv',consumptionRows(d.type==='PJ'?'PJ':'PF')),
 'export-sales':()=>exportCSV('vendas-'+month+'.csv',saleCSVRows(filteredMetrics().sales)),
 'export-clients':()=>exportCSV('clientes.csv',[['Nome','Tipo','Documento','Município','Bairro','UF','WhatsApp','Avisos autorizados','Autorização registrada em','Compras','Total'],...model.data.clients.map(c=>{const s=model.data.sales.filter(s=>s.status==='completed'&&s.customerId===c.id);return[c.name,c.personType,c.document||'',c.city,c.neighborhood,c.uf,c.phone,c.noticeConsent?'Sim':'Não',c.noticeConsentAt||'',s.length,(s.reduce((n,v)=>n+v.total,0)/100).toFixed(2)];})]),
 'expense':()=>openModal('Adicionar despesa',field('expense-title','Descrição','','placeholder="Ex.: transporte ou divulgação"')+field('expense-value','Valor (R$)','','inputmode="decimal"')+field('expense-date','Data',month+'-10','type="date"')+'<label for="expense-category">Finalidade</label><select id="expense-category"><option value="Operação">Operação</option><option value="Marketing">Marketing / divulgação</option></select>'+btn('save-expense','Registrar despesa','primary modal-action'),'expense'),
