function refreshTotal(){if(!draft)return;const q=model.quote(draft),el=document.getElementById('sale-total'),err=document.getElementById('sale-error');if(el)el.textContent=E.money(Number.isFinite(q.total)?Math.max(0,q.total):0);const subtotal=document.getElementById('sale-subtotal'),discount=document.getElementById('sale-discount-summary');if(subtotal)subtotal.textContent='Subtotal '+E.money(q.subtotal);if(discount)discount.innerHTML=appliedDiscountLabel(q.discount);q.items.forEach((item,i)=>{const amount=document.getElementById('item-quantity-'+i);if(amount)amount.textContent=E.quantity(item.qty)+' '+E.unitLabel(item.unit,item.qty);});if(draft.split&&!draft.partsManual)draft.parts.forEach((part,i)=>{const value=document.getElementById('pay-value-'+i);if(value&&value!==document.activeElement)value.value=part.value;});if(err){const error=saleError(false);err.textContent=error;err.className=error?'sale-dock-error':'sale-dock-error sr-only';const submit=document.querySelector('[data-action="open-cart"]');if(submit)submit.disabled=!!error||multiReviewPending();}}
function handleAppInput(event){
 const t=event.target;if(t.dataset?.numeric!==undefined)numericTouched.add(t.id);
 if(t.id==='catalog-title'){if(model.data.catalog){model.data.catalog.title=t.value;persist();}}
 else if(t.dataset.studio!==undefined){studio.drafts[+t.dataset.studio][t.dataset.field]=t.value;}
  else if(t.id==='studio-story'){studio.story=t.value;}
  else if(t.id==='studio-prompt'){studio.prompt=t.value;}
  else if(t.id==='ai-question'){aiQuestion=t.value;}
 else if(t.id==='catalog-search'){const results=document.getElementById('catalog-results');if(results)results.innerHTML=catalogResults(t.value);}
 else if(t.id==='client-search'){clientQuery=t.value;clientsOpen=true;render(true);}
  else if(t.id==='week-search'){weekQuery=t.value;render(true);}
 else if(t.id==='product-search'){query=t.value;render(true);}
 else if(t.id==='product-name'){updateProductName(t.value,false,event);}
 else if(t.dataset.variant!==undefined){const v=productForm.variants[+t.dataset.variant];v[t.dataset.field]=t.value;if(['volume','contentCount'].includes(t.dataset.field))v[t.dataset.field]=E.number(t.value);const notice=document.getElementById('stock-notice-'+t.dataset.variant);if(notice&&!productForm.editId)notice.innerHTML=icon('box')+' '+stockNoticeText(v);}
 else if(t.id==='sale-quantity'){if(t.value.trim()==='')numericTouched.delete(t.id);else numericTouched.add(t.id);const ok=setSaleQuantity(t.value);t.value=draft.items[draft.active].rawQty;splitUpdate();if(ok)render(true);refreshTotal();}
 else if(t.id==='sale-discount'){draft.discountValue=t.value;splitUpdate();refreshTotal();}
 else if(t.id==='sale-client-name'){draft.clientName=t.value;draft.clientId=null;saleClientFilter=t.value;refreshSaleClientChoices();}
 else if(t.id==='sale-client-city'){draft.city=t.value;if(isCarangola(draft))draft.uf='MG';}
 else if(t.id==='sale-client-neighborhood')draft.neighborhood=t.value;
 else if(t.id==='checkout-neighborhood'){draft.neighborhood=t.value;paintCheckout();}
 else if(clientEditor&&['client-name','client-phone','client-city','client-neighborhood'].includes(t.id)){clientEditor[{'client-name':'name','client-phone':'phone','client-city':'city','client-neighborhood':'neighborhood'}[t.id]]=t.value;}
 else if(t.dataset.paymentValue!==undefined){draft.parts[+t.dataset.paymentValue].value=t.value;draft.partsManual=true;refreshPayment();}
 else if(t.id==='move-quantity'){movement.raw=t.value;refreshMovementPreview();}
 else if(t.id==='move-reason')movement.note=t.value;
}
