// Venda de vários produtos: informada a quantidade do último produto pendente, o quadro dele fecha
// sozinho logo depois do último dígito, como os anteriores; só então o Carrinho é liberado, com os
// produtos todos fechados para o vendedor conferir o resumo.
const LAST_QUANTITY_MS=900;let lastQuantityTimer=0;
function multiReviewPending(){return !!draft&&draft.items.length>1&&!draft.quantityReviewCollapsed&&draft.items.every(i=>E.number(i.rawQty)>0);}
function armLastQuantity(){clearTimeout(lastQuantityTimer);if(draft?.multiPick)return;if(!multiReviewPending())return;const active=draft.active,raw=draft.items[active].rawQty;lastQuantityTimer=setTimeout(()=>{if(!multiReviewPending()||page!=='Venda'||draft.active!==active||draft.items[active].rawQty!==raw)return;if(document.activeElement?.id==='sale-quantity')document.activeElement.blur();saveActiveDiscount();window.TerritorioSectionMotion?.prepare(['#app .quantity-panel','#app .sale-customer']);draft.quantityReviewCollapsed=true;render();},LAST_QUANTITY_MS);}
const r20Digit=actions.digit;actions.digit=d=>{r20Digit(d);armLastQuantity();};
