function activeEventsAt(now){const stamp=now==null?Date.now():Number(now);return model.data.events.filter(e=>E.eventSellingNow(e,stamp)).sort((a,b)=>a.start.localeCompare(b.start)||a.from.localeCompare(b.from)||a.id.localeCompare(b.id));}

function eventChoice(now){const live=activeEventsAt(now),preferred=live.find(e=>e.id===preferredSaleEvent)||live.find(e=>e.id===scope);if(preferred)return preferred;if(live.length)return live[0];return model.data.events.filter(e=>e.status==='active'&&eventEndTime(e)>(now==null?Date.now():Number(now))).sort((a,b)=>eventStartTime(a)-eventStartTime(b)||a.id.localeCompare(b.id))[0]||null;}

function recipientOptions(now){if(draft?.orderId){const order=model.data.onlineShop?.orders.find(o=>o.id===draft.orderId),event=order?.event&&model.data.events.find(e=>e.id===order.event.id);return event?{pf:false,pj:false,event:true,eventRecord:event}:{pf:true,pj:true,event:false,eventRecord:null};}if(draft?.localOrderId)return{pf:true,pj:true,event:false,eventRecord:null};const event=eventChoice(now),live=!!event&&E.eventSellingNow(event,now==null?Date.now():Number(now));return{pf:!live,pj:!live,event:live,eventRecord:event};}

