function stockCardDescription(p){const description=E.description(p),unit=E.unitLabel(p.unit,1);return presentationText(E.normalize(description).includes(E.normalize(unit))?description:description+' · '+unit);}
function sellingCardDescription(p){if(p.category==='Cafés'){const format=E.normalize(p.format);return /grao|^verde$/.test(format)?'Grãos':presentationText(p.format||'Moído');}return ['kg','Litro','g','ml'].includes(p.unit)?'Granel':titleName(E.unitLabel(p.unit||'Unidade',1));}

