// --- Banco do mercado municipal e autocompletar por área ---
function mergeMarketCatalog(records){const market=(window.TERRITORIO_MARKET||[]).flatMap(([category,group,unit,names])=>names.split('|').map(name=>({name:name.trim(),category,group,unit}))).filter(r=>r.name),seen=new Set(market.map(r=>E.normalize(r.name)));return [...market,...records.filter(r=>!seen.has(E.normalize(r.name)))];}
const legacyCatalogDefaults=catalogDefaults;
// A unidade do grupo (maço, vidro, bandeja…) vale onde o app não tinha uma regra própria.
catalogDefaults=function(record){const d=legacyCatalogDefaults(record);if(record.unit&&(['Mel e apícolas','Conservas e temperos','Carnes e aves','Plantas e flores','Doces','Bebidas','Piscicultura'].includes(record.category)||record.category==='Hortifruti-Granjeiro'&&d.unit==='kg'))d.unit=record.unit;return d;};
// Com uma área escolhida, só sugere itens dela: "aba" no Hortifruti traz abacate e abacaxi, nada de outras áreas.
productSuggestions=function(prefix){const key=E.normalize(prefix);if(key.length<2)return [];const area=productForm&&productForm.manualCategory?productForm.category:'',seen=new Set(),starts=[],words=[],skip=['ovos de galinha','ovo de galinha','ovos de pascoa','ovo de pascoa','ovos de chocolate','ovo de chocolate'];
 for(const raw of catalogCandidates()){const p=E.normalize(raw.name)==='ovo'?{...raw,name:'Ovos'}:raw;if(area&&p.category!==area)continue;const name=E.normalize(p.name),canonical=name==='ovo'?'ovos':name;if(skip.includes(name)||seen.has(canonical))continue;if(name.startsWith(key)){seen.add(canonical);starts.push(p);}else if(name.split(/[\s-]+/).some(w=>w.startsWith(key))){seen.add(canonical);words.push(p);}}
 const order=(a,b)=>a.name.split(/\s+/).length-b.name.split(/\s+/).length||a.name.localeCompare(b.name,'pt-BR');return [...starts.sort(order),...words.sort(order)].slice(0,12);};

// --- Estilo do app: "Feira" (padrão, inspirado no ERPIA) ou "Território" (original) ---
function isFeira(){return model.data.settings.layout!=='territorio';}
function feiraHero(sel,m){const monthly=/^\d{4}-\d{2}$/.test(sel.month||'');if(!monthly)sel={...sel,month:E.monthKey(Date.now())};const days=new Date(Number(sel.month.slice(0,4)),Number(sel.month.slice(5,7)),0).getDate(),values=Array.from({length:days},(_,i)=>m.daily[sel.month+'-'+String(i+1).padStart(2,'0')]||0),max=Math.max(...values),today=E.dayKey(Date.now()),W=320,H=120,step=W/days,bw=Math.max(3,step*0.62);
 const bars=max?values.map((v,i)=>{const h=v?Math.max(3,v/max*(H-22)):0,x=i*step+(step-bw)/2;return h?'<rect class="bar'+(sel.month+'-'+String(i+1).padStart(2,'0')===today?' today':'')+'" x="'+x.toFixed(1)+'" y="'+(H-18-h).toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+h.toFixed(1)+'" rx="'+Math.min(3,bw/2).toFixed(1)+'"><title>'+(i+1)+': '+E.money(v)+'</title></rect>':'';}).join(''):'';
 const ticks=[1,6,11,16,21,26,days].filter((d,i,a)=>d<=days&&a.indexOf(d)===i).map(d=>'<text x="'+((d-0.5)*step).toFixed(1)+'" y="'+H+'" text-anchor="middle">'+d+'</text>').join('');
 return '<section class="feira-hero" aria-label="Resumo do período"><small>Receita líquida</small><span class="feira-hero-value">'+E.money(m.revenue)+'</span><div class="feira-hero-stats"><div><small>Vendas</small><strong>'+m.sales.length+'</strong></div><div><small>Ticket médio</small><strong>'+(m.sales.length?E.money(m.ticket):'—')+'</strong></div><div><small>Resultado</small><strong>'+E.money(m.result)+'</strong></div></div></section>'
 +(monthly?'<section class="feira-chart"><h2>Receita por dia</h2>'+(max?'<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Gráfico de receita por dia">'+'<line class="baseline" x1="0" x2="'+W+'" y1="'+(H-18)+'" y2="'+(H-18)+'"></line>'+bars+ticks+'</svg>':'<p class="feira-chart-empty">Sem vendas neste período.</p>')+'</section>':'');}
