function advisorHistory(){const today=E.dayKey(Date.now()),since=Date.now()-60*864e5,names=advisorNames();
 const dayDiff=(a,b)=>Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/864e5);
 const events=model.data.events.filter(e=>e.status==='finished'||e.end<today).map(e=>{const load=eventLoad(e.id),bal=load?eventLoadBalance(e.id):null,sold=new Map();eventSoldQuantities(e.id).forEach(s=>sold.set(s.productId,(sold.get(s.productId)||0)+s.qty));
  const ids=new Set([...sold.keys(),...(load?load.items.map(i=>i.productId):[])]);
  const items=[...ids].map(id=>{const li=load&&load.items.find(i=>i.productId===id),rest=bal&&bal.balance.find(b=>b.productId===id);return{productId:id,name:names.get(id)||'',sold:sold.get(id)||0,taken:li?li.qty:0,left:rest?Math.max(0,rest.qty):0};});
  return{id:e.id,name:e.name,start:e.start,days:dayDiff(e.start,e.end)+1,items};}).filter(e=>e.items.some(i=>i.sold>0));
 const daily=model.data.sales.filter(s=>s.status==='completed'&&Date.parse(s.date)>=since).flatMap(s=>netItems(s).map(i=>({day:E.dayKey(s.date),hour:Number(brTime(s.date).slice(0,2)),productId:model.product(i.productId)?.id||i.productId,qty:i.qty,amount:i.amount})));
 return{events,daily};}
const advisorBaseInput=advisorInput;
advisorInput=function(){const input=advisorBaseInput(),today=E.dayKey(Date.now()),byId=new Map(model.data.products.map(p=>[p.id,p]));
 input.today=today;input.history=advisorHistory();
 input.products=input.products.map(p=>{const full=byId.get(p.id);return full?{...p,decimal:['kg','Litro','g','ml'].includes(full.unit),unitShort:shortUnit(full.unit)}:p;});
 const next=model.data.events.filter(e=>e.status==='active'&&e.end>=today).sort((a,b)=>a.start.localeCompare(b.start))[0];
 if(input.upcoming&&next)input.upcoming.days=Math.round((Date.parse(next.end+'T12:00:00Z')-Date.parse(next.start+'T12:00:00Z'))/864e5)+1;
 return input;};
Object.assign(actions,{'restock-ids':d=>openRestock(String(d.ids||'').split(',').filter(Boolean))});

// --- Estilo Feira: Vender e Estoque com a estrutura do ERPIA ---
function feiraSearch(){return '<label class="feira-search">'+icon('search')+'<span class="sr-only">Buscar produto</span><input id="feira-search" type="search" placeholder="Buscar produto" value="'+escape(query)+'" autocomplete="off" spellcheck="false"></label>';}
function feiraChips(){const cats=[...new Set(model.data.products.map(p=>p.category))];if(cats.length<2&&page!=='Vender')return '';return '<div class="feira-chips" role="group" aria-label="Categorias">'+['Todos',...cats].map(c=>btn('feira-filter',escape(c),'chip'+(filter===c?' selected':''),{value:c})).join('')+'</div>';}
function feiraSellList(){const groups=new Map();productList(false).forEach(p=>{const k=familyKey(p);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(p);});
 if(!groups.size)return '<div class="empty"><strong>'+(model.data.products.length?'Nada encontrado':'Nenhum produto ainda')+'</strong><p>'+(model.data.products.length?'Tente outro nome ou categoria.':'Cadastre seus produtos no Estoque para começar a vender.')+'</p></div>';
 return '<div class="feira-grid">'+[...groups.values()].map(variants=>{const live=variants.filter(v=>v.stock>0),p=(live.length?live:variants).slice().sort((a,b)=>a.price-b.price)[0],out=!live.length,many=new Set(variants.map(v=>v.price)).size>1;
  return btn('sell-product','<strong>'+escape(titleName(p.name))+'</strong><small>'+escape(sellingCardDescription(p))+'</small>'+(out?'<em>Esgotado</em>':'')+'<span class="tabular">'+E.money(p.price)+'</span>','feira-card'+(out?' is-out':''),{id:p.id},out);}).join('')+'</div>';}
function feiraSellPage(){const today=E.dayKey(new Date()),sales=model.data.sales.filter(s=>s.status==='completed'&&s.scope===scope&&E.dayKey(s.date)===today),visible=model.data.settings.financialVisible;
 return top()+reminderBanner()+'<section class="feira-sell-hero">'+btn('weekly-sales','<span class="fsh-where"><span><small>Vendendo em</small><strong>'+escape(scopeName(scope))+'</strong></span></span><span class="fsh-today"><small>Hoje · '+grammarCount(sales.length,'venda','vendas')+'</small><strong class="tabular">'+(visible?E.money(sales.reduce((n,s)=>n+s.total,0)):'••••••')+'</strong></span>','fsh-main')+'<button type="button" data-action="toggle-financial" class="fsh-eye" aria-label="'+(visible?'Ocultar':'Mostrar')+' valores" aria-pressed="'+visible+'">'+icon(visible?'eye':'eyeOff')+'</button></section>'
 +draftResumeBanner()+feiraSearch()+feiraChips()+'<div id="feira-list">'+feiraSellList()+'</div>';}
function stockGroups(){const ok=[],low=[],out=[],products=window.TerritorioStockOrder?window.TerritorioStockOrder.orderStockProducts(model.data.products):model.data.products;products.forEach(p=>(p.stock<=0?out:p.stock<=(p.min||0)?low:ok).push(p));return{ok,low,out};}
function feiraStockStatus(){const g=stockGroups();if(!model.data.products.length)return '';const tile=(key,label,list,cls)=>btn('feira-restock','<small>'+label+'</small><strong class="tabular">'+list.length+'</strong>','feira-stock-count '+key+(list.length&&cls?' '+cls:''),{group:key},!list.length);
 return '<section class="feira-stock" aria-label="Situação do estoque"><div class="feira-stock-counts">'+tile('ok','Em dia',g.ok,'')+tile('low','Baixo',g.low,'warn')+tile('out','Esgotado',g.out,'alert')+'</div><p class="feira-stock-hint">Toque para repor.</p></section>';}
function resourceLimit(key,total){return window.TerritorioResourcePolicy?.limitFor(key,total)??Math.min(total,60);}
function resourceMore(key,total,shown){return total>shown?btn('resource-more','Mostrar mais produtos','choice modal-action resource-more',{key}):'';}
function feiraStockList(){const items=productList(true);if(!items.length)return '<div class="empty"><strong>Nenhum produto encontrado</strong></div>';const families=new Map();for(const p of items){const family=window.TerritorioStockOrder?.stockFamily?.(p)||E.normalize(p.category==='Cafés'?'Cafés':p.baseName||p.name);const key=p.category+'|'+family;if(!families.has(key))families.set(key,[]);families.get(key).push(p);}const row=p=>{const state=p.stock<=0?'out':p.stock<=(p.min||0)?'low':'ok';return btn('stock-product','<span class="fr-main"><strong>'+escape(titleName(p.name))+'</strong><small>'+escape(stockCardDescription(p))+'</small></span><span class="fr-side"><b class="tabular '+state+'">'+E.quantity(p.stock)+'</b><small>'+escape(shortUnit(p.unit))+'</small></span>'+icon('chevron')+(p.stock<=0?window.TerritorioRestockSymbol():'')+window.TerritorioProductOutline(p),'feira-row',{id:p.id});};const groups=[...families.values()],shown=resourceLimit('stock-families',groups.length);return groups.slice(0,shown).map(list=>'<section class="workflow-stock-family"><h3 class="feira-group" data-family-query="'+escape(window.TerritorioStockOrder?.stockFamily?.(list[0])||list[0].baseName||list[0].name)+'">'+escape(titleName(window.TerritorioStockOrder?.stockFamilyLabel?.(list[0])||list[0].baseName||list[0].name))+'</h3><div class="feira-rows">'+list.slice(0,3).map(row).join('')+'</div>'+(list.length>3?'<details data-resource-group="'+escape(list[0].id)+'" class="workflow-stock-more"><summary>Mais '+(list.length-3)+' '+(list.length===4?'apresentação':'apresentações')+' '+icon('down')+'</summary><div class="feira-rows">'+list.slice(3,resourceLimit('stock-'+list[0].id,list.length)).map(row).join('')+'</div>'+resourceMore('stock-'+list[0].id,list.length,resourceLimit('stock-'+list[0].id,list.length))+'</details>':'')+'</section>').join('')+resourceMore('stock-families',groups.length,shown);}
function feiraStockPage(){const typed=query;query='';const list=feiraStockList();query=typed;return top()+feiraStockStatus()+stockLossReminder()+feiraChips()+'<div id="feira-list">'+list+'</div>';}
document.addEventListener('input',event=>{if(event.target.id!=='feira-search')return;query=event.target.value;const list=document.getElementById('feira-list');if(list)list.innerHTML=page==='Estoque'?feiraStockList():feiraSellList();});

// --- Venda de vários produtos (segurar o cartão em Vender; src/features/multisell.js) ---
Object.assign(actions,{'sell-multiple':d=>{const ids=String(d.ids||'').split(',').filter(id=>{const p=model.product(id);return p&&p.active!==false&&!p.archived&&sellingAvailableStock(id)>0;}).slice(0,3);if(!ids.length)return;
 ids.forEach(id=>createDraft(id));const first=draft.items.findIndex(i=>i.productId===ids[0]);if(first>=0&&first!==draft.active){saveActiveDiscount();draft.active=first;loadActiveDiscount();}render();window.scrollTo(0,0);}});

// --- Leva 6: ordem dos produtos, pesos padrão, histórico da Loja, gráfico, CSV, estado da venda ---
// Ordem: dentro de cada área, do produto mais caro (por kg/L quando há peso) para o mais barato,
// e cada produto com suas apresentações em sequência de peso (250 g, 500 g, 1 kg).
function unitValue(p){const w=p.weight||p.volume||0;return w?p.price/(w/1000):p.price;}
function sortProducts(list){const cats=E.CATEGORIES,rank=new Map();list.forEach(p=>{const k=familyKey(p);rank.set(k,Math.max(rank.get(k)||0,unitValue(p)));});
 return list.slice().sort((a,b)=>{const ca=cats.indexOf(a.category),cb=cats.indexOf(b.category);if(ca!==cb)return (ca<0?99:ca)-(cb<0?99:cb);const ka=familyKey(a),kb=familyKey(b);if(ka!==kb)return rank.get(kb)-rank.get(ka)||ka.localeCompare(kb,'pt-BR');return (a.weight||a.volume||0)-(b.weight||b.volume||0)||a.price-b.price;});}
const baseProductList=productList;
productList=function(stockMode){const items=baseProductList(stockMode);return stockMode&&window.TerritorioStockOrder?window.TerritorioStockOrder.orderStockProducts(items):sortProducts(items);};
// Pesos padrão no cadastro: três apresentações usuais por área (no café: 250 g, 500 g e 1 kg).
const WEIGHT_PRESETS={'Cafés':[250,500,1000],'Laticínios':[250,500,1000],'Charcutaria':[250,500,1000],'Doces':[250,500,1000],'Mel e apícolas':[250,500,1000],'Conservas e temperos':[100,250,500],'Grãos':[500,1000,5000],'Hortifruti-Granjeiro':[500,1000,2000],'Carnes e aves':[500,1000,2000],'Piscicultura':[500,1000,2000],'Panificação':[50,100,500],'Bolos':[500,1000,1500],'Beleza':[50,100,200],'Outros':[250,500,1000]};
const VOLUME_PRESETS={'Bebidas':[300,600,1000],'Laticínios':[200,500,1000]};
const baseDimensionOptions=dimensionOptions;
dimensionOptions=function(field,index){const all=baseDimensionOptions(field,index),presets=(field==='weight'?WEIGHT_PRESETS:field==='volume'?VOLUME_PRESETS:{})[productForm&&productForm.category];if(!presets)return all;const rest=all.filter(x=>!presets.some(p=>String(p)===String(x)));return [...presets,...rest];};

// Venda com vários produtos: estado de cada produto (ativo, com quantidade, pendente).
function draftGroupStates(){if(!draft)return [];const groups=[];draft.items.forEach((line,index)=>{const p=model.product(line.productId);if(!p)return;const key=familyKey(p);let g=groups.find(x=>x.key===key);if(!g){g={key,indices:[]};groups.push(g);}g.indices.push(index);});return groups.map(g=>({active:!draft.quantityReviewCollapsed&&g.indices.includes(draft.active),done:g.indices.some(i=>E.number(draft.items[i].rawQty)>0)}));}

// Histórico da Loja (Vendas da semana) reorganizado: período claro, locais em linha, dias com total
// na mesma linha e cada venda com horário, pagamento, valor e itens um por linha.
function weekLabel(start,current){const diff=Math.round((Date.parse(current+'T12:00:00Z')-Date.parse(start+'T12:00:00Z'))/(7*864e5));return diff===0?'Esta semana':diff===1?'Semana passada':diff>1?'Há '+diff+' semanas':'Próxima semana';}
function weeklyPageClean(){const data=weekData(),fmt=(day,o)=>new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',o),weekEnd=shiftDay(weekStart,6),days=Array.from({length:7},(_,i)=>shiftDay(weekStart,i)),thisWeek=monday(E.dayKey(new Date()));
 const daily=day=>data.sales.filter(s=>E.dayKey(s.date)===day).sort((a,b)=>new Date(b.date)-new Date(a.date));
 const saleRow=s=>btn('sale-detail','<span class="hs-top"><span class="hs-time">'+new Date(s.date).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'})+' · '+escape(s.payments.map(p=>p.method).join(' + '))+(s.status==='returned'?' · <em>Devolvida</em>':'')+'</span><strong class="tabular">'+E.money(s.total)+'</strong></span><span class="hs-items">'+s.items.map(i=>'<span>'+E.quantity(i.qty)+'× '+escape(titleName(i.name))+'<small>'+escape(i.description)+'</small></span>').join('')+'</span>','hs-sale'+(s.status==='returned'?' is-returned':''),{id:s.id});
 const dayCard=day=>{const sales=daily(day),completed=sales.filter(s=>s.status==='completed'),total=completed.reduce((n,s)=>n+s.total,0),open=weekDaysOpen.has(day)||!!weekQuery;
  return '<section class="hs-day">'+btn('week-day','<span class="hs-day-name"><strong>'+escape(fmt(day,{weekday:'long'}))+'</strong><small>'+escape(fmt(day,{day:'numeric',month:'long'}))+' · '+grammarCount(completed.length,'venda','vendas')+'</small></span><span class="hs-day-total tabular">'+E.money(total)+'</span>'+icon(open?'down':'chevron'),'hs-day-head',{day})+(open?'<div class="hs-sales">'+(sales.length?sales.map(saleRow).join(''):'<p class="hs-empty">Nenhuma venda neste dia.</p>')+'</div>':'')+'</section>';};
 const withSales=days.filter(d=>daily(d).length).reverse(),empty=days.filter(d=>!daily(d).length);
 const head=header('Vendas','weekly-back').replace('<span class="spacer"></span>',btn('weekly-search',icon('search'),'title-search'));
 return '<div class="subview hs">'+head
 +'<div class="hs-period">'+btn('week-shift',icon('back'),'hs-arrow',{delta:-1})+'<span class="hs-range"><strong>'+escape(fmt(weekStart,{month:'short'})===fmt(weekEnd,{month:'short'})?fmt(weekStart,{day:'numeric'})+' – '+fmt(weekEnd,{day:'numeric',month:'short'}):fmt(weekStart,{day:'numeric',month:'short'})+' – '+fmt(weekEnd,{day:'numeric',month:'short'}))+'</strong><small>'+weekLabel(weekStart,thisWeek)+' · '+fmt(weekEnd,{year:'numeric'})+'</small></span>'+btn('week-shift',icon('chevron'),'hs-arrow',{delta:1})+'</div>'
 +'<div class="feira-chips hs-scopes" role="group" aria-label="Local">'+btn('week-scope','Loja','chip'+(scope==='loja'?' selected':''),{scope:'loja'})+model.data.events.map(e=>btn('week-scope',escape(e.name),'chip'+(scope===e.id?' selected':''),{scope:e.id})).join('')+'</div>'
 +(weekSearchOpen?'<label class="feira-search">'+icon('search')+'<input id="week-search" aria-label="Buscar venda" placeholder="Buscar produto, cliente ou pagamento" value="'+escape(weekQuery)+'"></label>':'')
 +'<section class="hs-summary"><small>'+escape(scopeName(scope))+' · semana</small><strong class="tabular">'+E.money(data.total)+'</strong><div class="hs-summary-stats"><span><b class="tabular">'+data.count+'</b> '+(data.count===1?'venda':'vendas')+'</span><span><b class="tabular">'+(data.count?E.money(Math.round(data.total/data.count)):'—')+'</b> por venda</span></div></section>'
 +(withSales.length?withSales.map(dayCard).join(''):'<p class="hs-empty hs-empty-week">Nenhuma venda nesta semana.</p>')
 +(empty.length&&withSales.length?'<p class="hs-empty-days">'+grammarCount(empty.length,'dia','dias')+' sem vendas: '+escape(empty.map(d=>fmt(d,{weekday:'short'}).replace('.','')).join(', '))+'</p>':'')
 +'</div>';}
const weeklyPageLegacy=weeklyPage;
weeklyPage=function(){return isFeira()?weeklyPageClean():weeklyPageLegacy();};
// Gestão no estilo Feira: o gráfico cronológico dá lugar ao ordenado.
const feiraHeroBase=feiraHero;
feiraHero=function(sel,m){const html=feiraHeroBase(sel,m),cut=html.indexOf('<section class="feira-chart"'),visible=!!model.data.settings.financialVisible;let hero=cut>=0?html.slice(0,cut):html,chart=feiraChartSorted(sel,m);
 // Valores escondidos: some o dinheiro (receita, ticket, resultado e valores das barras); a quantidade de vendas fica.
 if(!visible){hero=hero.replace(/R\$(&nbsp;|\s)?-?[\d.,]+/g,'••••••').replace('class="feira-hero-value"','class="feira-hero-value is-hidden"');chart=chart.replace(/<text[^>]*class="bar-value"[^>]*>[^<]*<\/text>/g,'');}
 const eye='<button type="button" data-action="toggle-financial" class="hero-eye" aria-label="'+(visible?'Ocultar':'Mostrar')+' valores" aria-pressed="'+visible+'">'+icon(visible?'eye':'eyeOff')+'</button>';
 hero=hero.replace(/<strong>([^<]+)<\/strong>/g,(tag,text)=>{const n=text.replace(/&nbsp;/g,' ').length;return n>=13?'<strong class="long xlong">'+text+'</strong>':n>=10?'<strong class="long">'+text+'</strong>':tag;}); // valores longos (ex.: R$ 1.234,56) diminuem para caber
 return hero.replace('<section class="feira-hero" aria-label="Resumo do período">',tag=>(m.result<0?tag.replace('class="feira-hero"','class="feira-hero is-negative"'):tag)+eye)+chart;};

// Gráfico: barras do menor para o maior, da esquerda para a direita, com o dia de cada uma.
function feiraChartSorted(sel,m){const entries=Object.entries(m.daily).filter(([day,v])=>v>0&&(!sel.month||day.slice(0,7)===sel.month)).sort((a,b)=>a[1]-b[1]);
 if(!entries.length)return '<section class="feira-chart"><h2>Receita por dia</h2><p class="feira-chart-empty">Sem vendas neste período.</p></section>';
 const max=entries[entries.length-1][1],W=320,H=150,n=entries.length,step=W/Math.max(n,4),bw=Math.min(36,step*0.62),x0=(W-step*n)/2;
 const bars=entries.map(([day,v],i)=>{const h=Math.max(4,v/max*(H-40)),x=x0+i*step+(step-bw)/2,y=H-22-h;return '<rect class="chart-bar" x="'+x.toFixed(1)+'" y="'+y.toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+h.toFixed(1)+'" rx="5"><title>'+dateBR(day)+': '+E.money(v)+'</title></rect>'+(n<=10?'<text x="'+(x+bw/2).toFixed(1)+'" y="'+(y-6).toFixed(1)+'" text-anchor="middle" class="bar-value">'+E.money(v).replace(/\s/g,' ').replace(',00','')+'</text>':'')+'<text x="'+(x+bw/2).toFixed(1)+'" y="'+H+'" text-anchor="middle">'+Number(day.slice(8))+'/'+day.slice(5,7)+'</text>';}).join('');
 return '<section class="feira-chart"><h2>Receita por dia</h2><p class="feira-chart-note">Do dia que menos vendeu para o que mais vendeu</p><svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Receita por dia, do menor para o maior">'+bars+'</svg></section>';}

// CSV: planilha geral com tudo e uma planilha por evento.
function exportScoped(scopeId,name){const previous=dataScope;dataScope=scopeId;try{exportCSV(name,generalRows());}finally{dataScope=previous;}}
Object.assign(actions,{
 'export-everything':()=>exportScoped('all','agro-gestao-planilha-geral.csv'),
 'export-event':d=>{const e=model.data.events.find(x=>x.id===d.id);if(e)exportScoped(e.id,'evento-'+E.normalize(e.name).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+e.start+'.csv');}
});

// --- Aviso de feira: cartão com a data em destaque ---
const reminderBannerLegacy=reminderBanner;
reminderBanner=function(){const notices=eventReminders();if(!notices.length)return '';const r=notices[0],e=r.event,today=E.dayKey(Date.now()),days=Math.round((Date.parse(e.start+'T12:00:00Z')-Date.parse(today+'T12:00:00Z'))/864e5);
 const when=days<=0?'A feira é hoje':days===1?'A feira é amanhã':'Feira em '+days+' dias',parts=String(r.text).split(/[.!]\s+/).filter(Boolean),todo=(parts.length>1?parts.slice(1).join('. '):parts[0]).replace(/\.$/,'');
 const d=new Date(e.start+'T12:00:00Z'),month=d.toLocaleDateString('pt-BR',{month:'short',timeZone:'UTC'}).replace('.','');
 return '<section class="fair-card fair-prep'+(days<=1?' is-soon':'')+'" role="status">'+btn('open-reminders','<span class="fc-date" aria-hidden="true"><b>'+d.getUTCDate()+'</b><small>'+escape(month)+'</small></span><span class="fc-text"><small>'+escape(when)+'</small><strong>'+escape(e.name)+'</strong><span>Confira produtos, troco e montagem.</span><span class="fc-cta">Preparar feira '+icon('chevron')+'</span></span>','fc-main')+btn('reminder-dismiss',icon('close')+'<span class="sr-only">Dispensar aviso</span>','fc-close',{key:r.key})+'</section>';};

// --- Reposição rápida: até 4 produtos por vez, teclado próprio ---
let restock=null;
function openRestock(ids){let products=[...new Set(ids.map(id=>model.product(id)?.id).filter(Boolean))].map(id=>model.product(id));if(window.TerritorioStockOrder)products=window.TerritorioStockOrder.orderStockProducts(products);ids=products.map(p=>p.id);if(!ids.length)return;restock={ids,page:0,values:{},active:ids[0]};paintRestock();}
function paintRestock(){const r=restock;if(!r)return;const pages=Math.ceil(r.ids.length/4),pageIds=r.ids.slice(r.page*4,r.page*4+4),last=r.page>=pages-1,active=model.product(r.active),decimal=active&&['kg','Litro','g','ml'].includes(active.unit);
 const rows=pageIds.map(id=>{const p=model.product(id),on=id===r.active,value=r.values[id]||'';return btn('restock-pick','<span class="rr-name"><strong>'+escape(titleName(p.name))+'</strong><small>Agora: '+E.quantity(p.stock)+' '+escape(E.unitLabel(p.unit,p.stock))+'</small></span><span class="rr-value'+(value?'':' empty')+'"><span class="tabular">'+(value||'0')+'</span><small>'+escape(shortUnit(p.unit))+'</small></span>','restock-row'+(on?' active':''),{id});}).join('');
 const keys=[1,2,3,4,5,6,7,8,9].map(n=>btn('restock-digit',String(n),'restock-key',{digit:n})).join('')+(decimal?btn('restock-digit',',','restock-key',{digit:','}):'<span aria-hidden="true"></span>')+btn('restock-digit','0','restock-key',{digit:0})+btn('restock-erase',icon('backspace')+'<span>Corrigir</span>','restock-key restock-erase');
 openModal('Repor estoque','<div class="restock-intro"><p>'+(r.ids.length>1?'Toque no produto e digite quanto chegou.':'Digite a quantidade que chegou.')+'</p>'+(pages>1?'<span>'+String(r.page+1)+' / '+pages+'</span>':'')+'</div><div class="restock-rows">'+rows+'</div><div class="restock-keypad" role="group" aria-label="Teclado de quantidade">'+keys+'</div>','restock',null,'<div class="restock-footer-actions">'+(last?'':btn('restock-next','Próximos','restock-next'))+btn('restock-finish','Finalizar','success')+'</div>');}
async function finishRestock(){const r=restock;if(!r||r.saving)return;r.saving=true;const button=document.querySelector('[data-action="restock-finish"]');if(button)button.disabled=true;
 try{
  let summary=r.pendingApplied;
  if(!summary){const before=JSON.stringify(model.data);let done=0;const missing=[],failed=[];
   for(const id of r.ids){const p=model.product(id),raw=r.values[id];if(!raw||!(E.number(raw)>0)){missing.push(titleName(p.name));continue;}try{model.move(id,'add',raw,'Reposição');done++;}catch(e){failed.push(titleName(p.name));}}
   summary={done,missing,failed};
   if(done&&!persist()){model=new E.ERPModel(JSON.parse(before));throw Error('Não foi possível salvar a reposição. Libere espaço.');}
   r.pendingApplied=summary;
  }
  if(summary.done&&window.TerritorioNative?.durable&&!await window.TerritorioNative.durable())throw Error('A gravação está pendente. Libere espaço; o app tenta novamente. As quantidades não serão aplicadas de novo.');
  const {done,missing,failed}=summary;restock=null;closeModal();render();const list=n=>n.length>2?n.slice(0,2).join(', ')+' e mais '+(n.length-2):n.join(' e ');
  if(!done)toast('Estoque não renovado'+(missing.length?': '+list(missing):'')+'.');
  else if(missing.length||failed.length)toast('Estoque não renovado: '+list([...missing,...failed])+'. Os demais foram atualizados.');
  else toast('Estoque renovado: '+grammarCount(done,'produto','produtos')+'.');
 }catch(error){r.saving=false;if(button)button.disabled=false;toast(error.message);}
}
function stockLevels(){return model.data.products.map(p=>{const r=stockRatio(p);return{id:p.id,name:titleName(p.name),detail:weightLabel(p),stock:p.stock,unit:E.unitLabel(p.unit,p.stock),ratio:r.reference>0?r.ratio:null};});}

