 'cloud-backup-confirm':()=>{if(!pendingBackupCode)return;model.data.cloudBackup={enabled:true,secret:pendingBackupCode};pendingBackupCode='';persist();cloudBackupModal();window.TerritorioBackup.syncNow();toast('Backup automático ligado.');},
 'cloud-backup-now':()=>window.TerritorioBackup.syncNow(),
