 'cloud-code-share':d=>{if(!navigator.share)return actions['cloud-code-copy'](d);navigator.share({title:'Código de recuperação do AGRO Gestão',text:'Código de recuperação do backup do AGRO Gestão:\n'+d.code+'\nGuarde em lugar seguro: ele abre os dados do seu negócio.'}).catch(()=>{});},
 'cloud-backup-disable':()=>openModal('Desligar o backup automático?','<p class="dialog-text">As próximas alterações deixam de ser enviadas. Você pode manter a última cópia na nuvem para restaurar depois, ou apagá-la.</p>','cloud-backup-off',null,btn('cloud-backup-off-keep','Desligar e manter a cópia','primary modal-action')+btn('cloud-backup-off-delete','Desligar e apagar a cópia','danger modal-action')+btn('cloud-backup','Voltar','link-row')),
 'cloud-backup-off-keep':()=>{setBackupState({enabled:false,waiting:false,error:''});cloudBackupModal();toast('Backup automático desligado.');},
 'cloud-backup-off-delete':async()=>{const b=model.data.cloudBackup;try{if(b&&b.secret)await window.TerritorioBackup.deleteRemote(b.secret);delete model.data.cloudBackup;persist();closeModal();if(page==='Dados')render();toast('Backup automático desligado e cópia apagada.');}catch(e){toast(e.message);}},
 'restore-options':()=>openModal('Importar ou restaurar','<p class="dialog-text">Os dados atuais deste celular serão substituídos pela cópia escolhida.</p>','restore-options',null,btn('import-backup-picker','Arquivo de backup (.json)','primary modal-action')+btn('cloud-restore','Backup automático (código de recuperação)','primary modal-action')+btn('close-modal','Cancelar','link-row')),
 'cloud-restore':()=>openModal('Restaurar com código','<p class="dialog-text">Digite o código de recuperação que apareceu quando o backup automático foi ligado.</p><label for="recovery-code">Código de recuperação</label><input id="recovery-code" class="recovery-input" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX-XXXX">','cloud-restore',null,btn('cloud-restore-fetch','Buscar cópia','success modal-action')+btn('close-modal','Cancelar','link-row')),
 'cloud-restore-fetch':async()=>{const input=document.getElementById('recovery-code'),button=document.querySelector('[data-action="cloud-restore-fetch"]');if(!input)return;if(button){button.disabled=true;button.textContent='Buscando…';}
  try{const found=await window.TerritorioBackup.fetchRestore(input.value),d=found.data||{};if(d.schema!==1||!Array.isArray(d.products)||!Array.isArray(d.sales)||!Array.isArray(d.clients))throw Error('A cópia não tem o formato esperado.');pendingCloudRestore=found;
   openModal('Restaurar esta cópia?','<p class="dialog-text">Cópia de '+backupDate(found.savedAt)+': '+grammarCount(d.products.length,'produto','produtos')+', '+grammarCount(d.sales.length,'venda','vendas')+' e '+grammarCount(d.clients.length,'cliente','clientes')+'.</p><p class="dialog-text">Os dados atuais deste celular serão substituídos.</p>','cloud-restore-confirm',null,btn('cloud-restore-apply','Restaurar','danger modal-action')+btn('close-modal','Cancelar','link-row'));}
  catch(e){if(button){button.disabled=false;button.textContent='Buscar cópia';}toast(e.message);}},
 'cloud-restore-apply':()=>{const found=pendingCloudRestore;if(!found)return;pendingCloudRestore=null;try{applyBackupData(found.data);model.data.cloudBackup={enabled:true,secret:found.code,savedAt:found.savedAt,verifiedAt:new Date().toISOString(),sha256:found.sha256};persist();if(page==='Dados')render();}catch(e){toast('Não foi possível restaurar: '+e.message);}},
 'toggle-backup-reminder':()=>{const st=model.data.settings;st.backupReminder=st.backupReminder===false;persist();render();toast(st.backupReminder?'Vamos lembrar você de fazer backup toda semana.':'Lembrete de backup desligado.');},
