// --- Leitura automática do QR (src/features/portfolio.js consulta o servidor) ---
function portfolioTracked(destination){const p=model.data.portfolio;return !!(p&&p.publishedAt&&destination&&destination.kind==='catalog'&&destination.payload&&destination.payload===safePublicURL(p.url));}
function newQrRef(){const alphabet='abcdefghjkmnpqrstuvwxyz23456789';return [...crypto.getRandomValues(new Uint8Array(8))].map(n=>alphabet[n%alphabet.length]).join('');}
function storyPayload(destination,pending){if(!pending||!portfolioTracked(destination))return destination.payload;pending.qrRef=pending.qrRef||newQrRef();return destination.payload+'?r='+pending.qrRef;}
function qrReadSummary(sales){const read=sales.filter(s=>s.qrReadAt),auto=read.filter(s=>s.qrReadSource==='auto').length;return grammarCount(read.length,'leitura','leituras')+(auto?' · '+grammarCount(auto,'automática','automáticas'):'');}
function qrWatchState(){if(!modal||!['story','qr-zoom'].includes(modal.kind))return null;const pending=modal.data&&(modal.data.pending||modal.data.id==='pending');if(pending)return recipientPending&&recipientPending.qrRef&&!recipientPending.qrReadAt?{ref:recipientPending.qrRef,pending:true}:null;const sale=model.data.sales.find(s=>s.id===(modal.data&&modal.data.id));return sale&&sale.qrRef&&!sale.qrReadAt?{ref:sale.qrRef,id:sale.id}:null;}
function qrRefs(){const cutoff=Date.now()-85*864e5;return{watching:qrWatchState(),unread:model.data.sales.filter(s=>s.qrRef&&!s.qrReadAt&&s.status==='completed'&&Date.parse(s.date)>cutoff).map(s=>s.qrRef)};}
function markQrRead(found){const watched=qrWatchState();let changed=0;
 if(recipientPending&&recipientPending.qrRef&&!recipientPending.qrReadAt&&recipientPending.qrRef in found){recipientPending.qrReadAt=found[recipientPending.qrRef]||new Date().toISOString();recipientPending.qrReadSource='auto';changed++;}
 for(const s of model.data.sales)if(s.qrRef&&!s.qrReadAt&&s.qrRef in found){s.qrReadAt=found[s.qrRef]||new Date().toISOString();s.qrReadSource='auto';changed++;}
 if(!changed)return 0;persist();
 if(watched&&watched.ref in found){storyModal(watched.pending?undefined:watched.id);toast('QR lido pelo cliente.');}else if(!dialog.open)render();
 return changed;}
// --- Venda de evento para empresa ---
function eventCompanyOn(){if(!recipientPending)return false;if(typeof recipientPending.eventCompany==='boolean')return recipientPending.eventCompany;return recordPersonType(recipientPending.draft)==='PJ';}
function eventCompanyControl(sale,state){if(sale)return sale.scope!=='loja'&&recordPersonType(sale)==='PJ'?'<p class="event-company-note">'+icon('check')+' Comprador: empresa (CNPJ)</p>':'';if(!state.event||!recipientPending)return '';const on=eventCompanyOn();return '<button type="button" data-action="toggle-event-company" class="client-row event-company" role="switch" aria-checked="'+on+'"><span>Comprador é empresa (CNPJ)<small>A venda continua contando para o evento.</small></span><span class="switch'+(on?' on':'')+'"><i></i></span></button>';}
Object.assign(actions,{'toggle-event-company':()=>{if(!recipientPending||recipientPending.busy)return;recipientPending.eventCompany=!eventCompanyOn();storyModal();}});

// --- Portfólio online (publicação feita por src/features/portfolio.js) ---
function producerPhotoField(st){return '<div class="producer-photo-field"><img src="'+escape(st.photo||PROFILE_PHOTO)+'" alt=""><div><strong>Foto do produtor</strong><small>Aparece no topo do seu portfólio online.</small><label class="catalog-upload">'+icon('upload')+' '+(st.photo?'Trocar foto':'Escolher foto')+'<input id="producer-photo" type="file" accept="image/png,image/jpeg,image/webp"></label></div></div>'+(st.photo?'':'<p class="settings-note">O retrato de Luiz Claudio é fictício, gerado por IA para esta prévia.</p>');}
function squarePhoto(file,size){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const side=Math.min(img.width,img.height),canvas=document.createElement('canvas');canvas.width=canvas.height=size;canvas.getContext('2d').drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,size,size);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.88));};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Não foi possível abrir a foto.'));};img.src=url;});}
document.addEventListener('change',async event=>{if(event.target.id!=='producer-photo'||!event.target.files[0])return;try{model.data.settings.photo=await squarePhoto(event.target.files[0],512);if(!persist())return toast('Não foi possível salvar a foto. Libere espaço.');const preview=document.querySelector('.producer-photo-field img');if(preview)preview.src=model.data.settings.photo;render();toast('Foto salva. Atualize o portfólio online para publicá-la.');}catch(e){toast(e.message);}});
function portfolioDate(iso){return new Date(iso).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).replace(',',' às');}
function portfolioPanel(){const p=model.data.portfolio,svc=window.TerritorioPortfolio,available=!!(svc&&svc.available),busy=available&&svc.busy(),live=!!(p&&p.publishedAt);
 return '<section class="panel portfolio-online"><div class="row"><h2>Portfólio online</h2><span class="badge'+(live?' portfolio-live':'')+'">'+(live?'NO AR':'NÃO PUBLICADO')+'</span></div>'
 +'<p class="small muted">'+(live?'Atualizado em '+portfolioDate(p.publishedAt)+'. Atualize sempre que mudar preços, fotos ou feiras.':'Uma página com sua história, produtos, próximas feiras e contato. O QR mostrado após cada venda abre essa página no celular do cliente.')+'</p>'
 +(live?'<p class="portfolio-url">'+escape(p.url.replace(/^https?:\/\//,''))+'</p>':'')
 +'<div class="portfolio-actions">'+btn('portfolio-publish',busy?'Publicando…':live?'Atualizar página':'Publicar página','success',null,busy||!available)+(live?'<div class="two">'+btn('portfolio-open','Ver página','primary')+btn('portfolio-copy','Copiar link','primary')+'</div>':'')+'</div>'
 +(live?btn('portfolio-unpublish','Tirar a página do ar','link portfolio-remove',null,busy):'')
 +(available?'':'<p class="settings-note">A publicação online ainda não está configurada nesta versão do app.</p>')+'</section>';}
function portfolioSource(){const st=model.data.settings,c=model.data.catalog,today=E.dayKey(Date.now());
 return{business:{name:c.title||st.businessName,producer:st.producerName,city:st.city,uf:st.uf,story:c.story},
 contact:{whatsapp:st.phone,email:st.email,instagram:safePublicURL(st.instagram),website:safePublicURL(st.website)},
 photo:st.photo||'',atlas:CATALOG_PHOTOS,
 groups:catalogGroups().map(group=>{const p=group[0],photos=c.photos||{},own=photos[p.id]||p.photo||presentations(p).map(v=>photos[v.id]||v.photo).find(Boolean)||'';return{name:titleName(p.name),category:p.category,unavailable:group.every(v=>v.stock<=0),variants:group.map(v=>({productId:v.id,unit:v.unit,label:[v.format,weightLabel(v)].filter(Boolean).join(' · '),price:v.price})),photo:own,atlasIndex:own||model.data.dataContext?.type!=='demo'&&model.data.settings.onboarding!=='demo'?null:photoIndex(p)};}),
 events:model.data.events.filter(e=>e.status!=='finished'&&(e.end||e.start)>=today).sort((a,b)=>a.start.localeCompare(b.start)).slice(0,8).map(e=>({name:e.name,place:e.place,start:e.start,end:e.end,from:e.from,until:e.until})),
 pdf:()=>prepareCatalogPDF().then(cache=>cache.blob)};}
function setPortfolio(state){const c=model.data.catalog,previous=model.data.portfolio;if(state){model.data.portfolio=state;if(state.publishedAt)c.publicUrl=state.url;}else{if(previous&&c.publicUrl===previous.url)c.publicUrl='';delete model.data.portfolio;}const ok=persist();render();return ok;}
function openExternal(url){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';document.body.appendChild(a);a.click();a.remove();}
Object.assign(actions,{
 'portfolio-publish':async()=>{try{await window.TerritorioPortfolio.publish();toast('Página publicada. O QR já abre seu portfólio.');}catch(e){toast(e.message);}},
 'portfolio-open':()=>{const p=model.data.portfolio;if(p&&p.url)openExternal(p.url);},
 'portfolio-copy':async()=>{const p=model.data.portfolio;if(!p)return;try{await navigator.clipboard.writeText(p.url);toast('Link copiado.');}catch(e){toast(p.url);}},
 'portfolio-unpublish':()=>openModal('Tirar a página do ar?','<p class="dialog-text">O QR e o link deixam de abrir seu portfólio. Você pode publicar de novo quando quiser, mas o endereço será outro.</p>','portfolio-unpublish',null,btn('portfolio-unpublish-confirm','Tirar do ar','danger modal-action')+btn('close-modal','Cancelar','link-row')),
 'portfolio-unpublish-confirm':async()=>{closeModal();try{await window.TerritorioPortfolio.unpublish();toast('Página retirada do ar.');}catch(e){toast(e.message);}}
});

window.TerritorioShell={
 canSelectProduct,
 page:()=>page,
 refresh:()=>render(),
 portfolioSource,
 portfolioState:()=>model.data.portfolio||null,
 setPortfolio,
 qrRefs,
 markQrRead,
 backupState:()=>model.data.cloudBackup||null,
 setBackupState,
 refreshBackup:refreshBackupViews,
 backupSource,
 backupReminder,
 askBackup,
 idle:shellIdle,
 stockLevels,
 draftGroupStates,
 openRestock,
 // Android back: dismiss the top-most layer, like Esc does on the web. Returns false at the root.
 back(){
  const picker=document.getElementById('date-picker-dialog');
  if(picker&&picker.open){closeDatePicker();return true;}
  if(document.querySelector('#number-pad:not([hidden]),#dialog-number-pad:not([hidden])')){closeNumberPad();return true;}
  if(dialog.open){const cancel=new Event('cancel',{cancelable:true});if(dialog.dispatchEvent(cancel)&&dialog.open)dialog.close();return true;}
  const subBack=app.querySelector('.subheader [data-action]');
  if(subBack){subBack.click();return true;}
  if(page!=='Vender'){actions.nav({page:'Vender'});return true;}
  return false;
 }
};
// Rodapé: reaproveita os botões existentes; assim a caixa do Estoque pode fechar ao sair.
const navigationBase=navigation;
navigation=function(){const buttons=[...nav.querySelectorAll('button[data-page]')];if(buttons.length!==5){navigationBase();return;}
 nav.hidden=['Venda','Produto','Semana','Inteligência','Ajustes','Dados','Catálogo','Estúdio'].includes(page);const glass=document.getElementById('nav-glass');if(glass)glass.hidden=nav.hidden;
 buttons.forEach(b=>{const on=b.dataset.page===page;if(b.classList.contains('active')!==on){b.classList.toggle('active',on);if(!on){b.classList.add('leaving');clearTimeout(b._leaving);b._leaving=setTimeout(()=>b.classList.remove('leaving'),500);}else b.classList.remove('leaving');}const label=b.querySelector('span');if(label&&label.textContent!==pageLabel(b.dataset.page))label.textContent=pageLabel(b.dataset.page);});};
// --- Gestão (estilo Feira): período no topo, card 3D, gráfico, orientação enxuta e detalhes numa lista ---
// Período: Dia, Semana, Mês ou Ano, com setas para andar no tempo; os locais ficam em pílulas logo abaixo.
let periodMode='mes',periodAnchor=E.dayKey(Date.now());
const PERIOD_MODES=[['dia','Dia'],['semana','Semana'],['mes','Mês'],['ano','Ano']];
function periodDays(mode,anchor){if(mode==='dia')return [anchor];if(mode==='semana'){const back=(new Date(anchor+'T12:00:00Z').getUTCDay()+6)%7;return Array.from({length:7},(_,i)=>shiftDay(anchor,i-back));}return [];}
function periodSelection(mode,anchor){return {month:mode==='dia'||mode==='mes'?anchor.slice(0,7):'',year:mode==='ano'?anchor.slice(0,4):'',days:periodDays(mode,anchor),scope:managementScope,from:'',until:'',periodMode:mode,periodAnchor:anchor};}
function shiftPeriod(mode,anchor,delta){if(mode==='dia')return shiftDay(anchor,delta);if(mode==='semana')return shiftDay(anchor,7*delta);const d=new Date(anchor.slice(0,7)+'-15T12:00:00Z');if(mode==='mes')d.setUTCMonth(d.getUTCMonth()+delta);else d.setUTCFullYear(d.getUTCFullYear()+delta);return d.toISOString().slice(0,10);}
function periodLabel(mode,anchor){const today=E.dayKey(Date.now()),fmt=(day,o)=>new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',Object.assign({timeZone:'UTC'},o)),cap=t=>t.charAt(0).toUpperCase()+t.slice(1);
 if(mode==='dia')return [fmt(anchor,{day:'numeric',month:'long'}),anchor===today?'Hoje':anchor===shiftDay(today,-1)?'Ontem':cap(fmt(anchor,{weekday:'long'}))+' · '+anchor.slice(0,4)];
 if(mode==='semana'){const d=periodDays(mode,anchor),a=d[0],b=d[6];return [(a.slice(0,7)===b.slice(0,7)?Number(a.slice(8)):fmt(a,{day:'numeric',month:'short'}).replace('.',''))+' – '+fmt(b,{day:'numeric',month:'short'}).replace('.',''),(d.includes(today)?'Esta semana':d.includes(shiftDay(today,-7))?'Semana passada':'Semana')+' · '+b.slice(0,4)];}
 if(mode==='mes')return [cap(fmt(anchor.slice(0,7)+'-15',{month:'long',year:'numeric'})),anchor.slice(0,7)===today.slice(0,7)?'Este mês':''];
 return [anchor.slice(0,4),anchor.slice(0,4)===today.slice(0,4)?'Este ano':''];}
function periodIsFuture(mode,anchor){const today=E.dayKey(Date.now()),next=shiftPeriod(mode,anchor,1);return mode==='dia'?next>today:mode==='semana'?periodDays(mode,next)[0]>today:mode==='mes'?next.slice(0,7)>today.slice(0,7):next.slice(0,4)>today.slice(0,4);}

// A seleção da Gestão (nos dois estilos) vem do período escolhido no topo.
const selectionBase=selection;
selection=function(){return periodSelection(periodMode,periodAnchor);};
const matchesSelectionBase=matchesSelection;
matchesSelection=function(record,sel){if(sel&&sel.year&&E.dayKey(record.date).slice(0,4)!==sel.year)return false;return matchesSelectionBase(record,sel);};
const previousSelectionBase=previousSelection;
previousSelection=function(sel){return sel&&sel.periodMode?periodSelection(sel.periodMode,shiftPeriod(sel.periodMode,sel.periodAnchor,-1)):previousSelectionBase(sel);};
const periodTextBase=periodText;
periodText=function(sel){if(!sel||!sel.periodMode)return periodTextBase(sel);const [title,sub]=periodLabel(sel.periodMode,sel.periodAnchor);return title+(sub?' · '+sub:'');};

// Painel de controle: um cartão só com o tipo de período, o período (‹ ›) e o local (abre uma folha).
function mgScopeOptions(){const events=model.data.events.filter(e=>e.status!=='finished'||model.data.sales.some(s=>s.scope===e.id)).sort((a,b)=>b.start.localeCompare(a.start));return [['all','Todos os locais',''],['loja','Loja','Vendas fora de feiras'],...(events.length>1?[['events','Todas as feiras','']]:[]),...events.map(e=>[e.id,e.name,eventDateLabel(e)])];}
function mgScopeLabel(){const o=mgScopeOptions().find(([id])=>id===managementScope);return o?o[1]:reportScopeName(managementScope);}
function periodBar(){const [title,sub]=periodLabel(periodMode,periodAnchor);
 return '<section class="mg-period" aria-label="Período e local">'
 +'<div class="mg-seg">'+PERIOD_MODES.map(([id,name])=>btn('mg-period-mode',name,periodMode===id?'on':'',{mode:id})).join('')+'</div>'
 +'<div class="mg-step">'+btn('mg-period-shift',icon('back')+'<span class="sr-only">Período anterior</span>','mg-arrow',{delta:-1})+'<span class="mg-range" aria-live="polite"><strong>'+escape(title)+'</strong>'+(sub?'<small>'+escape(sub)+'</small>':'')+'</span>'+btn('mg-period-shift',icon('chevron')+'<span class="sr-only">Próximo período</span>','mg-arrow',{delta:1},periodIsFuture(periodMode,periodAnchor))+'</div>'
 +btn('mg-scope-picker','<span class="mg-ico">'+icon('store')+'</span><span class="mg-scope-text"><small>Local</small><strong>'+escape(mgScopeLabel())+'</strong></span>'+icon('down'),'mg-scope')+'</section>';}
function mgScopeSheet(){return '<div class="mg-scope-list" role="listbox" aria-label="Local das vendas">'+mgScopeOptions().map(([id,name,note])=>btn('mg-scope','<span><strong>'+escape(name)+'</strong>'+(note?'<small>'+escape(note)+'</small>':'')+'</span>'+(managementScope===id?'<span class="picker-check" aria-hidden="true">✓</span>':''),'mg-scope-option'+(managementScope===id?' selected':''),{scope:id})).join('')+'</div>';}
Object.assign(actions,{
 'mg-scope-picker':()=>openModal('Local das vendas',mgScopeSheet(),'mg-detail'),
 'mg-scope':d=>{if(!mgScopeOptions().some(([id])=>id===d.scope))return;managementScope=d.scope;closeModal();render();}
});

const pct=(part,total)=>(total?part/total*100:0).toLocaleString('pt-BR',{maximumFractionDigits:0})+'%';
function mgSources(m){const map=new Map();m.sales.forEach(s=>{const id=s.scope||'loja';map.set(id,(map.get(id)||0)+s.total);});return [...map].sort((a,b)=>b[1]-a[1]).map(([id,v])=>[scopeName(id),v]);}
function mgCustomers(m){const r={PF:0,PJ:0,none:0};m.sales.forEach(s=>{const c=s.customerId&&model.data.clients.find(c=>c.id===s.customerId);if(!c)r.none++;else r[c.personType==='PJ'?'PJ':'PF']++;});return r;}
function mgBestDay(m){const totals=new Map();Object.entries(m.daily).forEach(([day,v])=>{const w=new Date(day+'T12:00:00Z').getUTCDay();totals.set(w,(totals.get(w)||0)+v);});const best=[...totals].sort((a,b)=>b[1]-a[1])[0];return best?['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'][best[0]]:'';}
function mgBars(rows,total){const max=Math.max(1,...rows.map(r=>r[1]));return rows.map(([name,v])=>'<div class="management-rank-row"><span class="management-ranking-label"><span>'+escape(name)+'</span><strong class="tabular">'+pct(v,total)+' · '+E.money(v)+'</strong></span><span class="track"><span class="bar" style="width:'+v/max*100+'%"></span></span></div>').join('');}
const openSection=html=>html.replace('<details class="panel management-section"','<details open class="panel management-section mg-in-sheet"');
const hideMoney=html=>model.data.settings.financialVisible?html:html.replace(/R\$(&nbsp;|\s)?-?[\d.,]+/g,'••••••');

function mgRow(key,ico,title,sub){return btn('mg-detail','<span class="mg-ico">'+icon(ico)+'</span><span class="mg-text"><strong>'+title+'</strong><small>'+escape(sub)+'</small></span>'+icon('chevron'),'mg-row',{key});}
function mgRows(sel,m){const none='Sem vendas no período',sold=m.sales.flatMap(s=>s.items),methods=Object.entries(m.payments).sort((a,b)=>b[1]-a[1]),peak=managementPeak(m),sources=mgSources(m),people=mgCustomers(m),best=mgBestDay(m);
 return mgRow('produtos','box','Produtos vendidos',m.sales.length?quantityHeadline(sold)+(m.rank[0]?' · mais vendido '+titleName(m.rank[0].name):''):none)
 +mgRow('resultado','chart','Resultado',m.sales.length?E.money(m.result)+' · margem '+(m.margin==null?'—':pct(m.margin,100)):none)
 +mgRow('pagamentos','wallet','Pagamentos',methods.length?methods.slice(0,2).map(([k,v])=>k+' '+pct(v,m.revenue)).join(' · '):none)
 +mgRow('horarios','clock','Melhor dia e horário',m.sales.length?best+(peak.hours[0]?' · '+peak.hours[0]:''):none)
 +mgRow('onde','store','Onde vendeu',sources.length?sources.slice(0,2).map(([n,v])=>n+' '+pct(v,m.revenue)).join(' · '):none)
 +mgRow('clientes','users','Clientes',m.sales.length?[people.PF&&grammarCount(people.PF,'compra PF','compras PF'),people.PJ&&grammarCount(people.PJ,'compra CNPJ','compras CNPJ'),people.none&&grammarCount(people.none,'sem nome','sem nome')].filter(Boolean).join(' · ')+' · '+qrReadSummary(m.sales):none)
 +mgRow('estoque','box','Estoque e sobras','Saldo e valores atuais · sobras por feira')
 +mgRow('relatorios','download','Relatórios e planilhas','Planilhas do período e de cada feira');}
function managementStockDetail(sel){const api=window.TerritorioDaySummary;if(!api)return '<p class="muted">Não foi possível consultar o estoque agora.</p>';const value=api.currentStockValue(model.data.products),money=E.money,partial=(amount,missing,known)=>missing?(known?money(amount)+' · parcial':'Não informado'):money(amount),current=value.rows.filter(p=>p.qty===null||p.qty>0),events=api.stockEventsInSelection(model.data.events,sel);
 const totals='<section class="ds-card mg-stock-current"><h3>Estoque geral agora</h3><div class="ds-row"><span>Ao custo atual</span><span class="ds-num"><strong>'+partial(value.cost,value.costMissing,value.costKnown)+'</strong></span></div><div class="ds-row"><span>Potencial de venda</span><span class="ds-num"><strong>'+partial(value.retail,value.priceMissing,value.priceKnown)+'</strong></span></div>'+(value.costMissing?'<p class="ds-note">'+grammarCount(value.costMissing,'produto com saldo sem custo informado','produtos com saldo sem custo informado')+'. O valor parcial soma apenas os custos conhecidos.</p>':'')+(value.priceMissing?'<p class="ds-note">'+grammarCount(value.priceMissing,'produto com saldo sem preço informado','produtos com saldo sem preço informado')+'. O potencial parcial soma apenas os preços conhecidos.</p>':'')+'<p class="ds-note">Saldo consultado agora, aos preços e custos atuais. Não é o saldo histórico no fechamento do dia. O potencial de venda não é receita recebida.</p></section>';
 const balances='<details class="panel management-section mg-stock-balances"><summary><span><strong>Saldo atual por produto</strong><small>'+grammarCount(current.length,'produto com saldo','produtos com saldo')+'</small></span>'+icon('down')+'</summary><div class="management-section-body">'+(current.length?current.map(p=>'<div class="ds-row"><span><strong>'+escape(titleName(p.name))+'</strong><small>'+escape(p.description||E.description(p))+'</small></span><span class="ds-num"><strong>'+(p.qty===null?'Não informado':E.quantity(p.qty)+' '+escape(shortUnit(p.unit)))+'</strong><small>'+(p.costValue===null?'Custo não informado':money(p.costValue)+' ao custo')+'</small></span></div>').join(''):'<p class="ds-empty">Estoque geral sem saldo.</p>')+'</div></details>';
 const leftovers=events.map(e=>{const load=eventLoad(e.id),known=!!load?.items?.length,report=known?fairReportFor(e):null,rows=(report?.products||[]).filter(p=>p.left>0),name=escape(managementEventName(e)),date=escape(dateBR(e.start)+(e.end!==e.start?' a '+dateBR(e.end):''));return '<section class="ds-card mg-stock-leftovers" data-stock-event="'+escape(e.id)+'"><h3>'+name+'</h3><p class="ds-note">'+date+' · '+(e.status==='active'?'Sobra calculada até agora':'Sobra calculada da feira')+'</p>'+(known?(rows.length?rows.map(p=>'<div class="ds-row"><span><strong>'+escape(titleName(p.name))+'</strong>'+(p.description?'<small>'+escape(p.description)+'</small>':'')+'</span><span class="ds-num"><strong>'+E.quantity(p.left)+' '+escape(shortUnit(p.unit))+'</strong></span></div>').join(''):'<p class="ds-empty">Sem sobras nos produtos com carga registrada.</p>'):'<p class="ds-empty">Carga não registrada. Não há base para calcular a sobra.</p>')+'</section>';}).join('');
 return totals+balances+'<h3 class="mg-sheet-title">Sobras por feira</h3><p class="ds-note">'+(model.data.events.some(e=>e.id===sel.scope)?'Evento selecionado.':'Feiras que atravessam o período selecionado.')+' Carga total registrada − vendas concluídas − perdas registradas, preservando a unidade de cada apresentação. Reposições já estão incluídas na carga. Estes registros continuam se atualizando; não são uma fotografia do fechamento.</p>'+(leftovers||'<p class="ds-empty">Nenhuma feira neste recorte.</p>');}
function mgDetail(key,sel,m){const events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start)),people=mgCustomers(m),peak=managementPeak(m);
 if(key==='produtos')return ['Produtos vendidos',productMetrics(sel,m)+openSection(managementRank(m))];
 if(key==='resultado')return ['Resultado',openSection(managementResults(m))+'<h3 class="mg-sheet-title">Indicadores</h3><div class="kpi-grid">'+kpiData(sel).map((k,i)=>kpiRow(k,i+1)).join('')+'</div><div class="two">'+btn('log-approaches','Registrar abordagens','choice')+btn('expense','Registrar despesa','choice')+'</div>'+metricSources()];
 if(key==='pagamentos')return ['Pagamentos',openSection(managementPayments(m))];
 if(key==='horarios')return ['Melhor dia e horário','<p class="mg-sheet-lead">'+(m.sales.length?'Mais vendas: '+escape(mgBestDay(m))+(peak.hours.length?', '+escape(peak.hours.join(' e ')):'')+'.':'Sem vendas no período.')+'</p>'+openSection(managementRevenue(m))];
 if(key==='onde')return ['Onde vendeu',m.sales.length?mgBars(mgSources(m),m.revenue):'<p class="muted">Sem vendas no período.</p>'];
 if(key==='clientes')return ['Clientes','<div class="mg-sheet-stats"><div><strong>'+people.PF+'</strong><small>Pessoa física</small></div><div><strong>'+people.PJ+'</strong><small>CNPJ</small></div><div><strong>'+people.none+'</strong><small>Sem nome</small></div></div><h3 class="mg-sheet-title">Consumo e comparativos</h3><div class="two">'+btn('consumption','Pessoa física','choice',{type:'PF'})+btn('consumption','CNPJ','choice',{type:'PJ'})+'</div><h3 class="mg-sheet-title">QR codes lidos</h3><p class="small muted">'+escape(qrReadSummary(m.sales))+'. Contadas sozinhas quando o cliente abre seu portfólio pelo QR mostrado após a venda.</p>'];
 if(key==='estoque')return ['Estoque e sobras',managementStockDetail(sel)];
 if(key==='relatorios')return ['Relatórios e planilhas',openSection(managementReports(events,sel,m))];
 if(key==='marca')return ['Sua marca',managementAdvice('branding')];
 if(key==='banca')return ['Sua banca',managementAdvice('pdv')];
 return null;}

function feiraManagementPage(){const sel=selection(),m=filteredMetrics(sel);
 const tools=mgRow('marca','leaf','Sua marca','Origem e relacionamento')+mgRow('banca','image','Sua banca','Exposição e experiência');
 return top()+periodBar()+feiraHero(sel,m)+'<div class="mg-advisor">'+hideMoney(advisorPanel())+'</div><h2 class="mg-section-title">Explorar o período</h2><section class="mg-list mg-overview-list" aria-label="Detalhes do período">'+hideMoney(mgRows(sel,m))+'</section><h2 class="mg-section-title">Planejar sua banca</h2><section class="mg-planning" aria-label="Ferramentas">'+tools+'</section>';
}
