managementPage=function(){return feiraManagementPage();};
Object.assign(actions,{
 'mg-period-mode':d=>{if(!PERIOD_MODES.some(([id])=>id===d.mode))return;periodMode=d.mode;periodAnchor=E.dayKey(Date.now());month=periodAnchor.slice(0,7);render();},
 'mg-period-shift':d=>{const next=shiftPeriod(periodMode,periodAnchor,Number(d.delta)>0?1:-1);if(Number(d.delta)>0&&periodIsFuture(periodMode,periodAnchor))return;periodAnchor=next;month=periodAnchor.slice(0,7);render();},
 'mg-detail':d=>{const sel=selection(),m=filteredMetrics(sel),r=mgDetail(d.key,sel,m);if(r)openModal(r[0],hideMoney(r[1]),'mg-detail');}
});
// --- Resumo do dia: vendas, famílias e custos. Saldos de estoque ficam na Gestão. ---
// Abre pelo ícone de papel do Vender (o histórico venda por venda fica dentro, em "Ver cada venda").
const DAY_COST_PRESETS=['Barraca','Transporte','Ajudante','Alimentação','Embalagens'];
function daySummaryData(){const day=E.dayKey(Date.now()),inDay=r=>E.dayKey(r.date)===day;let sales=model.data.sales.filter(s=>(s.status==='completed'||s.status==='returned')&&inDay(s));const costs=model.data.expenses.filter(inDay),m=aggregateSales(sales,costs);let familyRows=sales.flatMap(netItems),returns=[];
 try{const f=finStatement({...periodSelection('dia',day),scope:'all'}),st=FIN().statement({sales:f.sales,returns:f.returns,expenses:f.expenses,receipts:f.receipts,settings:model.data.settings.finance,general:false});sales=f.sales;returns=f.returns;Object.assign(m,{revenue:st.revenue,result:st.result,fees:st.fees,taxes:st.taxes,returned:st.returned,discounts:st.discounts,received:st.received,st});familyRows=f.sales.flatMap(netItems).concat(f.returns.flatMap(s=>netItems(s).map(i=>({...i,amount:-i.amount,qty:-i.qty}))));}catch(e){console.error(e);}
 m.families=window.TerritorioDaySummary?.categorySales(familyRows,model.data.products)||[];m.rank=window.TerritorioDaySummary?.dailyItemTotals(familyRows)||m.rank;
 const sections=window.TerritorioDaySummary?.dailySaleSections({sales,returns,events:model.data.events,day})||[];
 return {day,sales,costs,m,sections};}
// Fechamento de caixa: quanto entrou em cada forma de pagamento e quanto conferir na gaveta.
function dayCashHtml(m,money){const r=m.received||{},fees=(model.data.settings.finance&&model.data.settings.finance.cardFees)||{},rate=k=>FIN().financeSettings(model.data.settings.finance).cardFees[k]||0;const rows=E.PAYMENTS.filter(k=>r[k]).map(k=>{const net=['Débito','Crédito'].includes(k)?Math.round(r[k]*(1-rate(k)/100)):null;return '<div class="ds-row"><span><strong>'+escape(k)+'</strong>'+(net!=null?'<small>Cai na conta: '+money(net)+' (taxa '+rate(k).toLocaleString('pt-BR')+'%)</small>':k==='Dinheiro'?'<small>Confira na gaveta</small>':'')+'</span><span class="ds-num"><strong>'+money(r[k])+'</strong></span></div>';}).join('');
 if(!rows&&!m.returned&&!m.discounts&&!m.st?.creditSold)return '';return '<section class="ds-card"><h3>Recebimentos</h3>'+rows+(m.st?.creditSold?'<p class="ds-note">Vendido no Fiado: '+money(m.st.creditSold)+'. Ainda não é dinheiro recebido.</p>':'')+(m.discounts?'<p class="ds-note">Descontos dados hoje: '+money(m.discounts)+'.</p>':'')+(m.returned?'<p class="ds-note">Devoluções hoje: '+money(m.returned)+' (já descontadas do total).</p>':'')+'</section>';}
function dayLeftovers(m){const e=model.data.events.find(x=>x.id===scope),load=e&&eventLoad(e.id);
 if(load&&load.items&&load.items.length){const sold=new Map();model.data.sales.filter(s=>s.status==='completed'&&s.scope===e.id).forEach(s=>netItems(s).forEach(i=>sold.set(i.productId,(sold.get(i.productId)||0)+i.qty)));return {fromLoad:true,rows:load.items.map(i=>({name:i.name,description:i.description,unit:i.unit,took:i.qty,left:Math.max(0,i.qty-(sold.get(i.productId)||0))}))};}
 return {fromLoad:false,rows:m.rank.map(r=>{const p=model.product(r.id);return p?{name:p.name,description:p.description||r.description,unit:p.unit,left:Math.max(0,p.stock)}:null;}).filter(Boolean)};}
function daySaleSectionsHtml(sections,money){return sections.map(group=>{const rows=group.sales.flatMap(netItems).concat(group.returns.flatMap(s=>netItems(s).map(i=>({...i,amount:-i.amount,qty:-i.qty})))),st=FIN().statement({sales:group.sales,returns:group.returns,expenses:[],receipts:[],settings:model.data.settings.finance,general:false}),categories=window.TerritorioDaySummary.categorySales(rows,model.data.products),rank=window.TerritorioDaySummary.dailyItemTotals(rows),outside=group.kind==='outside',title=outside?'Fora do horário do evento':group.name,subtitle=outside?group.name+' · antes de '+group.from+' e a partir de '+group.until:group.eventId?(group.from?group.from+' às '+group.until+' · Brasília':'Horário não informado'):'Outras vendas do dia';
 return '<section class="ds-event-section" data-summary-section="'+escape(group.key)+'"><header><h3>'+escape(title)+'</h3><p>'+escape(subtitle)+'</p></header><div class="ds-section-total"><span>Total vendido</span><strong>'+money(st.revenue)+'</strong><small>'+grammarCount(group.sales.length,'venda registrada','vendas registradas')+'</small></div><section class="ds-card ds-families"><h4>Vendas por categoria</h4>'+categories.map(f=>'<div class="ds-row ds-family-row"><span><strong>'+escape(titleName(f.name))+'</strong><small>'+f.units.filter(u=>u.qty!==0).map(u=>E.quantity(u.qty)+' '+escape(shortUnit(u.unit))).join(' · ')+'</small></span><span class="ds-num"><strong>'+money(f.amount)+'</strong></span></div>').join('')+'</section>'+dayCashHtml({...st,st},money)+'<section class="ds-card"><h4>O que vendeu</h4>'+(rank.length?rank.map(r=>'<div class="ds-row"><span><strong>'+escape(titleName(r.name))+'</strong>'+(r.description?'<small>'+escape(r.description)+'</small>':'')+'</span><span class="ds-num"><strong>'+E.quantity(r.qty)+' '+escape(shortUnit(r.unit))+'</strong><small>'+money(r.amount)+'</small></span></div>').join(''):'<p class="ds-empty">Sem saldo de produtos vendidos nesta seção.</p>')+'</section></section>';}).join('')+'<p class="ds-note">Horários de Brasília. A divisão usa a data e a hora registradas na venda; uma venda anotada depois pode aparecer fora do horário do evento.</p>';}
function daySummaryHtml(){const {day,sales,costs,m,sections}=daySummaryData(),visible=!!model.data.settings.financialVisible,money=v=>visible?E.money(v):'••••••',e=model.data.events.find(x=>x.id===scope),when=new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC',weekday:'long',day:'numeric',month:'long'});
 const head='<div class="ds-head"><strong>Vendas de hoje</strong><small>'+escape(when.charAt(0).toUpperCase()+when.slice(1))+'</small>'+btn('toggle-day-privacy',icon(visible?'eye':'eyeOff')+'<span class="sr-only">'+(visible?'Esconder':'Mostrar')+' valores do resumo</span>','ds-privacy')+'</div>';
 const hero='<section class="feira-hero ds-hero'+(m.result<0?' is-negative':'')+'" aria-label="Resumo do dia"><small>Total vendido</small><span class="feira-hero-value'+(visible?'':' is-hidden')+'">'+money(m.revenue)+'</span><div class="feira-hero-stats ds-stats"><div><small>Vendas</small><strong>'+sales.length+'</strong></div><div><small>Lucro do dia</small><strong>'+money(m.result)+'</strong></div></div><p class="ds-hero-note">Vendas − custo dos produtos − taxas − custos do dia. As contas fixas do mês entram em Gestão → Finanças.</p></section>';
 const soldRows=m.rank.length?m.rank.map(r=>'<div class="ds-row"><span><strong>'+escape(titleName(r.name))+'</strong>'+(r.description?'<small>'+escape(r.description)+'</small>':'')+'</span><span class="ds-num"><strong>'+E.quantity(r.qty)+' '+escape(shortUnit(r.unit))+'</strong><small>'+money(r.amount)+'</small></span></div>').join(''):'<p class="ds-empty">Nenhuma venda hoje aqui.</p>';
 const familyRows=m.families.length?m.families.map(f=>'<div class="ds-row ds-family-row"><span><strong>'+escape(titleName(f.name))+'</strong><small>'+f.units.filter(u=>u.qty!==0).map(u=>E.quantity(u.qty)+' '+escape(shortUnit(u.unit))).join(' · ')+'</small></span><span class="ds-num"><strong>'+money(f.amount)+'</strong></span></div>').join(''):'<p class="ds-empty">Nenhuma venda hoje aqui.</p>';
 const costRows=(costs.length?costs.map(x=>'<div class="ds-row"><span><strong>'+escape(x.title)+'</strong></span><span class="ds-num"><strong>− '+money(x.amount)+'</strong></span></div>').join(''):'<p class="ds-empty">Sem custos registrados hoje.</p>')+btn('day-cost',icon('plus')+' Adicionar custo do dia','ds-add');
 return head+hero+(sections.some(g=>g.eventId)?daySaleSectionsHtml(sections,money)+(m.st?.collected?'<section class="ds-card"><h3>Recebimentos de Fiado</h3><strong class="tabular">'+money(m.st.collected)+'</strong><p class="ds-note">Pagamentos confirmados hoje, inclusive de vendas anteriores. Não são novas vendas.</p></section>':''):'<section class="ds-card ds-families"><h3>Vendas por categoria</h3>'+familyRows+'</section>'+dayCashHtml(m,money)+'<section class="ds-card"><h3>O que vendeu</h3>'+soldRows+'</section>')+'<section class="ds-card workflow-day-cost"><h3>Houve algum custo a mais hoje?</h3>'+costs.map(x=>'<div class="ds-row"><span><strong>'+escape(x.title)+'</strong><small>'+escape(scopeName(x.scope||'loja'))+'</small></span><strong>'+money(x.amount)+'</strong></div>').join('')+'<p class="ds-note">Novo custo em: '+escape(scopeName(scope))+'</p><label class="sr-only" for="workflow-day-extra">Valor do custo extra em reais</label><div class="workflow-inline-cost"><input id="workflow-day-extra" inputmode="decimal" placeholder="R$ 0,00" autocomplete="off">'+btn('workflow-day-cost-save','Registrar','choice')+'</div><p class="ds-note">Entra no resultado do dia e na Gestão.</p></section>'
 +'';}
function openDaySummary(markClosed=true){if(markClosed)markDayClosed();openModal('Resumo do dia',daySummaryHtml(),'day-summary',null,btn('close-modal',icon('back')+'<span>Voltar</span>','sheet-back'));}
function daySummaryText(){const {sales,costs,m}=daySummaryData(),money=v=>model.data.settings.financialVisible?E.money(v):'••••••',lines=['*Resumo do dia*',new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}),'','Total vendido: '+money(m.revenue),'Vendas: '+sales.length,'Lucro do dia: '+money(m.result)];
 if(m.families.length){lines.push('','*Vendas por categoria*');m.families.forEach(f=>lines.push('• '+titleName(f.name)+': '+money(f.amount)));}
 if(m.received){const rec=E.PAYMENTS.filter(k=>m.received[k]);if(rec.length){lines.push('','*Recebimentos*');rec.forEach(k=>lines.push('• '+k+': '+money(m.received[k])));}}
 if(m.rank.length){lines.push('','*O que vendeu*');m.rank.forEach(r=>lines.push('• '+titleName(r.name)+(r.description?' ('+r.description+')':'')+': '+E.quantity(r.qty)+' '+shortUnit(r.unit)+' · '+money(r.amount)));}
 if(costs.length){lines.push('','*Custos do dia*');costs.forEach(x=>lines.push('• '+x.title+': '+money(x.amount)));}
 return lines.join('\n');}

// Fim da feira: um aviso no Vender convida a fechar o dia e registrar os custos (uma vez por dia e local).
function dayCloseKey(){return scope+'|'+E.dayKey(Date.now());}
function markDayClosed(){const st=model.data.settings;st.dayClosed=st.dayClosed||{};if(!st.dayClosed[dayCloseKey()]){st.dayClosed[dayCloseKey()]=Date.now();const keys=Object.keys(st.dayClosed);if(keys.length>60)keys.slice(0,keys.length-60).forEach(k=>delete st.dayClosed[k]);persist();}}
function dayClosePrompt(){const e=model.data.events.find(x=>x.id===scope);if(!e)return '';const today=E.dayKey(Date.now());if(today<e.start||today>e.end)return '';const end=Date.parse(today+'T'+(e.until||'23:59')+':00-03:00');if(Date.now()<end||(model.data.settings.dayClosed||{})[dayCloseKey()])return '';
 return '<section class="fair-card day-close" role="status">'+btn('day-summary','<span class="fc-date" aria-hidden="true">'+icon('receipt')+'</span><span class="fc-text"><small>A feira terminou</small><strong>Feche o dia</strong><span>Confira suas vendas e registre os custos do dia.</span></span>'+icon('chevron'),'fc-main')+btn('day-close-dismiss',icon('close')+'<span class="sr-only">Dispensar aviso</span>','fc-close')+'</section>';}
const feiraSellPageBeforeClose=feiraSellPage;
feiraSellPage=function(){const html=feiraSellPageBeforeClose(),prompt=dayClosePrompt();return prompt?html.replace('<section class="feira-sell-hero"',prompt+'<section class="feira-sell-hero"'):html;};

Object.assign(actions,{
 'sales-history':()=>openDaySummary(),
 'day-summary':()=>openDaySummary(),
 'toggle-day-privacy':()=>{const prior=model.data.settings.financialVisible;model.data.settings.financialVisible=!prior;if(!persist()){model.data.settings.financialVisible=prior;return toast('Não foi possível salvar a preferência.');}render();openDaySummary(false);},
 'day-close-dismiss':()=>{markDayClosed();render();},
 'day-summary-sales':()=>{const {sales}=daySummaryData();salesHistory(sales,'Vendas de hoje');},
 'day-summary-gestao':()=>{closeModal();periodMode='dia';periodAnchor=E.dayKey(Date.now());month=periodAnchor.slice(0,7);managementScope=scope;page='Gestão';render();window.scrollTo(0,0);},
 'day-summary-share':()=>{const a=document.createElement('a');a.href='https://wa.me/?text='+encodeURIComponent(daySummaryText());a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();},
 'day-cost':()=>openModal('Custo do dia','<p class="dialog-text">Entra no lucro de hoje e na Gestão.</p><div class="ds-presets">'+DAY_COST_PRESETS.map(t=>btn('day-cost-preset',t,'chip',{title:t})).join('')+'</div>'+field('day-cost-title','Descrição','','placeholder="Ex.: barraca"')+field('day-cost-value','Valor (R$)','','inputmode="decimal"')+btn('day-cost-save','Salvar custo','primary modal-action'),'day-cost'),
 'day-cost-preset':d=>{const input=document.getElementById('day-cost-title');if(input){input.value=d.title;document.getElementById('day-cost-value')?.focus();}},
 'day-cost-save':()=>{const title=(document.getElementById('day-cost-title')?.value||'').trim(),amount=E.cents(document.getElementById('day-cost-value')?.value||'');if(!title||!Number.isFinite(amount)||amount<=0)return toast('Informe descrição e valor.');model.data.expenses.unshift({id:E.uid(),title,amount,date:E.dayKey(Date.now())+'T12:00:00-03:00',scope,customerType:'',category:'Operação'});persist();toast('Custo registrado.');openDaySummary();}
});
// --- Venda registrada: a venda é gravada ao finalizar (nunca se perde ao fechar) e a página mostra o QR ---
// Destino automático: a feira em andamento; fora de feira, pessoa física (ou CNPJ, se o cliente for empresa).
// "Foi uma empresa?" ajusta depois, sem refazer a venda.
const storyModalBase=storyModal;
storyModal=function(id){
 if(!id&&recipientPending&&!recipientPending.busy){storyModalBase();const state=recipientOptions(),type=state.event?'EVENT':recordPersonType(recipientPending.draft)==='PJ'?'PJ':'PF',pending=recipientPending;void chooseSaleRecipient(type,state.event?state.eventRecord.id:undefined);return;}
 const sale=id&&model.data.sales.find(s=>s.id===id);if(sale)return saleDoneModal(id);return storyModalBase(id);};
function saleDoneModal(id){const sale=model.data.sales.find(s=>s.id===id);if(!sale)return;const pj=recordPersonType(sale)==='PJ',methods=[...new Set(sale.payments.map(p=>p.method))].join(' + ');
 const body='<div class="sd workflow-sale-done"><div class="sd-head"><span class="sd-check" aria-hidden="true">'+icon('check')+'</span><strong>Venda registrada</strong><small>'+E.money(sale.total)+' · '+escape(methods)+' · '+escape(scopeName(sale.scope))+'</small></div><section class="sd-list">'+btn('sale-company','<span>Foi uma empresa?</span><span class="sd-switch'+(pj?' on':'')+'" role="switch" aria-checked="'+pj+'"><span></span></span>','sd-row',{id:sale.id})+'</section><p class="ds-note">Estoque e registros atualizados.</p></div>';
 openModal('',body,'story',{id:sale.id,pending:false},btn('close-modal','Nova venda','success sd-new')+btn('store-share','Enviar Lista de Pedidos','link sd-pdf',{sale:sale.id})+btn('store-portfolio','Enviar Portfólio','link sd-pdf',{sale:sale.id}));}
const qrReadBase=actions['qr-read'];
Object.assign(actions,{
 'qr-read':d=>{qrReadBase(d);const sale=d.id!=='pending'&&model.data.sales.find(s=>s.id===d.id);if(sale&&sale.qrReadAt)saleDoneModal(sale.id);},
 'sale-company':d=>{const sale=model.data.sales.find(s=>s.id===d.id);if(!sale||sale.status!=='completed')return;const pj=recordPersonType(sale)!=='PJ';sale.customerType=pj?'PJ':'PF';if(sale.scope==='loja')sale.recipientType=sale.customerType;if(!persist())return toast('Não foi possível salvar.');saleDoneModal(sale.id);}
});
// --- Finanças e Custos (Gestão) — cálculo em src/features/finance/finance.js ---
const FIN=()=>window.TerritorioFinance;
function finSettings(){return FIN().financeSettings(model.data.settings.finance);}
function finSaveSettings(patch){model.data.settings.finance={...(model.data.settings.finance||{}),...patch};return persist();}
function finSharesFor(sel){const today=E.dayKey(Date.now());return FIN().monthShares(sel.periodMode==='ano'?{year:sel.year,today}:sel.periodMode==='mes'?{month:sel.month}:{days:sel.days});}
// Um só cálculo (regime de competência): vendas pela data da venda (inclusive as devolvidas depois),
// devoluções pela data da devolução, custos lançados, perdas de estoque (só em "Todos os locais").
function finStatement(sel){const inSel=r=>matchesSelection(r,sel),general=sel.scope==='all';
 const sales=model.data.sales.filter(s=>(s.status==='completed'||s.status==='returned')&&inSel(s)),returns=model.data.sales.filter(s=>s.status==='returned'&&inSel({...s,date:s.returnedAt||s.date})),expenses=model.data.expenses.filter(inSel);
 const losses=general?FIN().lossValue((model.data.movements||[]).filter(m=>m.kind==='loss'&&inSel({date:m.date,scope:'loja'})),id=>model.product(id)?.cost):0;
 return {sales,returns,expenses,receipts:window.TerritorioReceivables.collections(model.data.sales,inSel),st:FIN().statement({sales,returns,expenses,receipts:window.TerritorioReceivables.collections(model.data.sales,inSel),losses,settings:model.data.settings.finance,shares:finSharesFor(sel),general})};}
function finData(sel){sel=sel||selection();const f=finStatement(sel),completed=f.sales.filter(s=>s.status==='completed');
 return {sel,sales:completed,returns:f.returns,expenses:f.expenses,st:f.st,places:FIN().profitByPlace({sales:f.sales,returns:f.returns,expenses:f.expenses,receipts:f.receipts,settings:model.data.settings.finance,nameOf:scopeName}),margins:FIN().productMargins(f.sales,f.returns)};}
function finGoal(){const s=finSettings();if(s.goal)return {value:s.goal,auto:false};const now=E.dayKey(Date.now()),past=[1,2,3].map(i=>{const anchor=shiftPeriod('mes',now,-i);return finData({...periodSelection('mes',anchor),scope:'all'}).st.result;});return {value:FIN().suggestedGoal(past),auto:true};}

// Lacunas: produtos sem custo e dias de venda (já encerrados) sem nenhum custo extra lançado.
function finGaps(){const today=E.dayKey(Date.now()),noCost=model.data.products.filter(p=>p.price>0&&!(p.cost>0)),days=new Map();
 model.data.sales.filter(s=>s.status==='completed').forEach(s=>{const day=E.dayKey(s.date),place=s.scope||'loja';if(day<shiftDay(today,-30))return;const e=model.data.events.find(x=>x.id===place);if(!e)return;const ended=day<today||Date.now()>Date.parse(today+'T'+(e.until||'23:59')+':00-03:00');if(!ended)return;days.set(place+'|'+day,{place,day,name:e.name});});
 const missing=[...days.values()].filter(d=>!model.data.expenses.some(x=>(x.scope||'loja')===d.place&&E.dayKey(x.date)===d.day)).sort((a,b)=>b.day.localeCompare(a.day));
 return {noCost,missing,any:noCost.length>0&&missing.length>0};}
// Aviso com duas saídas: "Fazer agora" (leva para completar) ou "Depois" (some até amanhã).
function finWarnKey(action){return action==='fin-nocost'?'nocost':'missing';}
function finSnoozed(key){return (model.data.settings.finSnooze||{})[key]===E.dayKey(Date.now());}
function finWarn(text,action,label,data){const key=finWarnKey(action);if(finSnoozed(key))return '';return '<section class="fin-warn" role="status"><span class="fin-warn-dot" aria-hidden="true"></span><span class="fin-warn-text-body">'+text+'</span><span class="fin-warn-actions">'+btn('fin-snooze','Depois','fin-warn-later',{key})+btn(action,'Fazer agora','fin-warn-go',data)+'</span></section>';}
Object.assign(actions,{'fin-snooze':d=>{const st=model.data.settings;st.finSnooze={...(st.finSnooze||{}),[d.key]:E.dayKey(Date.now())};persist();if(modal&&modal.kind==='mg-detail'){const h=document.querySelector('dialog[open] .fin-warn [data-key="'+d.key+'"]');h&&h.closest('.fin-warn').remove();}render();}});

// Estoque: aviso no topo quando há produto sem custo.
const stockLossReminderFin=stockLossReminder;
stockLossReminder=function(){const g=finGaps(),n=g.noCost.length;return (n?finWarn(grammarCount(n,'produto','produtos')+' sem custo: o lucro aparece maior do que é.','fin-nocost','Completar'):'')+stockLossReminderFin();};
function noCostSheet(){const list=finGaps().noCost;return '<p class="dialog-text">O custo é quanto você gasta para produzir ou comprar uma unidade (insumos, embalagem). Com ele, o app mostra o lucro real.</p><div class="mg-scope-list">'+list.map(p=>btn('edit-product','<span><strong>'+escape(titleName(p.name))+'</strong><small>'+(p.description?escape(p.description)+' · ':'')+'preço '+E.money(p.price)+'</small></span>'+icon('chevron'),'mg-scope-option',{id:p.id})).join('')+'</div>';}

function finRow(label,value,cls){return '<div class="fin-row'+(cls?' '+cls:'')+'"><span>'+label+'</span><strong class="tabular">'+value+'</strong></div>';}
const finPct=r=>(r*100).toLocaleString('pt-BR',{maximumFractionDigits:0})+'%';
function financeSheet(){const d=finData(),st=d.st,s=finSettings(),month=d.sel.periodMode==='mes',goal=month&&d.sel.scope==='all'?finGoal():null,money=E.money,g=finGaps();
 const goalHtml=goal&&goal.value?'<div class="fin-goal"><div class="fin-goal-text"><small>'+(goal.auto?'Meta sugerida':'Meta do mês')+' '+money(goal.value)+'</small><small>'+(st.result>=goal.value?'Meta alcançada ✓':'Faltam '+money(goal.value-Math.max(0,st.result)))+'</small></div><div class="fin-bar"><span style="width:'+Math.max(0,Math.min(100,st.result/goal.value*100))+'%"></span></div></div>':'';
 const hero='<section class="feira-hero fin-hero'+(st.result<0?' is-negative':'')+'"><small>Resultado do período</small><span class="feira-hero-value'+(model.data.settings.financialVisible?'':' is-hidden')+'">'+money(st.result)+'</span>'+goalHtml+'<div class="feira-hero-stats ds-stats"><div><small>Margem</small><strong>'+(st.revenue?finPct(st.contributionRate):'—')+'</strong></div><div><small>Para empatar o mês</small><strong>'+(st.breakEven?money(st.breakEven):'—')+'</strong></div></div></section>';
 const general=d.sel.scope==='all',onlyAll='só em Todos os locais';
 const statementHtml='<section class="ds-card"><h3>Demonstrativo</h3>'+finRow('Vendas do período',money(st.grossSales))+(st.returned?finRow('− Devoluções',money(st.returned),'fin-sub'):'')+finRow('= Total vendido',money(st.revenue),'fin-total')+(st.discounts?'<p class="ds-note">Já com '+money(st.discounts)+' de descontos dados.</p>':'')
  +finRow('− Custo dos produtos',money(st.cmv),'fin-sub')+finRow('− Taxas de cartão',money(st.fees),'fin-sub')+(s.salesTaxRate?finRow('− Impostos sobre vendas ('+s.salesTaxRate.toLocaleString('pt-BR')+'%)',money(st.taxes),'fin-sub'):'')+finRow('= Margem de contribuição',money(st.contribution),'fin-total')
  +finRow('− Custos da feira',money(st.costs.feira),'fin-sub')+finRow('− Produção e insumos',money(st.costs.producao),'fin-sub')+finRow('− Divulgação',money(st.costs.marketing),'fin-sub')+finRow('− Perdas de estoque',general?money(st.losses):onlyAll,'fin-sub')+finRow('− Custos fixos',general?money(st.fixed):onlyAll,'fin-sub')+finRow('− Sua retirada',money(st.draw),'fin-sub')+finRow('= Resultado',money(st.result),'fin-total'+(st.result<0?' is-negative':''))
  +(!st.costsLogged&&st.salesCount?'<p class="ds-note">Sem custos extras lançados neste período: o resultado considera só o custo dos produtos.</p>':'')+'</section>';
 const methods=E.PAYMENTS.filter(k=>st.received[k]);
 const cashHtml='<section class="ds-card"><h3>Caixa do período</h3>'+methods.map(k=>finRow('Recebido em '+escape(k),money(st.received[k]),'fin-sub')).join('')+(st.cashRefunded?finRow('− Devoluções pagas',money(st.cashRefunded),'fin-sub'):'')+(st.creditSold?finRow('Vendido no Fiado (a receber)',money(st.creditSold),'fin-sub'):'')+finRow('− Taxas e impostos',money(st.fees+st.taxes),'fin-sub')+finRow('− Custos, fixos e retirada',money(st.operating+st.fixed+st.draw),'fin-sub')+(st.investments?finRow('− Investimentos',money(st.investments),'fin-sub'):'')+finRow('= Sobra no caixa',money(st.cash),'fin-total'+(st.cash<0?' is-negative':''))+'<p class="ds-note">O caixa é o dinheiro que entrou e saiu. O resultado mede o lucro: investimentos saem do caixa, mas não do resultado; perdas de estoque entram no resultado, mas não saem do caixa.</p></section>';
 const places=d.places.length>1||d.places.some(p=>p.costs)?'<section class="ds-card"><h3>Lucro por local</h3>'+d.places.map(p=>'<div class="ds-row"><span><strong>'+escape(p.name)+'</strong><small>Vendeu '+money(p.revenue+(p.returned||0))+(p.returned?' · devoluções '+money(p.returned):'')+(p.taxes?' · imposto '+money(p.taxes):'')+(p.costs?' · custos '+money(p.costs):'')+'</small></span><span class="ds-num"><strong class="'+(p.profit<0?'fin-neg':'fin-pos')+'">'+money(p.profit)+'</strong></span></div>').join('')+'</section>':'';
 const margins=d.margins.filter(m=>m.margin!=null).slice(0,8);
 const marginsHtml=margins.length?'<section class="ds-card"><h3>Margem por produto</h3>'+margins.map(m=>'<div class="ds-row"><span><strong>'+escape(titleName(m.name))+'</strong><small>'+escape(m.description||'')+' · vendeu '+money(m.revenue)+'</small></span><span class="ds-num"><strong class="'+(m.margin<0.25?'fin-warn-text':'')+'">'+finPct(m.margin)+'</strong></span></div>').join('')+'<p class="ds-note">Margem = (venda − custo do produto) ÷ venda. Abaixo de 25% aparece em laranja.</p></section>':'';
 const tools='<section class="mg-list fin-tools">'+mgRow('custos','receipt','Custos','Lançar e ver custos do período')+btn('fin-settings','<span class="mg-ico">'+icon('settings')+'</span><span class="mg-text"><strong>Taxas, meta e retirada</strong><small>Débito '+s.cardFees['Débito'].toLocaleString('pt-BR')+'% · Crédito '+s.cardFees['Crédito'].toLocaleString('pt-BR')+'%'+(s.drawOn?' · retirada '+money(s.drawMonthly)+'/mês':'')+'</small></span>'+icon('chevron'),'mg-row')+'</section>';
 return '<p class="fin-period">'+escape(periodText(d.sel))+' · '+escape(mgScopeLabel())+'</p>'+auditBadge()+(g.missing.length?finWarn(grammarCount(g.missing.length,'dia de feira','dias de feira')+' sem custos lançados.','mg-detail','Lançar',{key:'custos'}):'')+hero+statementHtml+cashHtml+places+marginsHtml+tools;}

// --- Conferência dos números: o auditor dentro do app (src/features/finance/audit.js) ---
function auditRun(){const g=finGaps(),sel=selection(),st=finStatement(sel).st,b=window.TerritorioShell.backupState?.()||{};return FIN().runAudit({sales:model.data.sales,products:model.data.products,movements:model.data.movements||[],expenses:model.data.expenses,missingDays:g.missing,statementOk:st.checks,today:E.dayKey(Date.now()),backupAt:(typeof latestBackupAt==='function'&&latestBackupAt())||b.verifiedAt||b.savedAt||null});}
function auditBadge(){const a=auditRun(),all=a.ok===a.total;return btn('mg-detail','<span class="audit-seal'+(all?' ok':a.errors?' err':' warn')+'" aria-hidden="true">'+(all?'✓':'!')+'</span><span class="mg-text"><strong>Conferência dos números</strong><small>'+(all?'Tudo confere: '+a.total+' de '+a.total+' verificações':a.ok+' de '+a.total+' verificações em dia'+(a.errors?' · '+grammarCount(a.errors,'erro','erros'):''))+'</small></span>'+icon('chevron'),'audit-badge',{key:'conferencia'});}
function auditSheet(){const a=auditRun(),fails=a.checks.filter(c=>!c.ok),oks=a.checks.filter(c=>c.ok);
 return '<p class="dialog-text">As verificações locais procuram divergências entre vendas, pagamentos, estoque e custos. Elas ajudam a revisar os registros; não substituem conferência física, extratos ou análise contábil.</p>'
 +'<div class="audit-score"><strong>'+a.ok+'<small>/'+a.total+'</small></strong><span>'+(a.ok===a.total?'Nenhuma divergência detectada nestas verificações.':fails.length===1?'Falta 1 ponto para tudo conferir.':'Faltam '+fails.length+' pontos para tudo conferir.')+'</span></div>'
 +(fails.length?'<section class="ds-card"><h3>Precisa de atenção</h3>'+fails.map(c=>'<div class="audit-row '+c.level+'"><span class="audit-dot" aria-hidden="true"></span><span class="audit-text"><strong>'+escape(c.title)+'</strong><small>'+escape(c.problem)+' '+escape(c.help)+'</small></span>'+(c.action?btn(c.action,'Corrigir','fin-warn-go audit-go',c.data||{}):'')+'</div>').join('')+'</section>':'')
 +'<section class="ds-card"><h3>Conferido ✓</h3>'+oks.map(c=>'<div class="audit-row ok"><span class="audit-check" aria-hidden="true">✓</span><span class="audit-text"><strong>'+escape(c.title)+'</strong></span></div>').join('')+'</section>'
 +'<p class="ds-note">Cada fato usa a data registrada. Correções, devoluções e lançamentos posteriores podem atualizar a leitura dos períodos. A ausência de alerta não comprova que todos os dados foram informados.</p>';}
const mgDetailBeforeAudit=mgDetail;
mgDetail=function(key,sel,m){if(key==='conferencia')return ['Conferência dos números',auditSheet()];return mgDetailBeforeAudit(key,sel,m);};
const advisorInputBeforeAudit=advisorInput;
advisorInput=function(){const input=advisorInputBeforeAudit();try{const a=auditRun();input.audit={ok:a.ok,total:a.total,errors:a.checks.filter(c=>!c.ok&&c.level==='erro').map(c=>({id:c.id,title:c.title,problem:c.problem,help:c.help}))};}catch(e){console.error(e);}return input;};

function costsSheet(){const d=finData(),s=finSettings(),g=finGaps(),money=E.money,kinds=FIN().COST_KINDS;
 const warn=(g.missing.length?finWarn('Sem custos lançados: '+g.missing.slice(0,3).map(m=>escape(m.name)+' ('+dateBR(m.day)+')').join(', ')+(g.missing.length>3?' e mais '+(g.missing.length-3):'')+'.','fin-cost-new','Lançar',{day:g.missing[0].day,place:g.missing[0].place}):'')+(g.noCost.length?finWarn(grammarCount(g.noCost.length,'produto','produtos')+' sem custo no Estoque.','fin-nocost','Completar'):'');
 const list=kinds.map(([id,name])=>{const items=d.expenses.filter(x=>FIN().costKind(x)===id);if(!items.length)return '';return '<section class="ds-card"><h3>'+name+' · '+money(items.reduce((n,x)=>n+x.amount,0))+'</h3>'+items.map(x=>'<div class="ds-row"><span><strong>'+escape(x.title)+'</strong><small>'+dateBR(E.dayKey(x.date))+' · '+escape(scopeName(x.scope||'loja'))+'</small></span><span class="ds-num fin-cost-amount"><strong>'+money(x.amount)+'</strong>'+btn('fin-cost-delete',icon('trash')+'<span class="sr-only">Excluir custo</span>','fin-del',{id:x.id})+'</span></div>').join('')+'</section>';}).join('');
 const fixed='<section class="ds-card"><h3>Custos fixos do mês · '+money(s.fixedCosts.reduce((n,f)=>n+f.amount,0))+'</h3>'+(s.fixedCosts.length?s.fixedCosts.map(f=>'<div class="ds-row"><span><strong>'+escape(f.title)+'</strong><small>Todo mês</small></span><span class="ds-num fin-cost-amount"><strong>'+money(f.amount)+'</strong>'+btn('fin-fixed-delete',icon('trash')+'<span class="sr-only">Excluir custo fixo</span>','fin-del',{id:f.id})+'</span></div>').join(''):'<p class="ds-empty">Cadastre uma vez: energia, internet, combustível. Eles se repetem sozinhos todo mês.</p>')+btn('fin-fixed-new',icon('plus')+' Adicionar custo fixo','ds-add')+'</section>';
 return '<p class="fin-period">'+escape(periodText(d.sel))+' · '+escape(mgScopeLabel())+'</p>'+warn+'<p class="dialog-text">Custos extras não são o custo do produto (esse vem do Estoque e entra sempre). Lance quando quiser, inclusive dias depois: o cálculo do dia se refaz sozinho.</p>'+btn('fin-cost-new',icon('plus')+' Lançar custo','success modal-action ds-share')+(list||'<p class="ds-empty fin-empty">Nenhum custo extra neste período.</p>')+fixed;}

let finCostDraft={kind:'feira'};
function costForm(){const k=finCostDraft.kind,events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start)),place=finCostDraft.place||scope||'loja',day=finCostDraft.day||E.dayKey(Date.now());
 return '<div class="fin-kinds" role="group" aria-label="Tipo de custo">'+FIN().COST_KINDS.map(([id,name])=>btn('fin-cost-kind',name,'chip'+(k===id?' selected':''),{kind:id})).join('')+'</div><p class="ds-note">'+escape((FIN().COST_KINDS.find(([id])=>id===k)||[])[2]||'')+'</p>'
 +(k==='producao'?'<p class="fin-hint">Lance aqui só o que NÃO está no custo do produto (no Estoque). Se o custo do queijo já inclui o leite e a embalagem, não lance de novo: contaria duas vezes.</p>':'')+'<div class="ds-presets">'+(FIN().COST_PRESETS[k]||[]).map(t=>btn('fin-cost-preset',t,'chip',{title:t})).join('')+'</div>'
 +field('fin-cost-title','Descrição',finCostDraft.title||'','placeholder="Ex.: barraca"')+field('fin-cost-value','Valor (R$)',finCostDraft.value||'','inputmode="decimal"')
 +field('fin-cost-date','Dia',day,'type="date" max="'+E.dayKey(Date.now())+'"')
 +'<label for="fin-cost-place">Local</label><select id="fin-cost-place"><option value="loja"'+(place==='loja'?' selected':'')+'>Loja</option>'+events.map(e=>'<option value="'+escape(e.id)+'"'+(place===e.id?' selected':'')+'>'+escape(e.name)+'</option>').join('')+'</select>'
 +btn('fin-cost-save','Salvar custo','primary modal-action');}
function captureCostDraft(){const v=id=>document.getElementById(id)?.value;if(document.getElementById('fin-cost-title'))Object.assign(finCostDraft,{title:v('fin-cost-title'),value:v('fin-cost-value'),day:v('fin-cost-date'),place:v('fin-cost-place')});}
function reopenFin(key){const r=mgDetail(key,selection(),filteredMetrics(selection()));if(r)openModal(r[0],hideMoney(r[1]),'mg-detail');}
const mgDetailBeforeFin=mgDetail;
mgDetail=function(key,sel,m){if(key==='financas')return ['Finanças',financeSheet()];if(key==='custos')return ['Custos',costsSheet()];if(key==='resultado')return ['Finanças',financeSheet()];return mgDetailBeforeFin(key,sel,m);};
const mgRowsBeforeFin=mgRows;
mgRows=function(sel,m){const d=finData(sel),g=finGaps(),rows=mgRowsBeforeFin(sel,m).split('</button>').filter(Boolean).map(x=>x+'</button>');
 const fin=mgRow('financas','chart','Finanças',m.sales.length?'Resultado '+E.money(d.st.result)+' · margem '+finPct(d.st.contributionRate):'Resultado, caixa e margens'),costs=mgRow('custos','receipt','Custos'+(g.missing.length||g.noCost.length?' <span class="fin-badge" aria-label="Pendências">!</span>':''),d.expenses.length?E.money(d.expenses.reduce((n,x)=>n+x.amount,0))+' no período':'Feira, produção e custos fixos');
 return fin+costs+rows.filter(row=>!row.includes('data-key="resultado"')).join('');};
Object.assign(actions,{
 'fin-nocost':()=>openModal('Produtos sem custo',noCostSheet(),'mg-detail'),
 'fin-settings':()=>{const s=finSettings(),g=finGoal();openModal('Taxas, meta e retirada',field('fin-fee-debit','Taxa do débito (%)',String(s.cardFees['Débito']).replace('.',','),'inputmode="decimal"')+field('fin-fee-credit','Taxa do crédito (%)',String(s.cardFees['Crédito']).replace('.',','),'inputmode="decimal"')+field('fin-tax','Imposto sobre vendas (%)',s.salesTaxRate?String(s.salesTaxRate).replace('.',','):'','inputmode="decimal" placeholder="Ex.: 1,5 (Funrural)"')+'<p class="ds-note">Use se você paga imposto em cada venda (ex.: Funrural do produtor pessoa física). Guias mensais, como o DAS do MEI, vão em Custos fixos.</p>'+field('fin-goal','Meta de resultado do mês (R$)',s.goal?cashInput(s.goal):'','inputmode="decimal" placeholder="'+(g.value?'Sugestão: '+cashInput(g.value):'Ex.: 2000')+'"')+'<label class="fin-check"><input type="checkbox" id="fin-draw-on"'+(s.drawOn?' checked':'')+'> Separar minha retirada (pró-labore)</label>'+field('fin-draw','Retirada por mês (R$)',s.drawMonthly?cashInput(s.drawMonthly):'','inputmode="decimal" placeholder="Ex.: 1500"')+'<p class="ds-note">A retirada é o seu salário: separar o dinheiro da casa do dinheiro do negócio mostra se a produção paga o seu trabalho.</p>'+btn('fin-settings-save','Salvar','primary modal-action'),'mg-detail');},
 'fin-settings-save':()=>{const num=id=>Number(String(document.getElementById(id)?.value||'').replace(/\./g,'').replace(',','.')),debit=num('fin-fee-debit'),credit=num('fin-fee-credit'),goal=document.getElementById('fin-goal').value.trim(),draw=document.getElementById('fin-draw').value.trim();const tax=num('fin-tax')||0;if(!(debit>=0&&debit<=20)||!(credit>=0&&credit<=20)||!(tax>=0&&tax<=30))return toast('Use taxas entre 0 e 20% e imposto até 30%.');finSaveSettings({cardFees:{'Débito':debit,'Crédito':credit},salesTaxRate:tax,goal:goal?E.cents(goal):0,drawOn:document.getElementById('fin-draw-on').checked,drawMonthly:draw?E.cents(draw):0});toast('Finanças atualizadas.');reopenFin('financas');},
 'fin-cost-new':d=>{finCostDraft={kind:'feira',day:d&&d.day||'',place:d&&d.place||''};openModal('Lançar custo',costForm(),'mg-detail');},
 'fin-cost-kind':d=>{captureCostDraft();finCostDraft.kind=d.kind;openModal('Lançar custo',costForm(),'mg-detail');},
 'fin-cost-preset':d=>{const t=document.getElementById('fin-cost-title');if(t){t.value=d.title;document.getElementById('fin-cost-value')?.focus();}},
 'fin-cost-save':()=>{captureCostDraft();const c=finCostDraft,amount=E.cents(c.value||''),today=E.dayKey(Date.now());if(!String(c.title||'').trim()||!Number.isFinite(amount)||amount<=0)return toast('Informe descrição e valor.');if(!/^\d{4}-\d{2}-\d{2}$/.test(c.day||'')||c.day>today)return toast('Escolha um dia até hoje.');model.data.expenses.unshift({id:E.uid(),title:c.title.trim(),amount,date:c.day+'T12:00:00-03:00',scope:c.place||'loja',customerType:'',category:c.kind==='marketing'?'Marketing':'Operação',kind:c.kind});if(!persist())return toast('Não foi possível salvar.');toast('Custo registrado.');render();reopenFin('custos');},
 'fin-cost-delete':d=>{const i=model.data.expenses.findIndex(x=>x.id===d.id);if(i<0)return;const [removed]=model.data.expenses.splice(i,1);if(!persist()){model.data.expenses.splice(i,0,removed);return toast('Não foi possível excluir.');}toast('Custo excluído.');render();reopenFin('custos');},
 'fin-fixed-new':()=>openModal('Custo fixo do mês','<p class="dialog-text">Cadastre uma vez. Ele se repete todo mês e é rateado quando você olha um dia ou uma semana.</p><div class="ds-presets">'+FIN().FIXED_PRESETS.map(t=>btn('fin-fixed-preset',t,'chip',{title:t})).join('')+'</div>'+field('fin-fixed-title','Descrição','','placeholder="Ex.: energia"')+field('fin-fixed-value','Valor por mês (R$)','','inputmode="decimal"')+btn('fin-fixed-save','Salvar custo fixo','primary modal-action'),'mg-detail'),
 'fin-fixed-preset':d=>{const t=document.getElementById('fin-fixed-title');if(t){t.value=d.title;document.getElementById('fin-fixed-value')?.focus();}},
 'fin-fixed-save':()=>{const title=document.getElementById('fin-fixed-title').value.trim(),amount=E.cents(document.getElementById('fin-fixed-value').value);if(!title||!Number.isFinite(amount)||amount<=0)return toast('Informe descrição e valor.');const s=finSettings();if(!finSaveSettings({fixedCosts:[...s.fixedCosts,{id:E.uid(),title,amount,since:E.monthKey(Date.now())}]}))return toast('Não foi possível salvar.');toast('Custo fixo salvo.');render();reopenFin('custos');},
 'fin-fixed-delete':d=>{const s=finSettings();finSaveSettings({fixedCosts:s.fixedCosts.filter(f=>f.id!==d.id)});toast('Custo fixo excluído.');render();reopenFin('custos');}
});
// Custos do Resumo do dia entram como "custo da feira".
const dayCostSaveBase=actions['day-cost-save'];
actions['day-cost-save']=()=>{const before=model.data.expenses.length;dayCostSaveBase();if(model.data.expenses.length>before&&!model.data.expenses[0].kind){model.data.expenses[0].kind='feira';persist();}};

// Agente: a Orientação recebe as finanças do período.
const advisorInputBeforeFin=advisorInput;
advisorInput=function(){const input=advisorInputBeforeFin();try{const d=finData(),g=finGaps(),s=finSettings(),goal=d.sel.periodMode==='mes'&&d.sel.scope==='all'?finGoal():null;input.finance={mode:d.sel.periodMode,general:d.sel.scope==='all',...d.st,places:d.places.filter(p=>p.id!=='loja'),margins:d.margins,missingDays:g.missing,noCost:g.noCost.length,fixedCount:s.fixedCosts.length,drawOn:s.drawOn,goal:goal&&goal.value?goal:null};}catch(e){console.error(e);}return input;};
const advisorInputBeforeContext=advisorInput;
advisorInput=function(){return financialInsightsInput(selection());};
window.TerritorioShell.financeGaps=()=>{const g=finGaps();return {noCost:g.noCost.length,missing:g.missing.length,any:g.any};};
window.TerritorioShell.financeSnoozed=()=>finSnoozed('nocost')&&finSnoozed('missing');
window.TerritorioShell.financeSnooze=()=>{const st=model.data.settings,today=E.dayKey(Date.now());st.finSnooze={...(st.finSnooze||{}),nocost:today,missing:today};persist();render();};
window.TerritorioShell.openCosts=()=>{closeModal();page='Gestão';render();reopenFin('custos');};
// Um só cálculo de resultado no app inteiro: o das Finanças (custo dos produtos, taxas, custos
// lançados, fixos rateados e retirada). Card da Gestão, Orientação, Inteligência e planilhas usam o mesmo número.
const filteredMetricsBase=filteredMetrics;
filteredMetrics=function(sel){sel=sel||selection();const m=filteredMetricsBase(sel);if(!sel.periodMode||!window.TerritorioFinance)return m;try{const st=finStatement(sel).st;Object.assign(m,{revenue:st.revenue,cost:st.cmv,gross:st.revenue-st.cmv,fees:st.fees,taxes:st.taxes,losses:st.losses,fixed:st.fixed,draw:st.draw,expense:st.operating+st.losses+st.fixed+st.draw+st.taxes+st.fees,result:st.result,ticket:m.sales.length?st.revenue/m.sales.length:0,margin:st.revenue?(st.revenue-st.cmv)/st.revenue*100:null});}catch(e){console.error(e);}return m;};
const reportScopeNameBase=reportScopeName;
reportScopeName=function(id){return id==='all'?'Todos os locais':reportScopeNameBase(id);};
// --- Custos de evento integrados: criar na aba Eventos (com a inscrição), lançar no fim do dia pelo
// Resumo (5 perguntas), conferir e corrigir na página do evento. Tudo grava no mesmo lugar (expenses).
// Custo do evento inteiro (inscrição/barraca) é rateado pelos dias do evento: o evento leva o valor
// cheio; cada dia, a sua parte.
function eventDays(e){const out=[];for(let d=e.start;d<=e.end&&out.length<10;d=shiftDay(d,1))out.push(d);return out;}
function expandedExpenses(){return model.data.expenses.flatMap(x=>{if(!x.eventWide)return [x];const e=model.data.events.find(v=>v.id===x.scope);if(!e)return [x];const days=eventDays(e);if(days.length<2)return [{...x,date:days[0]+'T12:00:00-03:00'}];const part=Math.floor(x.amount/days.length);return days.map((d,i)=>({...x,id:x.id+'#'+i,amount:i===0?x.amount-part*(days.length-1):part,date:d+'T12:00:00-03:00',title:x.title+' ('+(i+1)+'/'+days.length+')',share:true}));});}
// O cálculo único passa a usar os custos já rateados.
const finStatementBeforeEvents=finStatement;
finStatement=function(sel){const original=model.data.expenses;model.data.expenses=expandedExpenses();try{return finStatementBeforeEvents(sel);}finally{model.data.expenses=original;}};
const finGapsBeforeEvents=finGaps;
finGaps=function(){const original=model.data.expenses;model.data.expenses=expandedExpenses();try{return finGapsBeforeEvents();}finally{model.data.expenses=original;}};
// Excluir uma parte rateada exclui o custo do evento inteiro.
const finCostDeleteBase=actions['fin-cost-delete'];
actions['fin-cost-delete']=d=>finCostDeleteBase({...d,id:String(d.id).split('#')[0]});

// Aba Eventos: local opcional e "Quanto pagou para participar?".
const eventModalBase=eventModal;
eventModal=function(){eventModalBase();const place=document.getElementById('event-place');if(place){const label=place.closest('.form-field')?.querySelector('label')||document.querySelector('label[for="event-place"]');if(label)label.textContent='Local (opcional)';place.placeholder='Ex.: Praça da Matriz';}
 const qr=document.querySelector('dialog[open] .event-qr');if(qr)qr.insertAdjacentHTML('beforebegin',field('event-fee','Quanto pagou para participar? (opcional)','','inputmode="decimal" placeholder="Inscrição ou aluguel da barraca"')+'<p class="ds-note">Entra como custo do evento. Nos eventos de vários dias, cada dia leva a sua parte.</p>');};
const saveEventBase=actions['save-event'];
actions['save-event']=()=>{const place=document.getElementById('event-place'),city=document.getElementById('event-city');if(place&&!place.value.trim())place.value=(city&&city.value.trim())||'Local não informado';const fee=E.cents(document.getElementById('event-fee')?.value||''),known=new Set(model.data.events.map(e=>e.id));saveEventBase();const e=model.data.events.find(v=>!known.has(v.id));if(e&&Number.isFinite(fee)&&fee>0){model.data.expenses.unshift({id:E.uid(),title:'Inscrição ou barraca',amount:fee,date:e.start+'T12:00:00-03:00',scope:e.id,customerType:'',category:'Operação',kind:'feira',eventWide:true,dayq:'inscricao'});persist();render();}};

// Página do evento: lucro do evento e os custos dele, com lançar e corrigir.
function eventFinanceHtml(e){const sel={scope:e.id,month:'',year:'',days:eventDays(e),from:'',until:'',periodMode:'evento',periodAnchor:e.start},st=finStatement(sel).st,costs=model.data.expenses.filter(x=>x.scope===e.id),money=E.money;
 return '<section class="feira-hero ds-hero ev-hero'+(st.result<0?' is-negative':'')+'"><div class="event-finance-heading"><small>Resultado do Evento</small>'+btn('event-financial',icon(model.data.settings.financialVisible?'eye':'eyeOff'),'insight-privacy-toggle',{id:e.id,label:model.data.settings.financialVisible?'Ocultar Valores':'Mostrar Valores'})+'</div><span class="feira-hero-value">'+money(st.result)+'</span><div class="feira-hero-stats ds-stats"><div><small>Vendas</small><strong>'+st.salesCount+'</strong></div><div><small>Vendeu</small><strong>'+money(st.revenue)+'</strong></div></div><p class="ds-hero-note">Vendas − custo dos produtos − taxas − custos do evento.</p></section>'
 +'<section class="ds-card"><h3>Custos do evento · '+money(costs.reduce((n,x)=>n+x.amount,0))+'</h3>'+(costs.length?costs.map(x=>'<div class="ds-row"><span><strong>'+escape(x.title)+'</strong><small>'+(x.eventWide?'Evento inteiro':dateBR(E.dayKey(x.date)))+'</small></span><span class="ds-num fin-cost-amount"><strong>'+money(x.amount)+'</strong>'+btn('ev-cost-delete',icon('trash')+'<span class="sr-only">Excluir custo</span>','fin-del',{id:x.id,event:e.id})+'</span></div>').join(''):'<p class="ds-empty">Nenhum custo lançado ainda.</p>')+btn('fin-cost-new',icon('plus')+'<span>Lançar ou Corrigir Custo</span>','choice event-cost-add',{place:e.id,day:E.dayKey(Date.now())>e.end?e.end:E.dayKey(Date.now())<e.start?e.start:E.dayKey(Date.now())})+'</section>';}
const eventDetailBase=eventDetail;
eventDetail=function(id){eventDetailBase(id);const e=model.data.events.find(v=>v.id===id),body=document.querySelector('dialog[open] .dialog-content')||document.querySelector('dialog[open]');if(!e||!body)return;const first=body.querySelector('p:nth-of-type(2)');const html=hideMoney(eventFinanceHtml(e));if(first)first.outerHTML=html;else body.insertAdjacentHTML('beforeend',html);};
actions['event-financial']=d=>{const top=dialog.querySelector('.dialog-content')?.scrollTop||0;model.data.settings.financialVisible=!model.data.settings.financialVisible;persist();eventDetail(d.id);const eye=dialog.querySelector('[data-action=event-financial]');eye?.setAttribute('aria-label',model.data.settings.financialVisible?'Ocultar Valores':'Mostrar Valores');eye?.setAttribute('aria-pressed',String(model.data.settings.financialVisible));const body=dialog.querySelector('.dialog-content');if(body)body.scrollTop=top;};
actions['ev-cost-delete']=d=>{const i=model.data.expenses.findIndex(x=>x.id===d.id);if(i<0)return;const [removed]=model.data.expenses.splice(i,1);if(!persist()){model.data.expenses.splice(i,0,removed);return toast('Não foi possível excluir.');}toast('Custo excluído.');render();eventDetail(d.event);};

// Resumo do dia: "Quanto custou estar aqui hoje?" — 5 perguntas opcionais, total automático.
const DAY_QUESTIONS=[['inscricao','Inscrição ou barraca'],['transporte','Transporte ou combustível'],['ajudante','Ajudante'],['alimentacao','Alimentação'],['outros','Outros (gelo, sacolas…)']];
let dayCostDraft=null;
function dayQuestionData(){const day=E.dayKey(Date.now()),mine=model.data.expenses.filter(x=>(x.scope||'loja')===scope&&E.dayKey(x.date)===day&&x.dayq&&!x.eventWide),wide=expandedExpenses().filter(x=>x.share!==undefined||x.eventWide).filter(x=>(x.scope||'loja')===scope&&E.dayKey(x.date)===day);return {day,mine,wide};}
function dayQuestionsForm(totalOnly){const {mine,wide}=dayQuestionData(),val=k=>{if(dayCostDraft&&Object.prototype.hasOwnProperty.call(dayCostDraft,k))return dayCostDraft[k];const x=mine.find(m=>m.dayq===k);return x?cashInput(x.amount):'';},wideAmount=wide.reduce((n,x)=>n+x.amount,0),where=scopeName(scope);
 const rows=DAY_QUESTIONS.map(([k,label])=>k==='inscricao'&&wideAmount?'<div class="dq-row dq-fixed"><span>'+label+'<small>informada no evento</small></span><strong data-dq-fixed="'+wideAmount+'">'+E.money(wideAmount)+'</strong></div>':'<label class="dq-row" for="dq-'+k+'"><span>'+label+'</span><input id="dq-'+k+'" class="dq-input" data-dq="'+k+'" inputmode="decimal" placeholder="0,00" value="'+escape(val(k))+'"></label>').join('');
 return '<div class="dq-form'+(totalOnly?' total-only':'')+'"><p class="dialog-text">'+escape(where)+' · hoje. Deixe em branco o que não teve. O custo dos produtos não entra aqui: ele já vem do Estoque.</p>'
 +(totalOnly?field('dq-total','Total dos custos de hoje (R$)',val('total'),'inputmode="decimal" placeholder="0,00"')+btn('day-cost-mode','Prefiro detalhar','link',{mode:'detail'})
 :'<div class="dq-list">'+rows+'<div class="dq-row dq-sum"><span>Total</span><strong id="dq-sum">'+E.money(mine.filter(m=>m.dayq!=='total').reduce((n,x)=>n+x.amount,0)+wideAmount)+'</strong></div></div>'+btn('day-cost-mode','Só sei o total','link',{mode:'total'}))
 +'</div>';}
function openDayCosts(totalOnly,keepDraft=false){if(!keepDraft)dayCostDraft={};openModal('Quanto custou estar aqui hoje?',dayQuestionsForm(totalOnly),'day-cost',null,btn('day-cost-save-all','Salvar e ver o lucro do dia','success modal-action')+btn('day-cost-cancel','Cancelar','sheet-back dq-cancel'));dialog.querySelector('.dialog-close')?.remove();dialog.setAttribute('data-no-close','');const sum=document.getElementById('dq-sum');if(sum)sum.textContent=E.money(dqSum());}
function cancelDayCosts(){dayCostDraft=null;closeNumberPad();openDaySummary(false);}
const closeModalBeforeDayCosts=closeModal;
closeModal=function(...args){if(dialog.open&&dialog.dataset.kind==='day-cost')return cancelDayCosts();return closeModalBeforeDayCosts(...args);};
dialog.addEventListener('cancel',event=>{if(dialog.dataset.kind!=='day-cost')return;event.preventDefault();event.stopImmediatePropagation();cancelDayCosts();},true);
function dqSum(){let n=0;document.querySelectorAll('dialog[open] .dq-input').forEach(i=>{const v=E.cents(i.value||'');if(Number.isFinite(v)&&v>0)n+=v;});document.querySelectorAll('dialog[open] [data-dq-fixed]').forEach(x=>n+=Number(x.dataset.dqFixed)||0);return n;}
document.addEventListener('input',event=>{if(!event.target.closest?.('.dq-form'))return;const out=document.getElementById('dq-sum');if(out)out.textContent=E.money(dqSum());});
Object.assign(actions,{
 'day-cost':()=>openDayCosts(dayQuestionData().mine.some(m=>m.dayq==='total')),
 'day-cost-cancel':()=>cancelDayCosts(),
 'day-cost-mode':d=>{dayCostDraft=dayCostDraft||{};document.querySelectorAll('dialog[open] [data-dq],dialog[open] #dq-total').forEach(input=>dayCostDraft[input.dataset.dq||'total']=input.value);openDayCosts(d.mode==='total',true);},
 'day-cost-save-all':()=>{const {day,mine}=dayQuestionData(),entries=[];const totalField=document.getElementById('dq-total');
  if(totalField){const v=E.cents(totalField.value||'');if(totalField.value.trim()&&!(Number.isFinite(v)&&v>=0))return toast('Informe um valor válido.');if(v>0)entries.push(['total','Custos do dia',v]);}
  else for(const [k,label] of DAY_QUESTIONS){const input=document.getElementById('dq-'+k);if(!input)continue;const raw=input.value.trim(),v=E.cents(raw||'0');if(raw&&!(Number.isFinite(v)&&v>=0))return toast('Confira o valor de '+label+'.');if(v>0)entries.push([k,label.replace(/ \(.*\)$/,''),v]);}
  const keep=model.data.expenses.filter(x=>!mine.includes(x)),added=entries.map(([k,title,amount])=>({id:E.uid(),title,amount,date:day+'T12:00:00-03:00',scope,customerType:'',category:'Operação',kind:'feira',dayq:k}));
  const prior=model.data.expenses;model.data.expenses=[...added,...keep];if(!persist()){model.data.expenses=prior;return toast('Não foi possível salvar.');}dayCostDraft=null;markDayClosed();toast(added.length?'Custos do dia salvos.':'Sem custos hoje.');render();openDaySummary(false);}
});
// No Resumo, os custos do dia viram um botão que abre as perguntas (com o total já lançado).
const daySummaryHtmlBeforeQuestions=daySummaryHtml;
daySummaryHtml=function(){return daySummaryHtmlBeforeQuestions().replace(/<button[^>]*data-action="day-cost"[^>]*>[\s\S]*?<\/button>/,()=>btn('day-cost',icon('plus')+' '+(dayQuestionData().mine.length?'Corrigir custos do dia':'Quanto custou estar aqui hoje?'),'ds-add'));};
// O Resumo também usa os custos rateados (evento de vários dias: cada dia mostra a sua parte).
const daySummaryDataBeforeEvents=daySummaryData;
daySummaryData=function(){const original=model.data.expenses;model.data.expenses=expandedExpenses();try{return daySummaryDataBeforeEvents();}finally{model.data.expenses=original;}};

// Esqueceu de criar o evento antes de vender? Se há evento hoje e as vendas de hoje foram na Loja,
// o Resumo oferece mover vendas e custos de hoje para o evento (um toque, com confirmação).
function eventTodayFor(){const day=E.dayKey(Date.now());return model.data.events.filter(e=>e.start<=day&&e.end>=day).sort((a,b)=>a.start.localeCompare(b.start))[0]||null;}
const daySummaryHtmlBeforeMove=daySummaryHtml;
daySummaryHtml=function(){const html=daySummaryHtmlBeforeMove(),day=E.dayKey(Date.now()),e=scope!=='loja'?model.data.events.find(v=>v.id===scope):eventTodayFor(),n=model.data.sales.filter(s=>s.status==='completed'&&(s.scope||'loja')==='loja'&&E.dayKey(s.date)===day).length;if(!e||!n)return html;return html+'<section class="fin-warn ds-move"><span class="fin-warn-dot" aria-hidden="true"></span><span class="fin-warn-text-body">'+(scope==='loja'?'Estas vendas foram na '+escape(e.name)+'?':'Hoje também há '+grammarCount(n,'venda','vendas')+' na Loja. Foram na '+escape(e.name)+'?')+'</span><span class="fin-warn-actions">'+btn('day-move-event','Mover para o evento','fin-warn-go',{id:e.id})+'</span></section>';};
actions['day-move-event']=d=>{const e=model.data.events.find(v=>v.id===d.id),day=E.dayKey(Date.now());if(!e)return;const sales=model.data.sales.filter(s=>(s.scope||'loja')==='loja'&&E.dayKey(s.date)===day),costs=model.data.expenses.filter(x=>(x.scope||'loja')==='loja'&&E.dayKey(x.date)===day);if(!d.confirmed)return openModal('Mover para o evento','<p class="dialog-text">Mover '+grammarCount(sales.length,'venda','vendas')+' e '+grammarCount(costs.length,'custo','custos')+' de hoje da Loja para '+escape(e.name)+'?</p>'+btn('day-move-event','Mover','success modal-action',{id:e.id,confirmed:'1'})+btn('sales-history','Cancelar','link'),'mg-detail');sales.forEach(s=>{s.scope=e.id;s.recipientType='EVENT';});costs.forEach(x=>x.scope=e.id);if(!persist())return toast('Não foi possível mover.');scope=e.id;toast('Vendas de hoje movidas para '+e.name+'.');render();openDaySummary();};
// Nomes em português: preposições e artigos no meio do nome ficam minúsculos ("Doce de Leite").
const titleNameBase=titleName;
titleName=function(value){return titleNameBase(value).replace(/(\s)(De|Da|Do|Das|Dos|E|Com|Em|Na|No|Nas|Nos|Por|Para|Sem|Ao|Aos|À|Às|A|O|Os|As)(?=\s)/g,(m,space,word)=>space+word.toLocaleLowerCase('pt-BR'));};
// Evento de um dia só: mostra a data uma vez.
const eventDetailBeforeDate=eventDetail;
eventDetail=function(id){eventDetailBeforeDate(id);const e=model.data.events.find(v=>v.id===id),p=document.querySelector('dialog[open] .dialog-text');if(e&&p&&e.start===e.end)p.innerHTML=p.innerHTML.replace(' a '+dateBR(e.end),'');};
// Agente persistente: a última pergunta e a resposta ficam guardadas no aparelho (voltam ao reabrir o app).
const runAIAnalysisBase=runAIAnalysis;
runAIAnalysis=async function(){const field=document.getElementById('ai-question');if(field)aiQuestion=field.value;await runAIAnalysisBase();if(aiResult){model.data.ai=model.data.ai||{};model.data.ai.last={question:aiQuestion,answer:aiResult,source:aiResultSource,stamp:aiResultStamp,at:new Date().toISOString()};persist();}};
(function restoreLastAnalysis(){const last=model.data.ai&&model.data.ai.last;if(!last||aiResult)return;aiQuestion=last.question||aiQuestion;aiResult=last.answer||'';aiResultSource=last.source||aiResultSource;aiResultStamp=last.stamp||aiResultStamp;})();
// --- Primeira abertura: o app começa zerado. Boas-vindas com nome, negócio, cidade e UF; "Começar do
// zero" é o caminho principal e "Ver com dados de exemplo" é opcional (apaga-se depois em Ajustes).
