document.addEventListener('input',event=>{if(event.target.id!=='stock-picker-search'||!productForm)return;stockProductFlow.search=String(event.target.value||'').slice(0,120);stockProductFlow.ownLimit=8;stockProductFlow.familyLimit=8;const results=document.getElementById('stock-picker-results');if(results)results.innerHTML=stockPickerResults();requestStockCatalog();});
// Native keyboards/autofill may commit with change only. Capture the visible
// values before validation and before a presentation redraw; explicit 0 stays 0.
function captureStockFormValues(){
 const f=productForm;if(!f)return;
 for(const [index,v] of f.variants.entries())for(const [prefix,key] of [['price','priceInput'],['cost','costInput'],['initial','stockInput'],['minimum','minInput']]){
  const el=document.getElementById(prefix+'-'+index);if(!el||el.readOnly)continue;
  v[key]=String(el.value??'');if(v[key].trim()!=='')numericTouched.add(el.id);
 }
}
document.addEventListener('change',event=>{const t=event.target;if(productForm&&t.dataset?.variant!==undefined&&['priceInput','costInput','stockInput','minInput'].includes(t.dataset.field))handleAppInput(event);});
const stockSaveProductBeforeFlow=actions['save-product'];
actions['save-product']=async d=>{
 const f=productForm;if(!f||f.saving)return;formError='';f.duplicateProductId='';
 try{
  if(f.pendingSaved){f.saving=true;const durable=window.TerritorioNative?.durable;if(durable&&!await durable())throw Error('A gravação ainda está pendente. Libere espaço; o app tenta novamente.');if(eventStockContext){await returnFromEventStock({saved:true});toast('Produto salvo. Incluído na preparação da feira.');return;}productForm=null;page='Estoque';filter='Todos';query='';render();toast('Produto salvo. Estoque atualizado.');return;}
  captureStockFormValues();if(stockNormalize(f.name).length<2)throw Error('Informe o nome do produto.');if(!f.category)throw Error('Escolha a categoria do produto.');
  for(const [index,v] of f.variants.entries()){
   if(!v.unit)throw Error('Escolha a unidade de venda.');
   if(!f.editId&&!v.unitConfirmed)throw Error('Confirme a unidade de venda sugerida ou escolha outra.');
   if(f.category==='Cafés'&&(!v.type||!v.format))throw Error('Escolha o tipo e o formato do café.');
   if(f.category==='Cafés'&&!(v.weight>0))throw Error('Informe o peso do café.');
   const option=f.variants.length>1?' na opção de venda '+(index+1):'';
   if(String(v.priceInput??'').trim()==='')throw Error('Informe o preço real'+option+'.');
   if(String(v.costInput??'').trim()===''&&(!f.editId||v.costKnown!==false))throw Error('Informe o custo real'+option+'. Se não houver custo, digite 0.');
   if(String(v.stockInput??'').trim()==='')v.stockInput='0';
   if(String(v.minInput??'').trim()==='')v.minInput='0';
   if(!f.editId)v.identityComplete=true;
  }
  f.saving=true;const dataBefore=JSON.stringify(model.data),draftBefore=eventLoadDraft&&JSON.stringify(eventLoadDraft);
  try{const saved=model.saveProducts(f,f.variants,f.editId);if(eventStockContext)stageStockForEvent(saved.filter(p=>!f.editId).map(p=>({productId:p.id,unit:p.unit,qty:p.stock})));if(!persist())throw Error('Não foi possível salvar. Libere espaço no dispositivo.');}
  catch(error){model=new E.ERPModel(JSON.parse(dataBefore));if(draftBefore)eventLoadDraft=JSON.parse(draftBefore);throw error;}
  f.pendingSaved=true;
  const durable=window.TerritorioNative?.durable;if(durable&&!await durable()){f.saving=false;formError='O aparelho ainda não confirmou a gravação. O app tenta novamente; não repita o cadastro.';f.pendingSaved=true;render();return;}
  if(eventStockContext){await returnFromEventStock({saved:true});toast('Produto salvo. Incluído na preparação da feira.');return;}
  productForm=null;page='Estoque';filter='Todos';query='';render();toast('Produto salvo. Estoque atualizado.');
 }catch(error){f.saving=false;if(error.code==='DUPLICATE_PRODUCT')f.duplicateProductId=error.productId;if(error.code==='INCOMPLETE_IDENTITY_REVIEW')f.reviewProductIds=error.candidates||[];formError=error.message;render();setTimeout(()=>document.getElementById('form-error')?.scrollIntoView({block:'center',behavior:model.data.settings.reduceEffects?'auto':'smooth'}),50);}
};
// A reposição usa a mesma movimentação e teclado. Só confirma depois de gravar;
// uma tentativa de gravação pendente não aplica a quantidade uma segunda vez.
actions['save-movement']=async()=>{
 const current=movement;if(!current||current.saving)return;current.saving=true;const save=document.querySelector('[data-action="save-movement"]');if(save)save.disabled=true;
 try{
  if(!current.pendingApplied){
   if(!current.raw.trim())throw Error('Informe a quantidade. Para zerar uma contagem, digite 0.');
   if(!/^\d+(?:[,.]\d{1,3})?$/.test(current.raw.trim()))throw Error('Use apenas uma quantidade válida, com até três casas decimais.');
   const before=JSON.stringify(model.data),draftBefore=eventLoadDraft&&JSON.stringify(eventLoadDraft);
   try{const record=model.move(current.id,current.kind,current.raw,current.note);if(current.eventId)record.eventId=current.eventId;
    if(eventStockContext){if(current.kind!=='add')throw Error('Use Repor para adicionar produtos à preparação da feira.');stageStockForEvent([{productId:current.id,unit:record.unit,qty:record.qty}]);record.preparedForEventId=eventStockContext.eventId;}
    if(!persist())throw Error('Não foi possível salvar. Libere espaço no dispositivo.');}
   catch(error){model=new E.ERPModel(JSON.parse(before));if(draftBefore)eventLoadDraft=JSON.parse(draftBefore);throw error;}
   current.pendingApplied=true;
  }
  if(window.TerritorioNative?.durable&&!await window.TerritorioNative.durable())throw Error('A gravação ainda está pendente. Libere espaço; o app tenta novamente. A quantidade não será aplicada de novo.');
  if(eventStockContext){await returnFromEventStock({saved:true});toast('Estoque atualizado. Quantidade incluída na preparação da feira.');return;}
  const eventId=current.eventId;closeModal();render();if(eventId)reviewEventLosses(eventId);toast('Movimentação registrada.');
 }catch(error){current.saving=false;if(save)save.disabled=false;const target=document.getElementById('move-error');if(target)target.innerHTML='<p class="error" role="alert">'+escape(error.message)+'</p>';else toast(error.message);}
};
// Preparação da feira: rascunho persistido por evento, separado da carga confirmada.
// Cadastrar/repor atualiza o estoque geral uma vez e volta ao mesmo rascunho.
const EP=()=>window.TerritorioEventPreparation;
let eventStockContext=null,eventPreparationTimer=null,eventPreparationClosing=false,eventStockOpening=false;
function preparationError(message){const target=document.getElementById('event-load-error');if(target){target.textContent=message;target.className=message?'error':'';}else if(message)toast(message);}
function updatePreparationSnapshot(){const d=eventLoadDraft,e=d&&model.data.events.find(e=>e.id===d.eventId);if(!e)return false;e.preparation=EP().snapshot(d);return true;}
function flushEventPreparation(){clearTimeout(eventPreparationTimer);eventPreparationTimer=null;if(!updatePreparationSnapshot())return false;if(!persist()){preparationError('Não foi possível guardar a preparação. Libere espaço e tente novamente.');return false;}return true;}
async function confirmPreparationDraft(){captureEventLoad();if(!flushEventPreparation())return false;const durable=window.TerritorioNative?.durable;if(durable&&!await durable()){preparationError('A preparação ainda não foi gravada no aparelho. Libere espaço e tente novamente.');return false;}return true;}
function preparationBusy(value){if(eventLoadDraft)eventLoadDraft.busy=value;dialog.querySelectorAll('[data-action="event-load-add"],[data-action="event-load-later"],[data-action="event-load-back"],[data-action="save-event-load"]').forEach(b=>b.disabled=value);dialog.querySelectorAll('[data-event-load-index],.el-clear').forEach(input=>input.disabled=value||!!eventLoadDraft?.pendingLoadSaved);}
startEventLoad=function(id){
 if(eventLoadDraft&&modal?.kind==='event-load'&&!eventLoadDraft.pendingLoadSaved){captureEventLoad();flushEventPreparation();}
 const events=model.data.events.slice().sort((a,b)=>b.start.localeCompare(a.start)),chosen=id?events.find(e=>e.id===id):(events.find(e=>e.status==='active')||events[0]);
 if(!chosen)return toast(id?'Este evento não está mais disponível.':'Crie um evento para registrar os produtos levados.');
 eventStockContext=null;eventLoadDraft=EP().createDraft(chosen,eventLoadProducts(chosen.id),eventLoad(chosen.id));paintEventLoad();
};
paintEventLoad=function(){
 const d=eventLoadDraft,e=d&&model.data.events.find(e=>e.id===d.eventId);if(!e)return;
 const rows=d.products.map((p,index)=>{const prod=model.product(p.productId),decimal=['kg','Litro','g','ml'].includes(p.unit);return '<div class="event-load-row el-has-clear numeric-field"><span><strong>'+escape(titleName(p.name))+'</strong><small>'+escape(p.description)+' · '+escape(E.unitLabel(p.unit,2))+'</small>'+(prod?'<small class="el-stock">no estoque: '+E.quantity(prod.stock)+'</small>':'')+'</span><label class="sr-only" for="event-load-'+index+'">Quantidade levada de '+escape(p.name+' '+p.description)+'</label><input id="event-load-'+index+'" data-event-load-index="'+index+'" inputmode="none" data-numeric="'+(decimal?3:0)+'" value="'+escape(p.raw)+'" placeholder="0"><button type="button" class="el-clear" data-clear-for="event-load-'+index+'" aria-label="Limpar quantidade de '+escape(p.name)+'">'+icon('backspace')+'</button></div>';}).join('');
 const footer=btn('save-event-load',d.pendingLoadSaved?'Confirmar gravação':'Salvar o que vou levar','success modal-action',null,!!d.busy)+btn('event-load-later','Adicionar depois','choice modal-action',null,!!d.busy)+btn('event-load-back',icon('back')+' Voltar','sheet-back',null,!!d.busy);
 openModal('O que vou levar','<p class="dialog-text event-load-help"><strong class="el-event">'+escape(e.name)+'</strong> · '+escape(dateBR(e.start))+'<br>Marque quanto vai levar. Use + para cadastrar ou repor um produto. Você também pode continuar depois.</p><div class="event-load-list">'+(rows||'<p class="event-load-empty">Seu estoque está vazio. Toque em + para adicionar um produto ou deixe a preparação para depois.</p>')+'</div><div id="event-load-error" role="status" aria-live="polite"></div>','event-load',{id:e.id},footer);
 dialog.querySelector('.checkout-header')?.insertAdjacentHTML('afterbegin','<button type="button" data-action="event-load-add" class="event-load-add round" aria-label="Adicionar produto ao estoque da feira"'+(d.busy?' disabled':'')+'>'+icon('plus')+'</button>');
};
async function leaveEventPreparation(){
 const d=eventLoadDraft;if(!d||d.busy)return;preparationBusy(true);
 try{if(d.pendingLoadSaved){if(window.TerritorioNative?.durable&&!await window.TerritorioNative.durable())throw Error('A gravação ainda está pendente. Libere espaço e tente novamente.');}else if(!await confirmPreparationDraft())return;
  const id=d.eventId;eventPreparationClosing=true;closeModal();eventPreparationClosing=false;eventLoadDraft=null;eventStockContext=null;page='Eventos';render();eventDetail(id);
 }catch(error){preparationError(error.message);}finally{eventPreparationClosing=false;if(eventLoadDraft===d)preparationBusy(false);}
}
async function addStockFromEvent(){
 const d=eventLoadDraft;if(!d||d.busy)return;preparationBusy(true);
 try{if(d.pendingLoadSaved){preparationError('Confirme a gravação antes de adicionar outro produto.');return;}if(!await confirmPreparationDraft())return;
  eventStockContext={eventId:d.eventId};eventPreparationClosing=true;closeModal();eventPreparationClosing=false;stockCreationTarget='general';eventStockOpening=true;startProduct();eventStockOpening=false;
 }catch(error){preparationError(error.message);}finally{eventPreparationClosing=false;eventStockOpening=false;if(modal?.kind==='event-load')preparationBusy(false);else d.busy=false;}
}
function stageStockForEvent(entries){
 const id=eventStockContext?.eventId,e=model.data.events.find(e=>e.id===id);if(!e)throw Error('Este evento não está mais disponível. Volte e escolha outro evento.');
 let d=eventLoadDraft?.eventId===id?eventLoadDraft:EP().createDraft(e,eventLoadProducts(id),eventLoad(id));d=EP().mergeProducts(d,eventLoadProducts(id));eventLoadDraft=EP().addStockEntries(d,entries);e.preparation=EP().snapshot(eventLoadDraft);
}
async function returnFromEventStock({saved=false}={}){
 const id=eventStockContext?.eventId;if(!id)return;
 if(!saved&&(productForm?.saving||movement?.saving))throw Error('Aguarde a confirmação da gravação antes de voltar.');
 if((productForm?.pendingSaved||movement?.pendingApplied)&&window.TerritorioNative?.durable&&!await window.TerritorioNative.durable())throw Error('A gravação ainda está pendente. Libere espaço; a quantidade não será aplicada de novo.');
 eventStockContext=null;eventPreparationClosing=true;closeModal();eventPreparationClosing=false;productForm=null;stockCreationTarget='general';page='Eventos';render();startEventLoad(id);
}
saveEventLoad=async function(){
 const d=eventLoadDraft;if(!d||d.busy)return;captureEventLoad();preparationBusy(true);
 try{
  if(!d.pendingLoadSaved){
   const items=[];for(const p of d.products){const value=String(p.raw).trim(),qty=value===''?0:E.number(value);if(value!==''&&!/^\d+(?:[.,]\d{1,3})?$/.test(value)||!Number.isFinite(qty)||qty<0||!['kg','Litro','g','ml'].includes(p.unit)&&!Number.isInteger(qty))throw Error('Informe uma quantidade válida de '+p.name+'. Use até três casas decimais para kg e litros.');if(qty>0)items.push({productId:p.productId,name:p.name,description:p.description,unit:p.unit,qty});}
   const shortfall=eventSoldQuantities(d.eventId).find(s=>s.qty>(items.find(i=>i.productId===s.productId&&i.unit===s.unit)?.qty||0));if(shortfall)throw Error('O total levado de '+shortfall.name+' deve cobrir as '+E.quantity(shortfall.qty)+' '+E.unitLabel(shortfall.unit,shortfall.qty)+' já vendidas nessa feira.');
   const e=model.data.events.find(e=>e.id===d.eventId);if(!e)throw Error('Este evento não está mais disponível.');
   const before=JSON.stringify(model.data),old=eventLoad(d.eventId),stamp=new Date().toISOString(),sold=model.data.sales.some(s=>s.scope===d.eventId&&s.status==='completed');
   items.forEach(i=>{const prev=old?.items.find(p=>p.productId===i.productId&&p.unit===i.unit),restocks=(prev?.restocks||[]).slice(),diff=Math.round((i.qty-(prev?.qty||0))*1000)/1000;if(sold&&old&&diff>0)restocks.push({at:stamp,qty:diff});let extra=restocks.reduce((n,r)=>n+r.qty,0);while(restocks.length&&extra>i.qty)extra-=restocks.pop().qty;if(restocks.length)i.restocks=restocks;});
   model.data.eventLoads=[...(model.data.eventLoads||[]).filter(l=>l.eventId!==d.eventId),{eventId:d.eventId,createdAt:old?.createdAt||stamp,updatedAt:stamp,items}];delete e.preparation;
   if(!persist()){model=new E.ERPModel(JSON.parse(before));throw Error('Não foi possível salvar as quantidades. Libere espaço e tente novamente.');}d.pendingLoadSaved=true;
  }
  if(window.TerritorioNative?.durable&&!await window.TerritorioNative.durable())throw Error('O aparelho ainda não confirmou a gravação. Tente novamente; as quantidades não serão duplicadas.');
  const id=d.eventId;eventPreparationClosing=true;closeModal();eventPreparationClosing=false;eventLoadDraft=null;eventStockContext=null;managementScope=id;managementDays.clear();managementHours={from:'',until:''};page='Eventos';render();eventDetail(id);toast('Produtos levados registrados.');
 }catch(error){preparationError(error.message);}finally{eventPreparationClosing=false;if(eventLoadDraft===d){preparationBusy(false);const save=dialog.querySelector('[data-action="save-event-load"]');if(save)save.textContent=d.pendingLoadSaved?'Confirmar gravação':'Salvar o que vou levar';}}
};
const closeModalBeforePreparation=closeModal;
closeModal=function(skipSaleCapture){if(!eventPreparationClosing&&modal?.kind==='event-load'){void leaveEventPreparation();return;}if(!eventPreparationClosing&&eventStockContext&&modal?.kind==='movement'){void returnFromEventStock().catch(error=>toast(error.message));return;}return closeModalBeforePreparation(skipSaleCapture);};
const startProductBeforePreparation=startProduct;
startProduct=function(id){if(eventStockContext&&!eventStockOpening)eventStockContext=null;return startProductBeforePreparation(id);};
const paintMovementBeforePreparation=paintMovement;
paintMovement=function(){paintMovementBeforePreparation();if(!eventStockContext)return;const e=model.data.events.find(e=>e.id===eventStockContext.eventId);dialog.querySelector('.movement-types')?.remove();dialog.querySelector('.movement-secondary')?.remove();dialog.querySelector('.dialog-close')?.remove();dialog.querySelector('.dialog-content')?.insertAdjacentHTML('afterbegin','<p class="event-stock-context">Para '+escape(e?.name||'a feira')+'</p>');dialog.querySelector('.checkout-footer')?.insertAdjacentHTML('beforeend',btn('event-stock-back',icon('back')+' Voltar para a feira','sheet-back'));const save=dialog.querySelector('[data-action="save-movement"]');if(save)save.textContent='Adicionar ao estoque e à feira';};
const cancelProductBeforePreparation=actions['cancel-product'],stockBackBeforePreparation=actions['stock-product-back'],navBeforePreparation=actions.nav,duplicateEditBeforePreparation=actions['duplicate-existing-edit'];
Object.assign(actions,{
 'event-load-add':()=>addStockFromEvent(),'event-load-later':()=>leaveEventPreparation(),'event-load-back':()=>leaveEventPreparation(),'save-event-load':()=>saveEventLoad(),
 'event-stock-back':()=>returnFromEventStock(),
 'cancel-product':()=>eventStockContext?returnFromEventStock():cancelProductBeforePreparation(),
 'stock-product-back':()=>eventStockContext?returnFromEventStock():stockBackBeforePreparation(),
 'duplicate-existing-edit':d=>eventStockContext?pickOwnStockProduct(d.id):duplicateEditBeforePreparation(d),
 nav:d=>{if(eventStockContext){eventStockContext=null;productForm=null;stockCreationTarget='general';}return navBeforePreparation(d);}
});
const eventLoadCardBeforePreparation=eventLoadCard;
eventLoadCard=function(e){const pending=e.preparation?.status==='pending',html=eventLoadCardBeforePreparation(e);if(!loadSummary(e).length&&e.status==='finished')return '<section class="ds-card el-card"><h3>Estoque do Evento</h3><p class="ds-note">Nenhuma carga registrada neste evento.</p></section>';if(!loadSummary(e).length)return '<section class="ds-card el-card"><h3>Estoque do Evento</h3><p class="ds-note">'+(pending?'Sua preparação está guardada. Continue quando estiver com os produtos.':'Adicione os produtos agora ou prepare a carga depois, quando estiver com seu estoque.')+'</p>'+btn('event-load',pending?'Continuar preparação':'Adicionar produtos','choice modal-action',{id:e.id})+'</section>';return pending?html.replace(/>(Alterar|Repor ou corrigir)<\/button>/,'>Continuar preparação</button>'):html;};
document.addEventListener('input',event=>{if(modal?.kind!=='event-load'||event.target.dataset?.eventLoadIndex===undefined||eventLoadDraft?.pendingLoadSaved)return;updatePreparationSnapshot();clearTimeout(eventPreparationTimer);eventPreparationTimer=setTimeout(()=>{eventPreparationTimer=null;if(!persist())preparationError('Não foi possível guardar a preparação. Libere espaço antes de sair.');},240);});
window.addEventListener('beforeunload',()=>{if(eventPreparationTimer&&eventLoadDraft&&!eventLoadDraft.pendingLoadSaved)flushEventPreparation();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&eventPreparationTimer&&eventLoadDraft&&!eventLoadDraft.pendingLoadSaved)flushEventPreparation();});
