 if(page==='Produto'&&productForm&&!eventStockContext){captureStockFormValues();const value=JSON.parse(JSON.stringify(productForm));delete value.saving;delete value.pendingSaved;return{kind:'product',value,flow:JSON.parse(JSON.stringify(stockProductFlow))};}
