 if(form.kind==='product'&&Array.isArray(v.variants)&&v.variants.length&&(!v.editId||model.product(v.editId))){productForm=v;stockProductFlow={...stockProductFlow,...form.flow,stage:'form',loading:false};productNamePrefix='';stockCreationTarget=v.stockGroup||'general';numericTouched.clear();page='Produto';render();}
